INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(9831, 'plPL', 'Wejście do Karazhanu', 'Wieści z tego raportu bardzo mnie niepokoją, $N. Dostanie się do Karazhanu nie będzie jednak łatwe.$B$BWidzisz, gdy stało się jasne, że utknąłem tutaj na dobre, podzieliłem klucz na trzy fragmenty.$B$BUmieściłem je w zaczarowanych pojemnikach, a te z kolei ukryłem w miejscach, które wówczas były bezpieczne.$B$BPo mrocznych zmianach, jakie przeszła Rubież, już tak nie jest. Pierwszy fragment znajduje się w części Auchindoun opanowanej przez Radę Cieni. Przynieś mi go.', 'Khadgar chce, abyś $gwszedł:weszła; do Labiryntu Cieni w Auchindoun i $gwydobył:wydobyła; pierwszy fragment klucza z ukrytego tam tajemnego pojemnika.', '', 'Wróć do Khadgara w Dolnym Mieście w Shattrath.', '', '', '', '', 0),
(9832, 'plPL', 'Drugi i trzeci fragment', 'Drugi fragment ukryłem na dnie Wężowego Jeziora, na długo zanim zaczęto je tak nazywać. Olbrzymi odpływ, który nagi zbudowały tam po przejęciu jeziora, zapewne wciągnął pojemnik w głąb Zbiornika Żmijokolców.$B$BTrzeci fragment będzie najtrudniej zdobyć, bo zostawiłem go w Twierdzy Burz, kiedy jeszcze władali nią naaru. Teraz rządzi nią Kael\'thas, a komnata, w której go zostawiłem, stała się więzieniem.$B$BPrzynieś mi pozostałe fragmenty, $N. Wiele zależy od twojego powodzenia.', 'Zdobądź drugi fragment klucza z tajemnego pojemnika w Zbiorniku Żmijokolców i trzeci fragment klucza z tajemnego pojemnika w Twierdzy Burz. Po wykonaniu zadania wróć do Khadgara w Shattrath.', '', 'Wróć do Khadgara w Dolnym Mieście w Shattrath.', '', '', '', '', 0),
(9836, 'plPL', 'Dotyk mistrza', 'Złożyłem z powrotem ten sam klucz, którego używałem jako uczeń. Jak na klucz, wygląda na całkowicie sprawny. Jeśli jednak chodzi o otwarcie Karazhanu, równie dobrze mógłby być kawałkiem złomu.$B$BBez zgody Medivha klucz jest bezwartościowy. Tak, oczywiście wiem, że Medivh nie żyje. To tylko utrudnia sprawę, a nie czyni jej niemożliwą.$B$BW Azeroth jest miejsce zwane Jaskiniami Czasu, strzeżone przez Brązowe Stado. Znajdź sposób, by się tam dostać, cofnij się w czasie i skłoń Medivha, by aktywował klucz.', 'Wejdź do Jaskiń Czasu i przekonaj Medivha, by aktywował twój odnowiony klucz ucznia.', 'Dotyk mistrza', '', '', '', '', '', 0),
(9837, 'plPL', 'Powrót do Khadgara', 'Zdaje się, że pamiętam przyszłe wydarzenia związane z tobą i tym kluczem.$B$B<Medivh patrzy na ciebie, jakby właśnie zobaczył ducha.>$B$BCzekają cię ciężkie próby, $N. Miejmy nadzieję, że nie zabraknie ci sił.$B$BCo do klucza – mam go wręczyć Khadgarowi, gdy zostanie do mnie przysłany. Nie mógłbym sobie życzyć lepszego ucznia.$B$BZapewne potrzebujesz własnego klucza.$B$B<Medivh sięga pod szatę i wręcza ci swój własny klucz.>$B$BRuszaj więc. I powodzenia, $N.', 'Wróć do Khadgara w Shattrath i pokaż mu Klucz Mistrza.', '', '', '', '', '', '', 0),
(9968, 'plPL', 'Dziwna energia', 'Coś dziwnego odmieniło teroćmy z gąszczu.$B$BKiedyś panowała tam różnorodność życia, a teraz zostały tylko teroćmy. Dawniej były spokojne, teraz są pobudzone i bez wahania zaatakują, jeśli podejdziesz za blisko.$B$BMuszę porównać te okrutne ze zwykłymi. Zbierz dla mnie trochę próbek jednych i drugich. Nietknięte teroćmy znajdziesz zarówno na południu, jak i na północy.$B$BJestem pewien, że ma to związek z tym, co zabiło wszystkich druidów.', 'Zbierz 4 próbki teroćmy i 4 próbki okrutnej teroćmy. Potem wróć do Wiążącego ziemię Tavgrena, tuż przed Gąszczem Cenariona w Puszczy Terokkar.', '', 'Wróć do wiążącego ziemię Tavgrena tuż przed Gąszczem Cenariona w Puszczy Terokkar.', '', '', '', '', 0),
(9971, 'plPL', 'Poszlaki w gąszczu', 'Nie mam pojęcia, co zabiło tutejszych druidów. Przez kilka dni mnie nie było, badałem Kościane Pustkowia na południu.$B$BProszę, musisz mi pomóc odkryć, co stoi za tą straszną tragedią. Wejdź do gąszczu i poszukaj jakiejś poszlaki, która mogłaby nam coś wyjaśnić. Kiedy byłem tam przez chwilę, mógłbym przysiąc, że widziałem martwego Złamanego, a obok niego dziwny przedmiot.$B$BI nie przejmuj się Treelosem – to, co się stało, mogło doprowadzić go do obłędu, ale myślę, że jest raczej niegroźny.', 'Zbadaj dziwny przedmiot obok zwłok Złamanego, żeby ustalić, co mogło spotkać Gąszcz Cenariona. Potem wróć do Wiążącego ziemię Tavgrena, tuż przed gąszczem w Puszczy Terokkar.', '', 'Wróć do wiążącego ziemię Tavgrena tuż przed Gąszczem Cenariona w Puszczy Terokkar.', 'Dziwny przedmiot zbadany', '', '', '', 0),
(9979, 'plPL', 'Handlarz wiatru Lathrai', 'Poproszono mnie, żebym odebrał od pewnego eteryka w Shattrath kilka pudełek z towarami i je dostarczył.$B$BKiedy ostatnio go widziałem, stał przed tawerną „Koniec Świata” w Dolnym Mieście. Nazywa się Handlarz wiatru Lathrai i to wszystko, co wiem!$B$BChcesz wiedzieć więcej, idź z nim pogadać!', 'Porozmawiaj z handlarzem wiatru Lathraiem przy tawernie „Koniec Świata” w Dolnym Mieście w Shattrath.', '', '', '', '', '', '', 0),
(9990, 'plPL', 'Zbadaj Tuurem', 'Wiesz, teraz, kiedy się nad tym zastanawiam, przypominam sobie, że jakiś miesiąc temu Empoor kupił ode mnie kilka pudełek dziwnych, egzotycznych części mechanicznych. Nie wiem, do czego miałyby służyć, ale wiem, że dostarczono je do Tuurem.$B$BMoże któreś z tych pudełek wciąż tam jest?', 'Znajdź zapieczętowane pudełko, a następnie dostarcz je wiążącemu ziemię Tavgrenowi tuż przed Gąszczem Cenariona w Puszczy Terokkar.', '', 'Wróć do wiążącego ziemię Tavgrena tuż przed Gąszczem Cenariona w Puszczy Terokkar.', '', '', '', '', 0),
(10004, 'plPL', 'Cierpliwość i zrozumienie', 'Weź plany i udaj się do Shattrath w Puszczy Terokkar. Na miejscu idź do Dolnego Miasta i poszukaj mo\'arga o imieniu Sal\'salabim. Pewnie będzie przy barze, topiąc smutki w kieliszku.$B$BPrzy okazji: być może trzeba go będzie przekonać, żeby ci pomógł. Spróbuj podejść do niego z cierpliwością i zrozumieniem. Jeśli to nie zadziała, użyj pięści.', 'Altruis Cierpiący z zachodniego Nagrandu chce, abyś $gzaniósł:zaniosła; plany głównego planisty Sal\'salabimowi w Shattrath i $gprzekonał:przekonała; go do pomocy.$B', 'Sal\'salabim przekonany', '', '', '', '', '', 0),
(10009, 'plPL', 'Rozbijanie łbów', '<Sal\'salabim się śmieje.>$B$BTo projekt Sal\'salabima.$B$B<Sal\'salabim wskazuje na architekturę i układ budowli na planach.>$B$BPatrz na wieże. Łowca demonów nie widzieć, tak? Biedny, biedny Altruis. On płakać, gdyby miał oczy, tak?$B$BTak, Sal\'salabim pomóc, ale najpierw ty pomóc Sal\'salabim.$B$B<Sal\'salabim daje ci księgę rachunkową.>$B$BTe stwory winne Sal\'salabim złoto. Dużo złoto. Idź zebrać dla Sal\'salabim i wracaj. Oni nie oddać ci złoto Sal\'salabim łatwo. Trzeba walczyć, ale ty mieć siła. Ty pokonać Sal\'salabim!', 'Sal\'salabim w Shattrath chce, abyś $godzyskał:odzyskała; dług Raliqa, dług Coosh\'coosha i dług Floona.', '', 'Wróć do Sal\'salabima w Shattrath w Puszczy Terokkar.', '', '', '', '', 0),
(10010, 'plPL', 'Takie to proste?', '<Sal\'salabim wskazuje na plany.>$B$BWidzisz, gdzie są spaczone działa?$B$B<Sal\'salabim rysuje strzałkę oznaczającą zmianę kierunku.>$B$BTy obrócić spaczone działo i strzelać w budowle.$B$BCzekaj! Nie złościć się! Jednej rzeczy ty nie wiedzieć. Nadzorcy mieć klucz do obracania dział. Najpierw trzeba klucz! Jeden od każdego nadzorcy!$B$BNie tak łatwo, co?$B$BZanieś te informacje Altruisowi.$B', 'Sal\'salabim w Shattrath chce, abyś $gwrócił:wróciła; do Altruisa Cierpiącego w zachodnim Nagrandzie.', '', '', '', '', '', '', 0),
(10017, 'plPL', 'Nadwątlone zapasy', 'Każdego dnia przez bramy Shattrath przybywa coraz więcej uchodźców. Niektórzy odnieśli takie rany, że to prawdziwy cud, iż w ogóle tu dotarli.$B$BZ większością zwykłych obrażeń sobie radzę – szkolenie uzdrowicielki Aldorów mnie do tego przygotowało. Zatrute rany to większy problem, bo kończą mi się zapasy odtrutki.$B$BPrzynieś mi worki jadowe miejscowych straszliwokłych pająków, żebym mogła przygotować więcej odtrutek. Skupisko tych pająków znajdziesz w południowo-wschodniej części Puszczy Terokkar.', 'Przynieś 8 worków jadowych straszliwokłego czyhacza Sha\'nir w Shattrath.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', 'Wróć do Sha\'nir w Puszczy Terokkar.', '', '', '', '', 0),
(10019, 'plPL', 'Więcej worków jadowych', '', '', '', 'Wróć do Sha\'nir na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(10020, 'plPL', 'Lekarstwo dla Zahlii', 'Kobieta po mojej prawej doznała ciężkiego urazu głowy. Przeżyła, ale straciła wzrok.$B$BTradycyjne lekarstwo stosowane przez mój lud wymaga krwi bardzo starego bazyliszka.$B$BNiestety, przez kłusownictwo różnych grup bazyliszki w Puszczy Terokkar rzadko dożywają sędziwego wieku.$B$BJest jednak jeden bazyliszek, którego imię znam, odkąd byłam dzieckiem. Mówią na niego po prostu „Kamiennooki” i podobno żyje na wschód stąd, blisko krawędzi lądu.$B$BPrzynieś mi jego krew, aby Zahlia znów mogła widzieć.', 'Przynieś krew Kamiennookiego Sha\'nir w Shattrath.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', 'Wróć do Sha\'nir w Puszczy Terokkar.', '', '', '', '', 0),
(10021, 'plPL', 'Przywrócenie Światła', 'Dawno temu region ten zamieszkiwali w dużej mierze draenei. Nam, Aldorom, powierzono pieczę nad naszymi świętymi miejscami i ołtarzami. Wiele z nich zostało od tamtej pory zniszczonych lub zajętych przez naszych wrogów.$B$BNa wschód stąd znajduje się placówka arakkoa. Celowo zbudowano ją w miejscu trzech naszych świętych ołtarzy. Arakkoa używają swojej plugawej magii, by wypaczać i bezcześcić wrodzoną moc naszych kapliczek.$B$BWeź to, udaj się do placówki arakkoa i oczyść tym trzy ołtarze.', 'Ishanah chce, abyś $gudał:udała; się do placówki arakkoa na wschód od Shattrath i $guzył:użyła; pobłogosławionej fiolki, by oczyścić wschodni ołtarz, zachodni ołtarz i północny ołtarz.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', 'Wróć do Ishanah na Wzniesieniu Aldorów w Shattrath.', '', '', '', '', 0),
(10024, 'plPL', 'Wizje Voren\'thala', 'Nasz przywódca, Voren\'thal Jasnowidz, był niegdyś bliskim doradcą Kael\'thasa. Prorocze wizje ostrzegły go, że droga Kaela doprowadzi do zagłady naszej rasy.$B$BWizje są zwykle mgliste i nieostre, ale nasi alchemicy opracowali eliksir, który pomaga mu skupić jasnowidzenie. Niestety, eliksir wymaga rzadkiego składnika: oczu bazyliszka. Mój stały dostawca, ten żałosny eteryk, zawiódł mnie.$B$BOdszukaj wilgotnołuskie bazyliszki w skalistych rejonach Puszczy Terokkar i przynieś mi ich oczy.', 'Przynieś 8 oczu wilgotnołuskiego bazyliszka arkanistce Adyrii w Shattrath.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', '', 'Wróć do arkanistki Adyrii w Shattrath.', '', '', '', '', 0),
(10025, 'plPL', 'Więcej oczu bazyliszka', '', '', '', 'Wróć do arkanistki Adyrii na Półwyspie Piekielnego Ognia.', '', '', '', '', 0),
(10037, 'plPL', 'Wolałbym iść na ryby', 'Skoro mowa o jeziorach, na północnym wschodzie jest jezioro, gdzie świetnie biorą ryby. Chodziłem tam z kolegami, ale mama już mnie nie puszcza.$B$BMówi, że to za niebezpieczne, ale nie widziałem tam nic oprócz paru małych pająków. Jakby pająki mogły komuś coś zrobić...$B$BNajbardziej lubiłem węgorze, które tam żyją. Jak będziesz w okolicy jeziora, może przyniesiesz mi trochę węgorzy? Są zadziorne, ale jak już je poskromisz, bez problemu je przyniesiesz.', 'Przynieś 8 nieskazitelnych migotliwołuskich węgorzy Sethowi w Shattrath.', '', 'Wróć do Setha w Dolnym Mieście w Shattrath.', '', '', '', '', 0),
(10038, 'plPL', 'Porozmawiaj z szeregowym Weeksem', 'Właśnie dotarł raport od jednego z naszych zwiadowców przy Wiosce Grangol\'var. Twierdzi, że w tamtejszych ruinach zadomowiła się jakaś mroczna banda.$B$B$N, chcę, żebyś $gporozmawiał:porozmawiała; z szeregowym Weeksem i $gsprawdził:sprawdziła;, jak możesz mu pomóc ustalić, co knuje ta nieznana grupa. Idź na zachód, za Warownię Kamieniołamaczy. Według ostatniego raportu jest przy północnym wejściu do wioski.', 'Porozmawiaj z szeregowym Weeksem przy północnym wejściu do Wioski Grangol\'var w Puszczy Terokkar.', '', '', '', '', '', '', 0),
(10040, 'plPL', 'Kim oni są?', 'Nie wiem, kim są, ale wiem, że są wrodzy!$B$BDam ci przebranie. Chcę, żebyś tam $gposzedł:poszła; i $gpogadał:pogadała; z trzema z nich, którzy według moich obserwacji są „gadatliwi”. Porozmawiaj z nowicjuszem, robotnikiem i doradcą.$B$BTylko uważaj: jest tam kilku łowców, którzy przejrzą twoje przebranie, a wyglądają groźnie! I cokolwiek zrobisz, nie opuszczaj wioski – przebranie jest dość liche. Jeśli je stracisz, wróć do mnie, a dam ci nowe.', 'W przebraniu porozmawiaj z cienistym nowicjuszem, cienistym robotnikiem i cienistym doradcą. Następnie wróć do szeregowego Weeksa w Wiosce Grangol\'var w Puszczy Terokkar.', '', 'Wróć do szeregowego Weeksa w Wiosce Grangol\'var w Puszczy Terokkar.', 'Rozmowa z cienistym nowicjuszem', 'Rozmowa z cienistym robotnikiem', 'Rozmowa z cienistym doradcą', '', 0),
(10041, 'plPL', 'Kim oni są?', 'Nie wiem, kim są, ale wiem, że są wrodzy!$B$BDam ci przebranie. Chcę, żebyś tam $gposzedł:poszła; i $gpogadał:pogadała; z trzema z nich, którzy według moich obserwacji są „gadatliwi”. Porozmawiaj z nowicjuszem, robotnikiem i doradcą.$B$BTylko uważaj: jest tam kilku łowców, którzy przejrzą twoje przebranie, a wyglądają groźnie! I cokolwiek zrobisz, nie opuszczaj wioski – przebranie jest dość liche. Jeśli je stracisz, wróć do mnie, a dam ci nowe.', 'W przebraniu porozmawiaj z cienistym nowicjuszem, cienistym robotnikiem i cienistym doradcą. Potem wróć do Zwiadowczyni Neftis w Wiosce Grangol\'var w Puszczy Terokkar.', '', 'Wróć do Zwiadowczyni Neftis w Wiosce Grangol\'var w Puszczy Terokkar.', 'Rozmowa z cienistym nowicjuszem', 'Rozmowa z cienistym robotnikiem', 'Rozmowa z cienistym doradcą', '', 0),
(10042, 'plPL', 'Wybij Radę Cieni!', 'Co?! Ci goście to Rada Cieni?!$B$B$N, musisz tam wrócić i ich wykończyć! Chcę, żebyś $gzlikwidował:zlikwidowała; ich przywódcę i tylu katów i przywoływaczy, ilu tylko zdołasz.$B$BGdy z tym skończysz, złóż raport porucznikowi Żwiromłotowi w Forcie Alleriańskim.$B$BPowodzenia, $N!', 'Zabij 10 cienistych katów, 10 cienistych przywoływaczy i mistrza cieni Grieve\'a, a następnie wróć do porucznika Żwiromłota w Forcie Alleriańskim w Puszczy Terokkar.', '', 'Wróć do porucznika Żwiromłota w Forcie Alleriańskim w Puszczy Terokkar.', '', '', '', '', 0),
(10043, 'plPL', 'Wybij Radę Cieni!', 'Co?! Ci goście to Rada Cieni?!$B$B$N, musisz tam wrócić i ich wykończyć! Masz zabić ich przywódcę i tylu katów i przywoływaczy, ilu zdołasz.$B$BKiedy już z tym skończysz, zgłoś się do Doradczyni Faili w Warowni Kamieniołamaczy.$B$BPowodzenia, $N!', 'Zabij 10 cienistych katów, 10 cienistych przywoływaczy i Mistrza cieni Grieve\'a, a potem wróć do Doradczyni Faili w Warowni Kamieniołamaczy w Puszczy Terokkar.', '', 'Wróć do Doradczyni Faili w Warowni Kamieniołamaczy w Puszczy Terokkar.', '', '', '', '', 0),
(10091, 'plPL', 'Urządzenia duszy', 'Ach! Torturowali mnie, próbując wyciągnąć ze mnie wszystko, co wiem.$B$BZawiodłem – innych rzucili na pożarcie Piekielnej Paszczy, a ja miałem być następny. Ale nic im nie powiedziałem!$B$BTo szaleńcy! Za wszelką cenę chcą przyzwać demoniczne siły, nad którymi nie mają żadnej kontroli!$B$BUżywają specjalnych urządzeń, by wzmocnić swoje odłamki dusz i przyzwania. Musisz ukraść te urządzenia!$B$BPoszedłbym z tobą, ale muszę wrócić do Shattrath i złożyć raport mistrzyni szpiegów Dolnego Miasta.', 'Ukradnij 5 urządzeń duszy i dostarcz je mistrzyni szpiegów Mehlisah Wysokiej Koronie na Tarasie Światła w Shattrath.', '', 'Wróć do mistrzyni szpiegów Mehlisah Wysokiej Korony na Wzniesieniu Aldorów w Shattrath.', '', '', '', '', 0),
(10095, 'plPL', 'W serce Labiryntu', 'Rada Cieni straciła kontrolę nad kosmiczną istotą, którą przyzwała tu prawie dwa lata temu! To ona spowodowała eksplozję Auchindoun i powstanie leżących za nim Kościanych Pustkowi.$B$BIstota znana jedynie jako Szmer grozi, że przytłoczy Radę Cieni i wyrwie się na zewnątrz!$B$BSkoro arcymistrz i reszta ich przywódców nie żyją, jesteś ostatnią nadzieją Rubieży w walce z tym potworem!$B$B$N, wiesz w głębi duszy, że ty i twoi towarzysze nie możecie zawieść!', 'Zniszcz Szmera i powiadom mistrzynię szpiegów Mehlisah Wysoką Koronę na Tarasie Światła w Shattrath o wydarzeniach w Labiryncie Cieni.', '', 'Wróć do mistrzyni szpiegów Mehlisah Wysokiej Korony na Wzniesieniu Aldorów w Shattrath.', '', '', '', '', 0),
(10102, 'plPL', 'Sekret ujawniony', 'Gdy przez stulecia moja energia powoli uchodziła, na moim miejscu rosła pustka, pożerająca dusze wszystkich w pobliżu. Na moich oczach, wbrew mej woli, pokolenia orczych dusz były wciągane w wir. Niedawno moi wrogowie ujarzmili ten wir i użyli go, by wciągnąć niezliczone sługi pustki do swojego Płonącego Legionu.$B$BTeraz klucz do przerwania tego cyklu i uwolnienia duchów orków leży u innego naaru – A\'dala. Wyczuwam jego esencję w starożytnym mieście Shattrath w Puszczy Terokkar.', 'Porozmawiaj z A\'dalem w Shattrath.', '', '', '', '', '', '', 0),
(10112, 'plPL', 'Osobista przysługa', 'Hmmm? Pudełko, mówisz? A może kilka? Wiesz, z jakiego materiału było zrobione?$B$BA jak nazywał się ten kupiec? Empoor? Na pewno jest jednym ze Złamanych? Rzadko robię interesy z takimi jak oni.$B$BMoże pamięć by mi się poprawiła, gdybyś $gwyświadczył:wyświadczyła; mi przysługę?$B$BArakkoa ze Skith – ci prymitywni czarownicy – niedawno ukradli ogromną dostawę moich bardziej egzotycznych towarów. Chcę odzyskać wszystko!$B$BZasłonę Skith znajdziesz tuż na południe od Shattrath.', 'Odzyskaj 5 kradzionych towarów Lathraia. Zwróć je handlarzowi wiatru Lathraiowi przy tawernie „Koniec Świata” w Dolnym Mieście w Shattrath.', '', 'Wróć do handlarza wiatru Lathraia w Dolnym Mieście w Shattrath.', '', '', '', '', 0),
(10167, 'plPL', 'Auchindoun...', 'W głębi Krypt Auchenai znajduje się grobowiec, jakiego nie ma nigdzie indziej w tej strzaskanej krainie. To z tego grobowca, pierwszego grobowca, zrodziło się ogromne mauzoleum Auchindoun.$B$BMusisz udać się do Krypt Auchenai w Auchindoun i odnaleźć ten grobowiec. Zabij strażnika krypty, by uwolnić uwięzionego w niej ducha. To duch ma klucz...', 'Udaj się do Krypt Auchenai na Kościanych Pustkowiach w Puszczy Terokkar i zabij egzarchę Maladaara, aby uwolnić ducha D\'ore.$B', '', 'Wróć do D\'ore na Wzgórzu Darrow w Międzygórzu.', '', '', '', '', 0),
(10169, 'plPL', 'Przegrywać z godnością', 'Aldorowie zyskali dziś przychylność Sha\'tar. Jakby to mogło kogokolwiek zaskoczyć!$B$BPopatrz, jak popisują się swoją musztrą ledwie parę kroków od A\'dala. Czy mogliby jeszcze bardziej podlizywać się naaru?$B$BOddział strzelców zwiastuna Haronema jest tak oddany, że nawet przynosi własny kociołek, żeby nie robić długich przerw na obiad. To nie może ujść im na sucho, $N.$B$BChcę, żebyś $gwlał:wlała; zawartość tej fiolki do ich posiłku. Efekt powinien być... komiczny.', 'Magister Falris w Shattrath chce, abyś $gzaniósł:zaniosła; fiolkę surowicy uspokajającej na Taras Światła i $gwlał:wlała; ją do kociołka oddziału Haronema.', '', '', '', '', '', '', 0),
(10177, 'plPL', 'Kłopoty w Auchindoun', 'Mam szpiegów w Auchindoun i przysyłają mi niepokojące raporty. Od wybuchu parę lat temu to miejsce przynosi same kłopoty.$B$BCoś tam poszło straszliwie nie tak – znowu – i Rada Cieni jest teraz w stanie gotowości bojowej. Choć raportom brakowało szczegółów, jej przygotowania wydają się skierowane do wewnątrz.$B$BMusisz dotrzeć do wejścia do Labiryntu Cieni. Mój dowódca polowy, Mahfuun, wyjaśni ci, co trzeba zrobić.', 'Zgłoś się do dowódcy polowego Mahfuuna przy wejściu do Labiryntu Cieni w Auchindoun w Puszczy Terokkar.', '', '', '', '', '', '', 0),
(10180, 'plPL', 'Nie usiedzi w miejscu', 'Nie udało mi się namówić Isfara, by został tutaj, w bezpiecznym Shattrath – nie chciał o tym słyszeć. Postanowił za to znów samotnie wyruszyć do Auchindoun.$B$BRaz miał szczęście i uciekł z Sal Sethekk, ale jeśli go odkryją, drugiego razu nie będzie.$B$BPodziwiam jego pragnienie uwolnienia siostry, ale bez pomocy mu się to nie uda.$B$BOdnajdź Isfara i porozmawiaj z nim, $N. Jeśli nie zdołasz go przekonać do powrotu, może pomożesz mu uratować Lakkę?', 'Porozmawiaj z Isfarem, którego znajdziesz przy wejściu do Sal Sethekk w Auchindoun.', '', '', '', '', '', '', 0),
(10210, 'plPL', 'A\'dal', 'Witaj w Shattrath, $N. To chyba jedyne miejsce na całej Rubieży, gdzie znajdziesz choć namiastkę bezpieczeństwa.$B$BGrupa naaru znana jako Sha\'tar przegnała stąd demony.$B$BJeśli nigdy nie $gspotkałeś:spotkałaś; naaru, koniecznie odwiedź A\'dala na Tarasie Światła. Przywódca Sha\'tar to widok, który zapiera dech w piersiach jak mało co. Zupełna odmiana od wszystkiego innego w tej ponurej krainie.', 'Porozmawiaj z A\'dalem, przywódcą Sha\'tar, pośrodku Tarasu Światła.', '', '', '', '', '', '', 0),
(10211, 'plPL', 'Miasto Światła', 'Nie zawracaj A\'dalowi głowy błahymi pytaniami, $N. To być może najpotężniejsza istota, z jaką kiedykolwiek staniesz twarzą w twarz.$B$BNie wyglądasz znajomo. Zapewne chcesz się czegoś dowiedzieć o mieście?$B$BWybacz, że nie oprowadzę cię osobiście, ale jestem dość zajęty omawianiem strategii z A\'dalem. Może przywołany sługa wystarczy w moim zastępstwie? Doskonale!', 'Podążaj za sługą Khadgara i wysłuchaj jego opowieści. Po wykonaniu zadania wróć do Khadgara.', 'Miasto Światła', 'Wróć do Khadgara w Shattrath.', '', '', '', '', 0),
(10228, 'plPL', 'Ezekiel', 'Uważam, że zmarłych, którymi opiekujemy się od jakichś pięciuset lat, należy zostawić w spokoju. Maladaar ma inne plany. Wycofał się do Krypty Pamięci, by rozpocząć swoje eksperymenty... Nekromancję.$B$BMam nadzieję, że nie $gzamierzałeś:zamierzałaś; tam wchodzić... Nie, zanim mi pomożesz, żeby te przeklęte duchy wreszcie dały mi spokój. Wiem, gdzie trzymają swoje skarby. Zwróciło to twoją uwagę, co?$B$BPrzynieś mi księgę umarłych, którą ma Aldor, Ezekiel z Shattrath.$B', 'Odnajdź Ezekiela z Shattrath i porozmawiaj z nim.', '', '', '', '', '', '', 0),
(10231, 'plPL', 'Jaka księga? Nie widzę żadnej księgi.', 'Ramdor? Hmm, niech pomyślę... Ramdor... Ach tak, kapłan śmierci. Po co mu ta księga? Zresztą nieważne. Tak, okłamałem cię i nie, nie mam tej księgi. W każdym razie już nie. Została skradziona. Pewnie przez któregoś z tych brudnych uchodźców.$B$BZresztą Auchindoun to już przeszłość. Nie potrzebujemy tej księgi. Jeśli ją znajdziesz, możesz ją zatrzymać.$B$BJak mówiłem, w zeszłym tygodniu widziałem kilku takich zbirów węszących przy tarasie. Zacznij poszukiwania od nich. Pewnie grają w kości w slumsach.', 'Ezekiel twierdzi, że księgę skradziono. Najlepiej będzie odnaleźć zbirów i sprawdzić, czy coś wiedzą.$B', 'Pobij „Brudnego” Larry\'ego i zdobądź informacje', 'Wróć do „Brudnego” Larry\'ego w Shattrath.', '', '', '', '', 0),
(10251, 'plPL', 'Wielki zamysł mistrza?', 'Wczoraj wieczorem odwiedziło nas dwóch draenei. Jakimś cudem dowiedzieli się, że mamy tę księgę, i złożyli bardzo hojną ofertę, że „zdejmą nam ją z głowy”.$B$BNie pytaliśmy, po co im ta księga, ale ten młody ciągle gadał o „wielkim zamyśle mistrza”, cokolwiek to znaczy.$B$BSłuchaj, nie zadaję pytań, kiedy w grę wchodzą pieniądze. Dali nam kupę złota, a my daliśmy im księgę.$B$BMówił, że mieszkają w Nagrandzie – w starej Porzuconej Zbrojowni, na północ od Telaar.', 'Odnajdź Nitrina Uczonego w Porzuconej Zbrojowni w Nagrandzie.', '', '', '', '', '', '', 0),
(10280, 'plPL', 'Specjalna dostawa do Shattrath', 'Jestem eterykiem, który dotrzymuje słowa, $N. Naprawdę mnie $gzainspirowałeś:zainspirowałaś;.$B$BPrzekażę ci teraz kryształ ata\'mal dla naaru. Ponieważ to twoje bohaterstwo to umożliwiło, chcę, żebyś to ty go $gdostarczył:dostarczyła;.$B$BMożesz skorzystać z mojego osobistego teleportera, by przenieść się prosto do Shattrath. Wystarczy przez niego przejść, a zostaniesz tam $gprzeniesiony:przeniesiona;.$B$BPrzekaż kryształ naaru zwanemu A\'dalem na Tarasie Światła. Niech wiatry handlu zawsze ci sprzyjają.', 'Dostarcz kryształ Ata\'mal A\'dalowi na Tarasie Światła w Shattrath.', '', '', '', '', '', '', 0),
(10325, 'plPL', 'Znaki Kil\'jaedena', 'Jak zapewne wiesz, $N, Aldorowie są strażnikami Światła i sługami naaru.$B$BDokładnie po przeciwnej stronie stoją agenci Płonącego Legionu – demony, które pragną niszczyć światy i deprawować niewinnych.$B$BJeśli chcesz dowieść Aldorom swojej wartości, przynieś mi insygnia niższych rangą sług Legionu i ich wyznawców z Rady Cieni. Wiemy o kryjówce Rady Cieni na Kościanych Pustkowiach, a w Nagrandzie i Górach Klingi jest wiele posterunków Legionu.', 'Przynieś 10 znaków Kil\'jaedena Adyenowi Strażnikowi Światła w Shattrath.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', 'Wróć do Adyena Strażnika Światła na Wzniesieniu Aldorów w Shattrath.', '', '', '', '', 0),
(10326, 'plPL', 'Więcej znaków Kil\'jaedena', '', '', '', 'Wróć do Adyena Strażnika Światła.', '', '', '', '', 0),
(10327, 'plPL', 'Pojedynczy znak Kil\'jaedena', '', '', '', 'Wróć do Adyena Strażnika Światła.', '', '', '', '', 0),
(10409, 'plPL', 'Cios śmierci dla Legionu', 'W starciu z potężnymi eredarami wielkie armie są w większości bezużyteczne. Ich moc deprawowania dusz śmiertelników jest tak wielka, że tylko najsilniejsi duchem w ogóle są w stanie stanąć z nimi twarzą w twarz.$B$BZabierz ten kamień do Punktu Inwazji: Zwierzchnik, między Bazą Kuźniczą: Zapomnienie a Gehenną, i weź ze sobą najbliższych i najsilniejszych przyjaciół. Orelis i Karja spotkają się z wami w Siedzibie Socrethara; wyślę z nimi Adyena.$B$BNiech Światło dziś zwycięży, $N. Niech Socrethar spotka swój koniec.', 'Arcykapłanka Ishanah chce, abyś $gudał:udała; się do teleportera Legionu w północno-zachodnim krańcu Burzy Otchłani i $gprzeniósł:przeniosła; się za jego pomocą do Siedziby Socrethara. Na miejscu pokonaj Socrethara.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', 'Cios śmierci dla Legionu', 'Zgłoś się do Ishanah na Wzniesieniu Aldorów w Shattrath.', '', '', '', '', 0),
(10410, 'plPL', 'Pomoc Ishanah', 'Nadszedł czas, by stawić czoła Socretharowi, $N. Konfrontacji z przywódcą eredarów nie traktujemy lekko. Jeśli nie będziemy dobrze przygotowani, jeden błąd najpewniej będzie nas kosztował życie.$B$BZanieś kamień teleportacyjny Socrethara arcykapłance Ishanah w Kaplicy Nieskończonego Światła w Shattrath. Ona zdecyduje, jak mamy postąpić.', 'Zanieś kamień teleportacyjny Socrethara arcykapłance Ishanah w Kaplicy Nieskończonego Światła na Wzniesieniu Aldorów w Shattrath.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', '', '', '', '', '', 0),
(10412, 'plPL', 'Sygnety Ognistego Skrzydła', 'Nie jest tajemnicą, że Kael\'thas Słońcobieżca uważa nas za wielkie zagrożenie. Spójrzmy prawdzie w oczy – niewielu sin\'dorei, świeżo przybyłych ze Srebrnej Luny, chce się przyłączyć do towarzystwa, w jakim obraca się Kael.$B$BNie jest też tajemnicą, że to nie tylko wojna na słowa. Widzący i armie służące Kael\'thasowi atakują się nawzajem, gdy tylko się zobaczą. Jedynym sposobem, by udowodnić, że jesteś z nami, $N, jest wzięcie udziału w walce.$B$BNiżsi rangą poplecznicy Kaela noszą sygnety Ognistego Skrzydła na znak swojej rangi. Przynieś mi je.', 'Magistrix Fyalenn w Shattrath chce, abyś $gprzyniósł:przyniosła; jej 10 sygnetów Ognistego Skrzydła.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', '', 'Wróć do magistrix Fyalenn w Puszczy Terokkar.', '', '', '', '', 0),
(10414, 'plPL', 'Pojedynczy sygnet Ognistego Skrzydła', '', '', '', 'Wróć do magistrix Fyalenn w Puszczy Terokkar.', '', '', '', '', 0),
(10415, 'plPL', 'Więcej sygnetów Ognistego Skrzydła', '', '', '', 'Wróć do magistrix Fyalenn w Puszczy Terokkar.', '', '', '', '', 0),
(10416, 'plPL', 'Synteza mocy', 'Tajemne księgi to nie zwykłe książki, które akurat traktują o sprawach magii. Tkwi w nich wewnętrzna moc – moc, którą nauczyłem się skupiać w jednej tajemnej runie.$B$BJeśli w swoich podróżach natrafisz na tajemną księgę, dam ci w zamian jedną taką runę. Księgi, których potrzebuję, noszą przy sobie tylko najpotężniejsi władający magią. Na Rubieży oznacza to zwykle krwawe elfy Kaela – ale zdziwisz się, gdzie takie księgi potrafią się znaleźć.', 'Voren\'thal Jasnowidz w Shattrath chce, abyś $gzdobył:zdobyła; tajemną księgę.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', '', 'Wróć do Voren\'thala Jasnowidza w Puszczy Terokkar.', '', '', '', '', 0),
(10419, 'plPL', 'Tajemne księgi', '', '', '', 'Wróć do Voren\'thala Jasnowidza w Puszczy Terokkar.', '', '', '', '', 0),
(10420, 'plPL', 'Oczyszczające Światło', 'Ta świątynia jest jednym z najświętszych miejsc na całej Rubieży. Moc Światła jest tu tak silna, że nawet przedmioty najmocniej skażone Spaczeniem można oczyścić z tego, co doczesne.$B$BJeśli w starciach z demonicznymi wrogami natrafisz na spaczone uzbrojenie, przynieś je do mnie, a pokażę ci oczyszczającą moc Światła.', 'Przynieś spaczone uzbrojenie Ishanah w Shattrath.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', 'Wróć do Ishanah na Wzniesieniu Aldorów w Shattrath.', '', '', '', '', 0),
(10421, 'plPL', 'Spaczone uzbrojenie', '', '', '', 'Wróć do Ishanah.', '', '', '', '', 0),
(10507, 'plPL', 'Punkt zwrotny', 'Na tę szansę czekaliśmy, $N. Nie tylko zdobyliśmy dowody, których potrzebujemy, by pokazać naszemu ludowi, dla kogo naprawdę pracuje Kael\'thas, ale możemy też dowieść swojej siły, pokonując jego nowych panów.$B$BWątłe zdrowie nie pozwala mi osobiście pomóc ci w tym przedsięwzięciu, ale dam ci przedmiot, dzięki któremu zdołam przenieść swoją moc przez cały kontynent.', 'Użyj kamienia teleportacyjnego Socrethara w Punkcie Inwazji: Zwierzchnik, na północ od Bazy Kuźniczej: Zapomnienie, by przenieść swoją drużynę do Lądowiska Socrethara. Na miejscu użyj obecności Voren\'thala, by pokonać Socrethara.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', '', 'Wróć do Voren\'thala Jasnowidza na Tarasie Widzących w Shattrath.', '', '', '', '', 0),
(10509, 'plPL', 'Ku chwale', 'Teraz mogę cię jak należy odesłać do Shattrath. $GOdkryłeś:Odkryłaś; dowody na to, że Kael\'thas zawiera pakty z Płonącym Legionem, i masz klucz do tylnych drzwi zwierzchnika.$B$BTylko dopilnuj, żeby Voren\'thal nie przewrócił się z wrażenia na te wieści – staruszek robi się nieco kruchy, jeśli wiesz, co mam na myśli. Znajdziesz go w Bibliotece Jasnowidza na Tarasie Widzących.', 'Zanieś kamień teleportacyjny Socrethara Voren\'thalowi Jasnowidzowi na Tarasie Widzących w Shattrath.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', '', '', '', '', '', '', 0),
(10547, 'plPL', 'O ostomaniakach i jajach...', 'Poddałbym się, gdybym nie zauważył... To ostomaniak. Z początku nie mogłem tego rozpoznać, ale wszystkie znaki na to wskazują...$B$BGdybyśmy tylko zdobyli trochę krwawego ostu, moglibyśmy działać.$B$BW swoich podróżach spotkałem w Shattrath podejrzanego Złamanego imieniem Tobias.$B$BTobias zbił interes na sprzedawaniu krwawego ostu krwawym elfom w zamian za zgniłe jaja arakkoa.$B$BTuż na zachód stąd są ruiny arakkoa. Przeszukaj je, znajdź jajo i udaj się do Dolnego Miasta w Shattrath. Tam znajdziesz Tobiasa.', 'Borak, syn Oronoka, przy moście na północ od Punktu Zaćmienia chce, abyś $gznalazł:znalazła; zgniłe jajo arakkoa i $gdostarczył:dostarczyła; je Tobiasowi Pożeraczowi Brudu w Shattrath, w północno-zachodniej części Puszczy Terokkar.', '', 'Odszukaj Tobiasa Pożeracza Brudu w Shattrath w Puszczy Terokkar.', '', '', '', '', 0),
(10550, 'plPL', 'Pęk krwawego ostu', 'Nie kłamałem. To jajo było niesamowite. Skąd je $gwziąłeś:wzięłaś;?$B$BCóż, jeśli kiedyś będziesz potrzebować więcej krwawego ostu, wiesz, gdzie mnie szukać i czego mi trzeba.$B$BMasz tu pęk tego ziela. Zanieś go swojemu dobroczyńcy.', 'Zanieś pęk krwawego ostu Borakowi, synowi Oronoka, przy moście w pobliżu Punktu Zaćmienia w Dolinie Cienistego Księżyca.$B', '', '', '', '', '', '', 0),
(10551, 'plPL', 'Wierność Aldorom', '', '', '', '', '', '', '', '', 0),
(10552, 'plPL', 'Wierność Widzącym', '', '', '', '', '', '', '', '', 0),
(10553, 'plPL', 'Voren\'thal Jasnowidz', 'Skoro już $gwybrałeś:wybrałaś; stronę, $N, czas poznać przywódcę Widzących.$B$BVoren\'thala Jasnowidza znajdziesz w Bibliotece Jasnowidza na Tarasie Widzących.$B$BSprawdź, czy możesz mu w czymś pomóc. Ucieszy się, że $gpostanowiłeś:postanowiłaś; podać im pomocną dłoń.', 'Porozmawiaj z Voren\'thalem Jasnowidzem w Bibliotece Jasnowidza na Tarasie Widzących w Shattrath.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', '', '', '', '', '', '', 0),
(10554, 'plPL', 'Ishanah', 'Skoro $gpostanowiłeś:postanowiłaś; stanąć po stronie Aldorów, dobrze by było, abyś $gprzedstawił:przedstawiła; się ich przywódczyni. Arcykapłankę Ishanah znajdziesz w Kaplicy Nieskończonego Światła.', 'Porozmawiaj z Ishanah w Kaplicy Nieskończonego Światła na Wzniesieniu Aldorów w Shattrath.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', '', '', '', '', '', 0),
(10560, 'plPL', 'Czczony u Sha\'tar', '<Kojące, melodyjne tony płynące od A\'dala stają się cichsze i posępniejsze.>$B$B<Widzisz wielką budowlę naaru zwaną Twierdzą Burz. Zamieszkują ją teraz siły Kael\'thasa, a jej moc służy nikczemnym celom. A\'dal obiecuje ci większe zadania, gdy wniesiesz swój wkład w odbicie Twierdzy Burz.>', 'A\'dal w Shattrath chce, abyś $gosiągnął:osiągnęła; u Sha\'tar reputację na poziomie „Czczony”, pokonując siły Kael\'thasa w Twierdzy Burz.', '', '', '', '', '', '', 0),
(10653, 'plPL', 'Znaki Sargerasa', 'Teraz już powinno być dla ciebie jasne, dlaczego sprzeciwiamy się Płonącemu Legionowi i tym, którzy mu służą.$B$BJeśli chcesz dowieść Aldorom swojej wartości, przynieś mi insygnia wysokich rangą sług Legionu i ich wyznawców z Rady Cieni. Najwyższych rangą sług Legionu znajdziesz w Burzy Otchłani i Dolinie Cienistego Księżyca.', 'Przynieś 10 znaków Sargerasa Adyenowi Strażnikowi Światła w Shattrath.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', 'Wróć do Adyena Strażnika Światła na Wzniesieniu Aldorów w Shattrath.', '', '', '', '', 0),
(10654, 'plPL', 'Więcej znaków Sargerasa', '', '', '', 'Wróć do Adyena Strażnika Światła.', '', '', '', '', 0),
(10655, 'plPL', 'Pojedynczy znak Sargerasa', '', '', '', 'Wróć do Adyena Strażnika Światła.', '', '', '', '', 0),
(10656, 'plPL', 'Sygnety Słonecznej Furii', 'Jak zapewne wiesz, Widzący i armie Kael\'thasa toczą wojnę. Kael uważa nas za zagrożenie dla swoich wpływów wśród innych krwawych elfów i raz po raz próbował nas zmiażdżyć.$B$BJeśli chcesz pomóc nam w walce z Kael\'thasem, celów ci nie zabraknie. Najwyżsi rangą żołnierze Kaela noszą sygnety Słonecznej Furii na znak swoich stopni. Znajdziesz ich w całej Burzy Otchłani i Dolinie Cienistego Księżyca.', 'Magistrix Fyalenn w Shattrath chce, abyś $gprzyniósł:przyniosła; jej 10 sygnetów Słonecznej Furii.$B$BWykonywanie zadań dla Widzących obniży twoją reputację u Aldorów.', '', 'Wróć do magistrix Fyalenn w Puszczy Terokkar.', '', '', '', '', 0),
(10658, 'plPL', 'Więcej sygnetów Słonecznej Furii', '', '', '', 'Wróć do magistrix Fyalenn w Puszczy Terokkar.', '', '', '', '', 0),
(10659, 'plPL', 'Pojedynczy sygnet Słonecznej Furii', '', '', '', 'Wróć do magistrix Fyalenn w Puszczy Terokkar.', '', '', '', '', 0),
(10704, 'plPL', 'Jak włamać się do Arkatrazu', 'W krysztale ata\'mal, który $godzyskałeś:odzyskałaś;, ukryto wiadomość. Książę Nexusa Haramad przekazał nam informacje kluczowe dla naszej kampanii przeciwko Twierdzy Burz.$B$BMówi, że istnieją dwa odłamki klucza, które po połączeniu otworzą satelitę twierdzy – Arkatraz.$B$BJedną połowę ma pradrzewiec w Botanice zwany Spaczodrzazgiem. Drugą przechowuje Pathaleon Rachmistrz w Mechanarze.$B$BPrzynieś mi oba odłamki, a połączę je w klucz do Arkatrazu.', 'A\'dal zlecił ci odzyskanie górnego i dolnego odłamka klucza do Arkatrazu. Zwróć mu je, a wykona z nich dla ciebie klucz do Arkatrazu.', '', 'Wróć do A\'dala w Dolnym Mieście w Shattrath.', '', '', '', '', 0),
(10708, 'plPL', 'Obietnica Akamy', '<Akama umieszcza kryształ w medalionie, który trzyma w dłoni.>$B$BNie jestem już tak silny jak niegdyś, $N. Przez te wszystkie lata byłem tak blisko samego zła, że nie wiem, czy mogę sobie zaufać, mając artefakt tak potężny jak ten.$B$BWeź go jako moją obietnicę, że gdy nadejdzie czas i staniesz przed Illidanem, będę po twojej stronie. Zanieś go jedynej istocie, której na pewno możemy powierzyć jego moc. Zanieś medalion A\'dalowi w Shattrath.', 'Zanieś medalion Karaboru A\'dalowi w Shattrath.', '', '', '', '', '', '', 0),
(10737, 'plPL', 'Dotyk mistrza', 'Złożyłem z powrotem ten sam klucz, którego używałem jako uczeń. Jak na klucz, wygląda na całkowicie sprawny. Jeśli jednak chodzi o otwarcie Karazhanu, równie dobrze mógłby być kawałkiem złomu.$B$BBez zgody Medivha klucz jest bezwartościowy. Tak, oczywiście wiem, że Medivh nie żyje. To tylko utrudnia sprawę, a nie czyni jej niemożliwą.$B$BW Azeroth jest miejsce zwane Jaskiniami Czasu, strzeżone przez Brązowe Stado. Znajdź sposób, by się tam dostać, cofnij się w czasie i skłoń Medivha, by aktywował klucz.', 'Wejdź do Jaskiń Czasu i przekonaj Medivha, by aktywował twój odnowiony klucz ucznia.', '', '', '', '', '', '', 0),
(10781, 'plPL', 'Bitwa o Karmazynową Strażnicę', 'Pewnie właśnie szukają cię na Ścieżce Podboju. Musisz uciekać!$B$BZostaw mnie, ze mną już koniec... Oni... Chyba słyszę, że nadchodzą. Teraz albo nigdy! Uciekaj! Jeśli zostaniesz, będziesz $gmusiał:musiała; walczyć!$B$BJeśli podejmiesz walkę i jakimś cudem przeżyjesz, zabierz to, czego się tu $gdowiedziałeś:dowiedziałaś;, i przekaż tę wiedzę A\'dalowi w Shattrath.', 'Walcz z siłami Illidana w Karmazynowej Strażnicy i przeżyj!$B$BJeśli wyjdziesz z walki zwycięsko, wróć do A\'dala w Shattrath.', 'Siły Karmazynowej Pieczęci unicestwione', 'Wróć do A\'dala w Shattrath w Puszczy Terokkar.', '', '', '', '', 0),
(10822, 'plPL', 'Pojedynczy sygnet Słonecznej Furii', '', '', '', 'Wróć do magini bojowej Vyary w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10823, 'plPL', 'Więcej sygnetów Słonecznej Furii', '', '', '', 'Wróć do magini bojowej Vyary w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10826, 'plPL', 'Znaki Sargerasa', 'Teraz już powinno być dla ciebie jasne, dlaczego sprzeciwiamy się Płonącemu Legionowi i tym, którzy mu służą.$B$BJeśli chcesz dowieść Aldorom swojej wartości, przynieś mi insygnia wysokich rangą sług Legionu i ich wyznawców z Rady Cieni. Tu, w Dolinie Cienistego Księżyca, silne siły Legionu znajdziesz daleko na zachodzie, w Warowni Legionu i Kuźni Śmierci.', 'Przynieś 10 znaków Sargerasa zwiastunowi Saronenowi w Dolinie Cienistego Księżyca.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.', '', 'Wróć do zwiastuna Saronena przy Ołtarzu Sha\'tar w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10827, 'plPL', 'Więcej znaków Sargerasa', '', '', '', 'Wróć do zwiastuna Saronena w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10828, 'plPL', 'Pojedynczy znak Sargerasa', '', '', '', 'Wróć do zwiastuna Saronena w Dolinie Cienistego Księżyca.', '', '', '', '', 0),
(10831, 'plPL', 'Krawiectwo księżycowej tkaniny', 'Jeśli chcesz, mogę cię nauczyć krawiectwa księżycowej tkaniny. Dzięki tej specjalizacji z wytwarzania pierwotnej księżycowej tkaniny uzyskasz dwa razy więcej niż zwykle i zyskasz dostęp do kilku wyjątkowych wykrojów. Wystarczy, że zdasz prosty test.$B$BTwoim zadaniem będzie wytworzenie małej próbki pierwotnej księżycowej tkaniny w księżycowej studni w Schronieniu Cenariona. Dostarczę ci wszystkie potrzebne materiały. Gdy wytworzysz próbkę, przynieś mi ją do oceny.', 'Użyj kawałka nasyconej tkaniny Otchłani, stojąc w księżycowej studni w Schronieniu Cenariona, by wytworzyć próbkę pierwotnej księżycowej tkaniny. Przynieś gotową próbkę Nasmarze Księżycowej Pieśni w Dolnym Mieście w Shattrath.$B$B*UWAGA!* Możesz wybrać tylko jedną specjalizację krawiecką.', '', 'Wróć do Nasmary Księżycowej Pieśni w Shattrath.', '', '', '', '', 0),
(10832, 'plPL', 'Krawiectwo ognia zaklęć', 'Jeśli chcesz, mogę cię nauczyć krawiectwa ognia zaklęć, ale ostrzegam – to niebezpieczne zajęcie.$B$BWytwarzanie tkaniny zaklęć w Burzy Otchłani przyciąga potężne upiory Otchłani. Szukam sposobu, by złagodzić ten odwet, ale do badań potrzebuję więcej esencji upiorów Otchłani.$B$BWeź tę latarnię do Burzy Otchłani i użyj jej, by przywołać upiora Otchłani. Przynieś mi jego esencję, a zgodzę się cię uczyć. Jako $gkrawiec:krawcowa; ognia zaklęć otrzymasz dwa razy więcej tkaniny i zyskasz dostęp do wyjątkowych wykrojów.', 'Przynieś próbkę esencji upiora Otchłani Gidge Tkaczce Zaklęć w Dolnym Mieście w Shattrath.$B$B*UWAGA!* Możesz wybrać tylko jedną specjalizację krawiecką.', '', 'Wróć do Gidge Tkaczki Zaklęć w Shattrath.', '', '', '', '', 0),
(10833, 'plPL', 'Krawiectwo tkaniny cienia', 'Jeśli wyspecjalizujesz się w tkaninie cienia, będziesz wytwarzać dwa razy więcej cienistej tkaniny niż przeciętny krawiec i zyskasz dostęp do kilku wyjątkowych wykrojów.$B$BOczywiście każdy krawiec może korzystać z Ołtarza Cieni, ale krawiec tkaniny cienia ma z ołtarzem głębszą więź, która odblokowuje moce pojmowane tylko przez nielicznych.$B$BZabierz ten kryształ do wschodniej części Doliny Cienistego Księżyca i znajdź Przełęcz Otchłanioskrzydłych, prowadzącą na południe od Pól Otchłanioskrzydłych. Blisko krawędzi świata znajdziesz Ołtarz Cieni. Użyj tam kryształu.', 'Użyj kryształu głębokich cieni w pobliżu Ołtarza Cieni, by pogłębić swoją więź z ołtarzem, a następnie wróć do Andriona Mrokoprzęda w Dolnym Mieście w Shattrath.$B$B*UWAGA!* Możesz wybrać tylko jedną specjalizację krawiecką.', '', 'Wróć do Andriona Mrokoprzęda w Shattrath.', 'Pogłębiona więź z Ołtarzem Cieni', '', '', '', 0),
(10847, 'plPL', 'Oczy Skettis', 'Zagłada nadciąga z urwisk Skettis.$b$bMój lud, arakkoa, stoi w obliczu losu spowitego niewypowiedzianym złem. Zbyt często nadużywaliśmy mrocznej magii w niegodziwych celach. Dzięki A\'dalowi poznałem Światło i odkupienie.$b$bTerokk obserwuje swoje kolonie ze Skettis przez kule zaklęte czarną magią. Wykradnij te Oczy z Zasłony Reskk i Zasłony Shienor w północnej części Puszczy Terokkar. Pozwól mi zobaczyć to, co widzi Terokk. Pozwól mi spojrzeć oczami Skettis.', 'Przynieś oko Reskk i oko Shienor Rilakowi Odkupionemu w Dolnym Mieście w Shattrath.', '', 'Wróć do Rilaka Odkupionego w Dolnym Mieście w Shattrath.', '', '', '', '', 0),
(10849, 'plPL', 'Odszukaj Kirrika', 'Inni arakkoa także wzięli udział w zdradzie Terokka.$b$bKirrik rozpoznał w Terokku szarlatana, a nie proroka. Jedyne proroctwo, jakie Terokk przewidział, to zagłada, którą sam sprowadził.$b$bTo Kirrik dzielnie wyprowadził nas ze Skettis. Po naszej pielgrzymce do Shattrath Kirrik udał się do kolonii w poszukiwaniu innych.$b$bTen list opisuje to, co ujrzały Oczy. Kirrik musi się o tym dowiedzieć! Idź drogą na południe od Shattrath, do Kościanych Pustkowi, i szukaj karawany.', 'Zanieś list Rilaka Kirrikowi Przebudzonemu przy Karawanie Uchodźców na Kościanych Pustkowiach.', '', '', '', '', '', '', 0),
(10862, 'plPL', 'Kapitulacja przed Hordą', 'Tchórzliwi arakkoa atakują nas codziennie. Urządzają zasadzki na naszych łowców, a czasem napadają nawet w obrębie naszych murów. Zabijamy ich, kiedy możemy, ale ich magia jest silna i często wymykają się naszym oddziałom.$B$BDowiedziałem się, że niektórzy arakkoa twierdzą, że są przyjaźnie nastawieni do Hordy. Mieszkają w Shattrath, na północnym zachodzie. Ich przywódcą jest Rilak Odkupiony. Poszukaj go w Dolnym Mieście, a gdy go znajdziesz, zażądaj jego kapitulacji.', 'Rokag chce, abyś $godszukał:odszukała; Rilaka Odkupionego w Dolnym Mieście w Shattrath i $gzażądał:zażądała;, by on i jego lud poddali się Hordzie.', '', '', '', '', '', '', 0),
(10863, 'plPL', 'Sekrety arakkoa', 'Tu, na pograniczu, codziennie mamy do czynienia z arakkoa. Uderzają, kiedy im się podoba, napadając na nasze linie zaopatrzenia i zabijając zwiadowców.$B$BA jednak niewiele wiemy o tych zagadkowych stworzeniach. Doszły mnie wieści, że na północny zachód stąd, w Shattrath, żyją arakkoa, którzy nie są wrogo nastawieni. Może zechcą podzielić się sekretami swojej rasy.$B$BIch przywódcą jest Rilak Odkupiony. Przebywa w północnej części Dolnego Miasta.', 'Lady Dena Kennedy chce, abyś $godszukał:odszukała; Rilaka Odkupionego w Dolnym Mieście w Shattrath i $gsprawdził:sprawdziła;, jakimi sekretami arakkoa zechce się podzielić.', '', '', '', '', '', '', 0),
(10869, 'plPL', 'Przetrzebić stado', 'Arakkoa znów nas zaatakowali, tym razem uderzając nocą, a potem uciekli za pomocą mrocznej magii, zanim zdążyliśmy zebrać żołnierzy.$B$BZasłona Reskk i Zasłona Shienor leżą na północy i północnym zachodzie. Znajdź te gniazda arakkoa i zabij, ilu tylko zdołasz. Może się nas nie boją, ale przynajmniej przetrzebimy ich szeregi.', 'Porucznik Żwiromłot prosi, żebyś $gzabił:zabiła; 14 szponowców z Shienor i 6 czarowników z Shienor, a potem $gwrócił:wróciła; do niego w Forcie Alleriańskim.', '', 'Wróć do porucznika Żwiromłota w Forcie Alleriańskim w Puszczy Terokkar.', '', '', '', '', 0),
(10879, 'plPL', 'Ofensywa Skettis', 'Skettis wypowiedziało nam wojnę! $GZebrałeś:Zebrałaś; dość sił, by pomóc w obronie Shattrath?$b$bPowstrzymaj napastników!', 'Powstrzymaj napastników i porozmawiaj z Rilakiem Odkupionym.', 'Atak odparty', 'Wróć do Rilaka Odkupionego w Dolnym Mieście w Shattrath.', '', '', '', '', 0),
(10882, 'plPL', 'Zwiastun zagłady', '<W „głosie” A\'dala da się wyczuć fałszywą nutę.>$B$BKsiążę Kael\'thas źle wybrał strażnika i teraz istoty, które trzymaliśmy zamknięte w Arkatrazie, wyrywają się na wolność.$B$BJedna z nich, sługa Przedwiecznych znany jako zwiastun Skyriss, pragnie urzeczywistnić wizję swoich panów – podbój wszystkich światów we wszechświecie.$B$B$N, nie możesz pozwolić mu uciec. Wróć do Twierdzy Burz, wejdź do Arkatrazu i zabij zwiastuna Skyrissa, zanim będzie za późno!', 'Masz się udać do satelity Twierdzy Burz – Arkatrazu – i zabić zwiastuna Skyrissa. Potem wróć do A\'dala na Tarasie Światła w Shattrath.', '', 'Wróć do A\'dala w Dolnym Mieście w Shattrath.', '', '', '', '', 0),
(10883, 'plPL', 'Klucz do Twierdzy Burz', '$GDowiodłeś:Dowiodłaś;, że jesteś $gzdolny:zdolna; do wielkich czynów, $N. Twoje odkrycie Szyfru Potępienia i udziału Kael\'thasa ma ogromne znaczenie dla naszej sprawy. Gdyby Kael użył szyfru, to, co zostało z tego świata, mogłoby się rozpaść.$B$BA\'dal jest przekonany, że Kaela trzeba powstrzymać, i szuka teraz śmiałków gotowych poddać się próbom. Ci, którzy dowiodą swojej siły, zyskają przychylność naaru.$B$B<Khadgar kiwa głową.>$B$BA\'dal czeka...$B', 'Porozmawiaj z A\'dalem w Shattrath.$B', '', '', '', '', '', '', 0),
(10884, 'plPL', 'Próba naaru: łaska', 'Musisz przejść cztery próby, zanim naaru uznają cię za $ggodnego:godną;.$B$BW Strzaskanych Salach Cytadeli Piekielnego Ognia przetrzymywanych jest trzech twoich pobratymców. Więzi ich bezlitosny Kargath Brzytworęki. Chce ich stracić na znak swojej męskości i potęgi. Musisz ocalić tych więźniów, zanim dojdzie do takiej potworności. Na dowód dokonania przynieś mi nieużywany topór kata. Na jego ostrzu nie może być ani kropli krwi!$B', 'A\'dal w Shattrath chce, abyś $godzyskał:odzyskała; nieużywany topór kata ze Strzaskanych Sal Cytadeli Piekielnego Ognia.$B$BTo zadanie trzeba wykonać na heroicznym poziomie trudności lochu.', '', 'Wróć do A\'dala w Dolnym Mieście w Shattrath.', '', '', '', '', 0),
(10885, 'plPL', 'Próba naaru: siła', 'Musisz przejść cztery próby, zanim naaru uznają cię za $ggodnego:godną;.$B$BPróba siły dzieli się na dwie części. Musisz zniszczyć przywódcę Krypty Pary w Zbiorniku Żmijokolców, wodza Kalithresha, i przynieść mi jego trójząb. Zabij istotę spoza tego wymiaru, znaną jako Szmer, w Labiryncie Cieni w Auchindoun, i przynieś mi jego esencję.$B$BZrób to, a przejdziesz próbę siły.', 'A\'dal w Shattrath chce, abyś $godzyskał:odzyskała; trójząb Kalithresha i esencję Szmeru.$B$BTo zadanie trzeba wykonać na heroicznym poziomie trudności lochu.', '', 'Wróć do A\'dala w Dolnym Mieście w Shattrath.', '', '', '', '', 0),
(10886, 'plPL', 'Próba naaru: nieustępliwość', 'Musisz przejść cztery próby, zanim naaru uznają cię za $ggodnego:godną;.$B$BW naszych podróżach napotkaliśmy wiele niebezpiecznych istot. Niektóre z nich uwięziliśmy w miejscu znanym dziś jako Arkatraz w Twierdzy Burz.$B$BJest jednak jeden więzień, który padł ofiarą okoliczności. Pasażer na gapę, który znalazł się na niewłaściwym statku naaru w niewłaściwym czasie.$B$BUdaj się do Arkatrazu i uratuj gnoma, Mełka Gromiłłę. Dopilnuj, by przeżył.', 'A\'dal w Shattrath chce, abyś $guratował:uratowała; Mełka Gromiłłę z Arkatrazu w Twierdzy Burz.$B$BTo zadanie trzeba wykonać na heroicznym poziomie trudności lochu.', 'Mełko Gromiłło uratowany', 'Wróć do A\'dala w Dolnym Mieście w Shattrath.', '', '', '', '', 0),
(10888, 'plPL', 'Próba naaru: Magtheridon', 'Musisz przejść cztery próby, zanim naaru uznają cię za $ggodnego:godną;.$B$BZostała tylko jedna przeszkoda, $gśmiertelniku:śmiertelniczko;. Zbierz armię i udaj się do leża Magtheridona, głęboko w Cytadeli Piekielnego Ognia. Przebij się do serca komnaty i zniszcz tego plugawego deprawatora!', 'A\'dal w Shattrath chce, abyś $gzabił:zabiła; Magtheridona.', '', 'Wróć do A\'dala w Dolnym Mieście w Shattrath.', '', '', '', '', 0),
(10889, 'plPL', 'Powrót do Shattrath', 'Twoje czyny, choć odważne, z pewnością wywołają mściwą odpowiedź Terokka.$b$bPospiesz się do Shattrath. Przekaż wiadomość Rilakowi!', 'Udaj się do Shattrath i porozmawiaj z Rilakiem Odkupionym w Dolnym Mieście.', '', '', '', '', '', '', 0),
(10898, 'plPL', 'Podniebne Skrzydło', 'Podniebne Skrzydło trzepocze wokół ciebie.$b$bMasz wrażenie, że chce, byś $gposzedł:poszła; za nim.', 'Eskortuj Podniebne Skrzydło i złóż raport Rilakowi Odkupionemu w Shattrath.', 'Eskortuj Podniebne Skrzydło', 'Wróć do Rilaka Odkupionego w Dolnym Mieście w Shattrath.', '', '', '', '', 0),
(10902, 'plPL', 'Mistrz eliksirów', 'Poświęciłem życie doskonaleniu moich eliksirów. Mimo sukcesów nie zdołałem stworzyć eliksiru wiecznego życia.$B$BChyba wiem, jakiego składnika mi brakuje. Słyszałem o miejscu w Azeroth zwanym Jaskiniami Czasu, gdzie intruzi zwani władcami szczelin i strażnikami szczelin pojawiają się na linii czasu i z niej znikają.$B$BTo natrętne przesuwanie się w czasie tworzy rozdarcia w samym czasie, skręcając go w nieskończoność w skrystalizowane esencje. Przynieś mi je wraz z próbkami swojej pracy, a nauczę cię wszystkiego, co wiem.', 'Udaj się do Czarnych Mokradeł w Jaskiniach Czasu i zdobądź 10 esencji nieskończoności od władców szczelin i strażników szczelin. Przynieś je wraz z 5 eliksirami wielkiej obrony, 5 eliksirami mistrzostwa i 5 eliksirami wielkiej zręczności Lorokeemowi w Dolnym Mieście w Shattrath.$B$B*UWAGA!* Możesz wybrać tylko jedną specjalizację alchemiczną.', '', 'Wróć do Lorokeema w Shattrath.', '', '', '', '', 0),
(10906, 'plPL', 'Mistrz eliksirów', 'Moja wiedza o alchemii jest rozległa. Ma jednak charakter ogólny. Jeśli chcesz się specjalizować, musisz znaleźć innych, którzy zajmują się węższymi dziedzinami.$B$BJeśli chcesz się specjalizować w tworzeniu eliksirów, radziłbym ci poszukać pomocy arakkoa o imieniu Lorokeem.$B$BJego wiedza o eliksirach nie ma sobie równych, a jednak marnuje swój talent na pogoń za eliksirem wiecznego życia. Znajdź go i przekonaj się, czego może cię nauczyć.', 'Porozmawiaj z Lorokeemem w Dolnym Mieście w Shattrath.$B$B*UWAGA!* Możesz wybrać tylko jedną specjalizację alchemiczną.', '', '', '', '', '', '', 0),
(10908, 'plPL', 'Porozmawiaj z Rilakiem Odkupionym', 'Wyglądasz na $gzaskoczonego:zaskoczoną;, że ze mną rozmawiasz. Nie dziwię ci się. Mój lud, arakkoa, zasługuje na to, by się go bać.$b$bJeśli chcesz dowiedzieć się więcej, porozmawiaj z Rilakiem Odkupionym w Shattrath. Znajdziesz go w północnej części Dolnego Miasta, wraz z innymi wyrzutkami ze Skettis.$b$bI jeszcze porozmawiamy, $N.', 'Kirrik Przebudzony chce, abyś $gporozmawiał:porozmawiała; z Rilakiem Odkupionym w Dolnym Mieście w Shattrath.', '', '', '', '', '', '', 0),
(10917, 'plPL', 'Dola wyrzutka', 'Jako wyrzutek jestem skazany na śmierć przez arakkoa wiernych miastu Skettis. Nie mogę opuścić tych murów, bo drżę o życie, ale to nie znaczy, że nie mogę uderzyć w nich w odwecie.$B$BMam niewielki skarbczyk, z którym chętnie się rozstanę, jeśli pomożesz mi odpłacić moim niedoszłym zabójcom. Przynieś mi pióra mieszkańców różnych Zasłon w Puszczy Terokkar jako dowód ich zguby.', 'Przynieś 30 piór arakkoa Vekaxowi w Dolnym Mieście w Shattrath.', '', 'Wróć do Vekaxa w Dolnym Mieście w Shattrath.', '', '', '', '', 0),
(10918, 'plPL', 'Więcej piór', '', '', '', 'Wróć do Vekaxa w Dolnym Mieście w Shattrath.', '', '', '', '', 0),
(10948, 'plPL', 'Dusza w niewoli', 'Może zastanawiasz się, dlaczego tak bardzo staram się ukryć swoje zamiary. Dlaczego nie przyłączę się otwarcie do naaru?$B$BSama moja istota – moja dusza – jest uwięziona w Czarnej Świątyni. Illidan mógł mnie zniszczyć w każdej chwili... aż do teraz! Ta filakteria pozwoli mi odzyskać kontrolę nad duszą.$B$BNadszedł czas, $N. Poprowadzę Maiev i moich Zaprzysiężonych Śmierci pod same drzwi Illidana.$B$BPorozmawiaj z A\'dalem i powiedz mu o naszym planie. Jeśli uderzymy razem, przełamiemy obronę Illidana.', 'Udaj się do Shattrath i powiedz A\'dalowi o prośbie Akamy.', '', '', '', '', '', '', 0),
(10949, 'plPL', 'Wejście do Czarnej Świątyni', '<A\'dal pokazuje ci obraz naaru przed Czarną Świątynią, walczącego u boku draenejskich obrońców i magistrów krwawych elfów. Natychmiast rozumiesz, że to odwrócenie uwagi, na które czeka Akama.>', 'Udaj się do wejścia do Czarnej Świątyni w Dolinie Cienistego Księżyca i porozmawiaj z Xi\'rim.', '', '', '', '', '', '', 0),
(10960, 'plPL', 'Kiedy dorosnę...', '$GWiedziałeś:Wiedziałaś;, kiedy $gbyłeś:byłaś; w moim wieku, kim chcesz zostać, gdy dorośniesz?$B$BJa nie wiem, kim chcę być. Może magiem albo czarnoksiężnikiem, jak już mówiłam? A może paladynem, Krwawym Rycerzem? Tak, na pewno Krwawym Rycerzem!$B$BPodobno prawdziwych szkoli się w Srebrnej Lunie, w twoim świecie. Zabierzesz mnie tam? Z opowieści, które słyszałam, wynika, że nauczyciele paladynów przebywają w tym mieście na Skwerze Obieżyświatów.$B$BProszę, zabierz mnie tam. Proszę!', 'Zabierz swoją sierotkę, Salandrię, do nauczycieli paladynów na Skwerze Obieżyświatów w Srebrnej Lunie. Jeśli po przybyciu nie będzie jej przy tobie, zawołaj ją. Następnie porozmawiaj z Lady Liadrin, matriarchą Krwawych Rycerzy.$B$BPamiętaj, że w mieście możesz korzystać z mapy, a o drogę do nauczycieli paladynów możesz zapytać strażników.', 'Salandria zaprowadzona do nauczycieli paladynów w Srebrnej Lunie', 'Porozmawiaj z Lady Liadrin w Srebrnej Lunie.', '', '', '', '', 0),
(10966, 'plPL', 'Powrót do sierocińca', 'A niech to! Chyba pora wracać do sierocińca w Shattrath.$B$BTak świetnie się bawiłam. Jesteś najlepszą osobą we wszystkich światach, $N! Jesteś teraz $gmoim starszym bratem:moją starszą siostrą;!$B$B<Oczy Dornai zaczynają wypełniać się łzami.>$B$BBędę za tobą strasznie tęsknić! Jak dorosnę, będę dokładnie taka jak ty!!!', 'Odprowadź swoją podopieczną do sierocińca w Shattrath, oddając gwizdek draenejskiej sieroty opiekunce sierocińca Mercy w Dolnym Mieście.', '', 'Wróć do opiekunki sierocińca Mercy w Shattrath.', '', '', '', '', 0),
(10967, 'plPL', 'Powrót do sierocińca', 'A niech to! Chyba pora wracać do sierocińca w Shattrath.$B$BTak świetnie się bawiłam. Jesteś najlepszą osobą we wszystkich światach, $N! Jesteś teraz $gmoim starszym bratem:moją starszą siostrą;!$B$B<Oczy Salandrii zaczynają wypełniać się łzami.>$B$BBędę za tobą strasznie tęsknić!!!', 'Odprowadź swoją podopieczną do sierocińca w Shattrath, oddając gwizdek sieroty krwawych elfów opiekunce sierocińca Mercy w Dolnym Mieście.', '', 'Wróć do opiekunki sierocińca Mercy w Shattrath.', '', '', '', '', 0),
(10983, 'plPL', 'Mog\'dorg Sędziwy', 'Mog\'dorg mądry! On wysłać Grok do miasta, szukać pomoc. Klan Krwawych Młotów potrzebować pomoc.$B$BMog\'dorg mówić, wysłać silne maluchy do niego w Góry Klingi. On stać na wieży przy Krwawym Kręgu. Mog\'dorg mądry!', 'Odwiedź Mog\'dorga Sędziwego na szczycie jednej z wież tuż przy Krwawym Kręgu w Górach Klingi.', '', '', '', '', '', '', 0),
(10984, 'plPL', 'Porozmawiaj z ogrem', '<Głos V\'eru wypełnia twój umysł krystalicznym tonem i czystością.>$B$BW Dolnym Mieście jest ogr, który błaga przechodniów o pomoc. Wszyscy pozostają głusi na jego niedolę.$B$BCzy zechcesz mu pomóc?$B$BNazywa się Grok i siedzi w pobliżu kupców na południowym wschodzie.$B$BDziękuję ci, $N.', 'Porozmawiaj z ogrem Grokiem w Dolnym Mieście w Shattrath.', '', '', '', '', '', '', 0),
(11007, 'plPL', 'Kael\'thas i zielona sfera', 'Powietrze wokół ciebie brzęczy – łagodnie brzęczy. Naaru wiedzą o twoim zwycięstwie. Może to przez nich coś kazało ci podnieść tę sferę z wciąż drgających szczątków Kael\'thasa Słońcobieżcy. Jakie sekrety może skrywać?$B$BMoże A\'dal w Shattrath zdoła zrozumieć, czym jest ten przedmiot.', 'Zanieś zieloną sferę A\'dalowi w Shattrath.', '', '', '', '', '', '', 0),
(11024, 'plPL', 'Sojusznik w Dolnym Mieście', 'W Dolnym Mieście jest arakkoa imieniem Rilak... Można mu ufać. Zanieś księgę... do niego.$B$B<Adaris traci przytomność, oddając ci księgę.>', 'Zanieś almanach Ishaala Rilakowi Odkupionemu w Dolnym Mieście w Shattrath.', '', 'Wróć do Rilaka Odkupionego w Dolnym Mieście w Shattrath.', '', '', '', '', 0),
(11028, 'plPL', 'Odliczanie do zagłady', 'Ten almanach zapowiada powrót Terokka, najpotężniejszego i najstraszliwszego króla Skettis w historii arakkoa.$B$BZawsze wierzyłem, że to tylko legenda, $N. Powrót szponokapłanów i odnalezienie przez ciebie tej księgi świadczą o czymś innym.$B$BZ każdym dniem Terokk jest bliżej odzyskania pełni sił. Jedyną szansą jest sprowadzenie go do naszego świata przedwcześnie. Wróć do Skettis i porozmawiaj o tym z Adarisem. Miejmy nadzieję, że starczy mu mądrości, by postąpić słusznie.', 'Wróć do podniebnego dowódcy Adarisa na Przystani Czarnego Wiatru w Puszczy Terokkar z wieściami o powrocie Terokka.', '', '', '', '', '', '', 0),
(11038, 'plPL', 'Wesprzyj egzarchę Orelisa', 'Niedawno arcykapłanka Ishanah wysłała do Burzy Otchłani niewielki oddział anachoretów pod dowództwem egzarchy Orelisa. Mieli zbadać działania Kael\'thasa i jego sług, ale nie otrzymaliśmy jeszcze żadnych raportów z ich ustaleń.$B$BObawiam się, że nasze siły w tym rejonie mogą nie wystarczyć do wykonania misji. Jestem pewien, że egzarcha skorzystałby na twojej wiedzy i doświadczeniu. Czy zechcesz udać się do Strefy 52 i go wesprzeć?', 'Porozmawiaj z egzarchą Orelisem w Strefie 52.', '', '', '', '', '', '', 0),
(11039, 'plPL', 'Zgłoś się do mistrza szpiegów Thalodiena', 'Jakiś czas temu Voren\'thal wysłał do Burzy Otchłani niewielki zespół, by zbadał działania Kael\'thasa. Nasz przywódca ma pełne zaufanie do mistrza szpiegów Thalodiena i jego towarzyszy i postanowił spełnić jego prośbę o posiłki.$B$BRaport Thalodiena był krótki, ale jasno wynikało z niego, że natrafił na coś bardzo ważnego. Zgłoś się do niego w Strefie 52 i pomóż mu, jak tylko zdołasz, $N.', 'Zgłoś się do mistrza szpiegów Thalodiena w Strefie 52.', '', '', '', '', '', '', 0),
(11045, 'plPL', 'Zorus Sędzia', 'Historia Doliny Cienistego Księżyca jest długa i burzliwa. Niewielu ją zgłębia z obawy, że tchną nowe życie w niewypowiedziane okropieństwa, do których tam doszło.$B$BNie wszyscy są jednak tak lękliwi. Zorus Sędzia szuka prawdy o duchach przeszłości Doliny Cienistego Księżyca. To ogromne przedsięwzięcie i jestem pewien, że chętnie przyjąłby pomoc.$B$BJeśli wybierzesz się do doliny, szukaj Zorusa w Warowni Dzikiego Młota, w środkowej części południa doliny.', 'Porozmawiaj z Zorusem Sędzią w Warowni Dzikiego Młota.', '', '', '', '', '', '', 0),
(11046, 'plPL', 'Główna aptekarka Hildagard', 'Historia Doliny Cienistego Księżyca jest długa i burzliwa. Niewielu ją bada z obawy, że tchną nowe życie w niewypowiedziane okropieństwa, do których tam doszło.$B$BNie wszyscy są jednak tak lękliwi. Badania głównej aptekarki Hildagard dotyczą duchów przeszłości Doliny Cienistego Księżyca. To ogromne przedsięwzięcie i jestem pewien, że chętnie przyjęłaby pomoc.$B$BJeśli podróże zaprowadzą cię w tamte strony, szukaj Hildagard w Wiosce Cienistego Księżyca, w północno-zachodniej części doliny.', 'Porozmawiaj z główną aptekarką Hildagard w Wiosce Cienistego Księżyca.', '', '', '', '', '', '', 0),
(11052, 'plPL', 'Obietnica Akamy', '<Akama umieszcza kryształ w medalionie, który trzyma w dłoni.>$B$BNie jestem już tak silny jak niegdyś, $N. Przez te wszystkie lata byłem tak blisko samego zła, że nie wiem, czy mogę sobie zaufać, mając artefakt tak potężny jak ten.$B$BWeź go jako moją obietnicę, że gdy nadejdzie czas i staniesz przed Illidanem, będę po twojej stronie. Zanieś go jedynej istocie, której na pewno możemy powierzyć jego moc. Zanieś medalion A\'dalowi w Shattrath.', 'Zanieś medalion Karaboru A\'dalowi w Shattrath.', '', 'Wróć do A\'dala w Shattrath w Puszczy Terokkar.', '', '', '', '', 0),
(11096, 'plPL', 'Zagrożenie z góry', 'Więc chcesz dołączyć do Podniebnej Straży? Cóż, wiem, że umiesz latać... ale czy umiesz walczyć?$B$BPodniebna Straż przysięgła chronić Shattrath przed zagrożeniami, które wiszą nad nami, bliskimi i dalekimi. Ogry Gordunni żyjące na Wzgórzach Bariery na północy są dla nas bezpośrednim zagrożeniem.$B$BDotarcie do ogrów sprawia kłopot naziemnym oddziałom Shattrath. I tu wkraczamy my. Zobacz, co możesz zrobić, by pomóc ich powstrzymać.', 'Zabij 20 dowolnych ogrów Gordunni na Wzgórzach Bariery i wróć do Yuuli w Shattrath.', '', 'Wróć do Yuuli w Puszczy Terokkar.', 'Ogr Gordunni', '', '', '', 0),
(11098, 'plPL', 'Do Skettis!', 'Wzgórza Bariery to tylko jeden z frontów, na które nas wysłano. Mniej pilne, ale znacznie groźniejsze zagrożenie czai się za Górami Skethyl, w mieście arakkoa – Skettis.$B$BKilka miesięcy temu nasi zwiadowcy wykryli tam ogromny wzrost aktywności arakkoa. Wkrótce potem doszło do kilku ataków na Shattrath. Od tamtej pory trzymamy siły pod ich miastem.$B$BZanieś te materiały wybuchowe sierżantowi Dorynowi na Przystani Czarnego Wiatru, tuż pod Skettis. Powiedz mu, że jesteś nowym rekrutem.', 'Zanieś paczkę materiałów wybuchowych podniebnemu sierżantowi Dorynowi na Przystani Czarnego Wiatru pod Skettis.', '', 'Wróć do podniebnego sierżanta Doryna w Dolinie Czarnego Wiatru w Puszczy Terokkar.', '', '', '', '', 0),
(11108, 'plPL', 'Lord Illidan Burzogniewny', 'Chodź, $gnajwyższy lordzie:najwyższa lady; $N. Sam Illidan na nas czeka!', 'Spotkaj się z Illidanem Burzogniewnym. Jeśli przeżyjesz, odszukaj Barthamusa w Dolnym Mieście w Shattrath.', 'Spotkanie z Illidanem Burzogniewnym', 'Wróć do Barthamusa w Shattrath w Puszczy Terokkar.', '', '', '', '', 0),
(11109, 'plPL', 'Jorus, kobaltowy smokowiec otchłanioskrzydły', '', '', '', '', '', '', '', '', 0),
(11110, 'plPL', 'Malfas, fioletowy smokowiec otchłanioskrzydły', '', '', '', '', '', '', '', '', 0),
(11111, 'plPL', 'Onyxien, onyksowy smokowiec otchłanioskrzydły', '', '', '', '', '', '', '', '', 0),
(11112, 'plPL', 'Suraku, lazurowy smokowiec otchłanioskrzydły', '', '', '', '', '', '', '', '', 0),
(11113, 'plPL', 'Voranaku, fiołkowy smokowiec otchłanioskrzydły', '', '', '', '', '', '', '', '', 0),
(11114, 'plPL', 'Zoya, seledynowy smokowiec otchłanioskrzydły', '', '', '', '', '', '', '', '', 0),
(11195, 'plPL', 'Zabawa lalkami', 'Jestem wzruszony, $N, i to prawda. Nie pamiętam, kiedy ostatnio jakiś $r wyciągnął Zungama z kłopotów.$b$bZwinąłem to jednemu z tych dzikusów, kiedy zakuwał mnie w łańcuchy. Nie wygląda na wiele, ale jeśli ktoś może ocenić, ile to warte, to mój dobry kumpel Griftah!$b$bJak wyjdziesz stąd $gżywy:żywa;, może warto zanieść mu to do Shattrath.', 'Zanieś postrzępioną lalkę wudu Griftahowi w Shattrath.', '', 'Wróć do Griftaha w Shattrath.', '', '', '', '', 0),
(11354, 'plPL', 'Poszukiwana: Szpicruta Nazana', 'Mam dziś kupca, którego interesuje przedmiot będący w posiadaniu wierzchowca herolda Illidana. Mowa oczywiście o Vazrudenie Heroldzie i jego smoczym wierzchowcu, Nazanie.$B$BJeśli chcesz dostać znaleźne, które oferuję, odszukaj ich na niebie nad Wałami Cytadeli Piekielnego Ognia i wróć ze szpicrutą smoka.$B$BMoje źródła donoszą, że ten przedmiot trzyma przy sobie sam smok. Podobno Nazan nie pozwala Vazrudenowi, by go nią smagał.', 'Handlarz wiatru Zhareem poprosił cię o zdobycie Szpicruty Nazana. Dostarcz mu ją do Dolnego Miasta w Shattrath, aby odebrać nagrodę.$B$BTo zadanie można wykonać tylko na poziomie heroicznym.', '', 'Wróć do handlarza wiatru Zhareema w Puszczy Terokkar.', '', '', '', '', 0),
(11362, 'plPL', 'Poszukiwany: Pierzasty kostur Keli\'dana', 'O gustach się nie dyskutuje. Weźmy choćby mojego ostatniego kupca.$B$BW Cytadeli Piekielnego Ognia przebywa krwawy ork zwany Keli\'danem Ciemiężcą. Nosi przy sobie najzwyklejszy kostur – nic, na co warto by spojrzeć drugi raz. A jednak właśnie tego pragnie mój klient.$B$BKimże jestem, by odmówić?$B$BJeśli chcesz mojej zapłaty, znajdziesz Keli\'dana i jego kostur w Krwawym Piecu.', 'Handlarz wiatru Zhareem poprosił cię o zdobycie Pierzastego kostura Keli\'dana. Dostarcz mu go do Dolnego Miasta w Shattrath, aby odebrać nagrodę.$B$BTo zadanie można wykonać tylko na poziomie heroicznym.', '', 'Wróć do handlarza wiatru Zhareema w Puszczy Terokkar.', '', '', '', '', 0),
(11363, 'plPL', 'Poszukiwana: Pieczęć Brzytworękiego', 'Mam dziś bardzo zamożnego kolekcjonera, który potrzebuje czegoś naprawdę wyjątkowego.$B$BWódz wojenny Kargath Brzytworęki nosi przy sobie pieczęć dowódcy, którą sygnuje wszystkie oficjalne dokumenty. Chcę, żebyś mi ją $gzdobył:zdobyła;.$B$BZnajdziesz go głęboko w Strzaskanych Salach. Bez wątpienia będziesz $gmusiał:musiała; przedrzeć się przez istną armię, żeby do niego dotrzeć. Nie wątpię jednak, że ci się uda.', 'Handlarz wiatru Zhareem poprosił cię o zdobycie Pieczęci Brzytworękiego. Dostarcz mu ją do Dolnego Miasta w Shattrath, aby odebrać nagrodę.$B$BTo zadanie można wykonać tylko na poziomie heroicznym.', '', 'Wróć do handlarza wiatru Zhareema w Puszczy Terokkar.', '', '', '', '', 0),
(11364, 'plPL', 'Poszukiwani: centurioni Strzaskanej Dłoni', 'Czy kwestionujesz swojego pana? Mah\'duun też nie.$B$BSzukam krwi centurionów klanu Strzaskanej Dłoni. Znajdziesz ich w Strzaskanych Salach Cytadeli Piekielnego Ognia.$B$BJeśli chcesz nagrody, nie wracaj, dopóki nie zabijesz ich wszystkich.', 'Tropiciel Otchłani Mah\'duun zlecił ci zabicie 4 centurionów Strzaskanej Dłoni. Gdy wszyscy będą martwi, wróć do niego do Dolnego Miasta w Shattrath po nagrodę.', '', 'Wróć do tropiciela Otchłani Mah\'duuna w Puszczy Terokkar.', '', '', '', '', 0),
(11368, 'plPL', 'Poszukiwane: Serce Quagmirrana', 'Mam nietypową prośbę. Pewna zamożna osoba, z którą utrzymuję kontakt poza tym światem, interesuje się makabrycznym okazem.$B$BA dokładnie – chce serca Quagmirrana.$B$BSłyszałem, że ta bestia ma trzy, ale do naszych celów jedno wystarczy. O ile wiem, Quagmirran spoczywa w głębokim zbiorniku wody w Zagrodach Niewolników.', 'Handlarz wiatru Zhareem poprosił cię o zdobycie Serca Quagmirrana. Dostarcz mu je do Dolnego Miasta w Shattrath, aby odebrać nagrodę.$B$BTo zadanie można wykonać tylko na poziomie heroicznym.', '', 'Wróć do handlarza wiatru Zhareema w Puszczy Terokkar.', '', '', '', '', 0),
(11369, 'plPL', 'Poszukiwane: Jajo Czarnego Tropiciela', 'Na Moczarach Zangarskich jest zawsze tylko jedna wielka matka bagiennych wędrowców. Zawsze nazywa się ją Czarnym Tropicielem, a wykluwa się z jednego z jaj, które zostają po śmierci jej matki.$B$BMam kupca, który interesuje się jednym z tych jaj. Wspominał coś o tym, że zrobi z niej atrakcję swojego zwierzyńca.$B$BJeśli interesuje cię oferowana przeze mnie nagroda, udaj się do Podbagna i zabij Czarnego Tropiciela, by zdobyć jej jajo.', 'Handlarz wiatru Zhareem chce, żebyś $gzdobył:zdobyła; Jajo Czarnego Tropiciela. Dostarcz mu je do Dolnego Miasta w Shattrath, aby odebrać nagrodę.$B$BTo zadanie można wykonać tylko na poziomie heroicznym.', '', 'Wróć do handlarza wiatru Zhareema w Puszczy Terokkar.', '', '', '', '', 0),
(11370, 'plPL', 'Poszukiwany: Traktat wodza', 'Wiadomo, że wódz nag Kalithresh sam w sobie jest wielkim wojownikiem, ale mniej osób wie, że spisał całą swoją wiedzę.$B$BJeden z moich klientów jednak o tym wie i bardzo chce zdobyć jego traktat.$B$BProszę, udaj się do Krypty Pary w Zbiorniku Żmijokolców i zdobądź dla mnie tę księgę.', 'Handlarz wiatru Zhareem poprosił cię o zdobycie Traktatu wodza. Dostarcz mu go do Dolnego Miasta w Shattrath, aby odebrać nagrodę.$B$BTo zadanie można wykonać tylko na poziomie heroicznym.', '', 'Wróć do handlarza wiatru Zhareema w Puszczy Terokkar.', '', '', '', '', 0),
(11371, 'plPL', 'Poszukiwani: siepacze Żmijokolców', 'Mah\'duun słyszy i jest posłuszny, a teraz proszę, byś ty $gzostał:została; moim narzędziem.$B$BPrzekazano mi, że siepacze plemienia Żmijokolców muszą zostać zniszczeni. Szukaj ich w dusznych wnętrzach Krypty Pary pod Zbiornikiem Żmijokolców.$B$BNie przyjmę niczego poza ich całkowitą zagładą.', 'Tropiciel Otchłani Mah\'duun poprosił cię o zabicie 14 siepaczy Żmijokolców. Gdy wszyscy będą martwi, wróć do niego do Dolnego Miasta w Shattrath po nagrodę.', '', 'Wróć do tropiciela Otchłani Mah\'duuna w Puszczy Terokkar.', '', '', '', '', 0),
(11372, 'plPL', 'Poszukiwany: Pióropusz Ikissa', 'Niedawno zwróciła się do mnie taurenka, której mąż wkrótce zostanie wodzem. Chce w wyjątkowy sposób ozdobić jego pióropusz.$B$BA dokładnie – chce zdobyć pióra z głowy nikczemnego Szponiego Króla Ikissa.$B$BJeśli chcesz zgarnąć moją nagrodę, udaj się do Sal Sethekk w Auchindoun i go odnajdź.', 'Handlarz wiatru Zhareem poprosił cię o zdobycie Pióropusza Ikissa. Dostarcz mu go do Dolnego Miasta w Shattrath, aby odebrać nagrodę.$B$BTo zadanie można wykonać tylko na poziomie heroicznym.', '', 'Wróć do handlarza wiatru Zhareema w Puszczy Terokkar.', '', '', '', '', 0),
(11373, 'plPL', 'Poszukiwany: Cudowny amulet Shaffara', 'Dziś mam do ciebie osobistą prośbę, ale nagroda z pewnością będzie odpowiadać niebezpieczeństwu.$B$BMoja rodzina ma, powiedzmy, pewną „historię” z księciem Nexusa Shaffarem i jego poplecznikami. Gdyby amulet, który nosi, trafił w moje ręce, z pewnością oznaczałoby to, że się z nim rozprawiono.$B$BJeśli interesuje cię oferowana przeze mnie nagroda, wyrusz do jego leża w Grobowcach Many w Auchindoun.', 'Handlarz wiatru Zhareem chce, żebyś $gzdobył:zdobyła; Cudowny amulet Shaffara. Dostarcz mu go do Dolnego Miasta w Shattrath, aby odebrać nagrodę.$B$BTo zadanie można wykonać tylko na poziomie heroicznym.', '', 'Wróć do handlarza wiatru Zhareema w Puszczy Terokkar.', '', '', '', '', 0),
(11374, 'plPL', 'Poszukiwany: Klejnot dusz egzarchy', 'W Kryptach Auchenai w Auchindoun prowadzi się wiele odrażających eksperymentów w dążeniu do głębszego zrozumienia sztuk nekromanckich. Wiele duchów jest tam torturowanych lub niszczonych.$B$BMam klienta, któremu zależy na uwolnieniu jednego z tych duchów. Doniesiono mi, że duch ten jest uwięziony w klejnocie dusz, który posiada nie kto inny jak sam egzarcha Maladaar.$B$BOdszukaj go w kryptach jak najszybciej i wróć do mnie z klejnotem.', 'Handlarz wiatru Zhareem poprosił cię o odzyskanie Klejnotu dusz egzarchy. Dostarcz mu go do Dolnego Miasta w Shattrath, aby odebrać nagrodę.$B$BTo zadanie można wykonać tylko na poziomie heroicznym.', '', 'Wróć do handlarza wiatru Zhareema w Puszczy Terokkar.', '', '', '', '', 0),
(11375, 'plPL', 'Poszukiwany: Szept Szmeru', 'Kiedy skończę mówić, możesz nie chcieć przyjąć tego zlecenia.$B$BMam ekscentrycznego klienta, który specjalizuje się w badaniu martwych rzeczywistości. Krążą pogłoski, że istota zwana Szmerem zniszczyła ostatni świat, z którego ją przyzwano. Profesor chce zbadać jej „szept”, jak to nazwał, by zrozumieć, jak Szmer tego dokonał.$B$BUdasz się do Labiryntu Cieni w Auchindoun i zdobędziesz go dla mnie?', 'Handlarz wiatru Zhareem poprosił cię o zdobycie Szeptu Szmeru. Dostarcz mu go do Dolnego Miasta w Shattrath, aby odebrać nagrodę.$B$BTo zadanie można wykonać tylko na poziomie heroicznym.', '', 'Wróć do handlarza wiatru Zhareema w Puszczy Terokkar.', '', '', '', '', 0),
(11376, 'plPL', 'Poszukiwane: złośliwe instruktorki', 'Mah\'duun słyszał, że nikt nie jest tak okrutny jak sześcioramienne demonice z Labiryntu Cieni.$B$BUdaj się do Auchindoun, odszukaj je i zabij je wszystkie.$B$BJeśli nie potrafisz wykonać tak prostego zadania, nie mamy sobie nic więcej do powiedzenia.', 'Tropiciel Otchłani Mah\'duun chce, żebyś $gzabił:zabiła; 3 złośliwe instruktorki. Gdy wszystkie będą martwe, wróć do niego do Dolnego Miasta w Shattrath po nagrodę.', '', 'Wróć do tropiciela Otchłani Mah\'duuna w Puszczy Terokkar.', '', '', '', '', 0),
(11377, 'plPL', 'Zemsta jest smaczna', 'Dziś wieczorem zajmuję się wyżywieniem dość nietypowych gości na przyjęciu. Jeden z nich latał nad Skettis i potworny kaliri strącił go na ziemię – ma paskudnie złamaną nogę.$b$bNa przyjęcie z okazji jego powrotu do zdrowia zamówili coś specjalnego: gulasz z kaliri.$b$bMogę ci pożyczyć mój kociołek, żebyś $gugotował:ugotowała; dla mnie porcję gulaszu. Sam przepis jest prosty, ale będziesz potrzebować olbrzymiego skrzydła kaliri i kilku upieczonych burgerów z tropiciela wypaczenia.', 'Rokk z Dolnego Miasta poprosił cię, żebyś $gugotował:ugotowała; w jego kociołku Gulasz z kaliri. Gdy skończysz, wróć do niego.', '', 'Wróć do Rokka w Puszczy Terokkar.', '', '', '', '', 0),
(11378, 'plPL', 'Poszukiwana: Głowa Łowcy Epok', 'Gusta moich klientów sięgają od przyziemnych po egzotyczne. A czasem chcą robić bardzo przyziemne rzeczy z egzotycznymi przedmiotami, których szukają.$B$BTak jest z moim najnowszym zamówieniem. Mój klient, który pozostanie bezimienny, chce zdobyć głowę Łowcy Epok, by powiesić ją na ścianie.$B$B$N, czy znajdziesz sposób, by cofnąć się w czasie do Starego Międzygórza i zdobyć tę głowę dla mojego kolekcjonera trofeów?', 'Handlarz wiatru Zhareem poprosił cię o zdobycie Głowy Łowcy Epok. Dostarcz mu ją do Dolnego Miasta w Shattrath, aby odebrać nagrodę.$B$BTo zadanie można wykonać tylko na poziomie heroicznym.', '', 'Wróć do handlarza wiatru Zhareema w Puszczy Terokkar.', '', '', '', '', 0),
(11379, 'plPL', 'Gulasz na ostro', 'Próbuję wymyślić coś z prawdziwym pazurem. Ale szczerze mówiąc, ostatnio jestem raczej goblinem od pomysłów. Straciłem ducha przygody.$b$bAle ty... przypominasz mi moje młode lata, kiedy byłem gotów podbić świat z mieczem w jednej ręce i patelnią w drugiej.$b$bChcę, żebyś $gwziął:wzięła; mój ukochany kociołek i $gruszył:ruszyła; w Góry Klingi. Wrzuć do niego żeberka i chrupkiego węża – już ugotowane, dla lepszego smaku – i zapiecz to nad zwłokami otchłańca, bo tylko one są dość gorące, żeby się udało.', 'Rokk z Dolnego Miasta poprosił cię, żebyś w jego kociołku $gprzyrządził:przyrządziła; Demoniczną niespodziankę z rusztu z dwóch porcji Żeberek Mok\'Nathalów i Chrupkiego węża. Gdy skończysz, wróć do niego.', '', 'Wróć do Rokka w Puszczy Terokkar.', '', '', '', '', 0),
(11380, 'plPL', 'Manapyszności', 'No i masz ci los – myślę, że moja spiżarnia jest aktualna, a tu ktoś przychodzi i zamawia coś nietypowego: rozkosz z jagód many.$b$bNiestety, jagody many rosną tylko w ekokopułach Burzy Otchłani. Tylko nie trać czasu na szukanie wokół Burzowej Iglicy – tam wszystko już wyzbierano.$b$bWybór najlepszych jagód mogę powierzyć tylko komuś obeznanemu ze sztuką kulinarną, więc nie zawiedź mnie!', 'Rokk z Dolnego Miasta poprosił cię o zebranie 15 jagód many z ekokopuł w Burzy Otchłani.', '', 'Wróć do Rokka w Puszczy Terokkar.', '', '', '', '', 0),
(11381, 'plPL', 'Zupa dla duszy', 'Śmierć wisi w powietrzu. Jeszcze nigdy nie miałem tylu zamówień na moją słynną zupę – podnosi na duchu i koi duszę.$b$bA kolegę po fachu poznam na pierwszy rzut oka! Chcesz mi pomóc i dostać działkę z zysków?$b$bMasz, weź mój kociołek, zdobądź trochę mięsa z rozłupokopyta, a zdradzę ci mały sekret. Co sprawia, że moja zupa tak dobrze robi na duszę? To nie rosół z kury – gotuję ją na Ziemiach Przodków w Nagrandzie, żeby nasiąkła całą tamtejszą duchowością.', 'Rokk z Dolnego Miasta poprosił cię, żebyś w jego kociołku $gprzyrządził:przyrządziła; Duchową zupę. Gdy skończysz, wróć do niego.', '', 'Wróć do Rokka w Puszczy Terokkar.', '', '', '', '', 0),
(11382, 'plPL', 'Poszukiwana: Klepsydra Aeonusa', 'Przysięgam, niektórzy moi klienci są szaleni. Są przedmioty, po które się sięga, i takie, o których nie śmie się nawet myśleć!$B$BMój obecny klient to ewidentnie skończony szaleniec. Pożąda klepsydry, którą trzyma Aeonus.$B$BTak, dobrze słyszysz – Aeonus z Nieskończonego Stada!$B$BKimże jestem, by się spierać, skoro płaci królewski okup? No więc, $ggotów:gotowa; udać się do Jaskiń Czasu i przenieść się na Czarne Mokradła, by ją dla mnie zdobyć?', 'Handlarz wiatru Zhareem poprosił cię o zdobycie Klepsydry Aeonusa. Dostarcz mu ją do Dolnego Miasta w Shattrath, aby odebrać nagrodę.$B$BTo zadanie można wykonać tylko na poziomie heroicznym.', '', 'Wróć do handlarza wiatru Zhareema w Puszczy Terokkar.', '', '', '', '', 0),
(11383, 'plPL', 'Poszukiwani: władcy szczelin', 'Mah\'duun wie, dokąd musisz iść. Mah\'duun wie, że musisz zabić władców szczelin. Ale Mah\'duun nie wie dokładnie kiedy.$B$BWiem, że to nie ma sensu, ale głos na wietrze nie był bardziej konkretny.$B$BPrzejdź przez Jaskinie Czasu na Czarne Mokradła, a droga stanie się jasna.', 'Tropiciel Otchłani Mah\'duun chce, żebyś $gzabił:zabiła; 4 władców szczelin. Gdy wszyscy będą martwi, wróć do niego do Dolnego Miasta w Shattrath po nagrodę.', '', 'Wróć do tropiciela Otchłani Mah\'duuna w Puszczy Terokkar.', '', '', '', '', 0),
(11384, 'plPL', 'Poszukiwana: Szczepka Spaczodrzazga', 'Niedawno zwróciła się do mnie druidka kaldorei ze wzruszającą prośbą. I z mnóstwem złota, rzecz jasna!$B$BWygląda na to, że siły Darnassus pragną odrodzić pradrzewiec magii tajemnej zwany Spaczodrzazgiem. To olbrzymie drzewo zostało zmącone albo splugawione – nie jestem pewien – ale znajdziesz je w Botanice w Twierdzy Burz.$B$BPowiedziała, że do ponownego wyhodowania go wystarczy im mała szczepka.', 'Handlarz wiatru Zhareem poprosił cię o zdobycie Szczepki Spaczodrzazga. Dostarcz mu ją do Dolnego Miasta w Shattrath, aby odebrać nagrodę.$B$BTo zadanie można wykonać tylko na poziomie heroicznym.', '', 'Wróć do handlarza wiatru Zhareema w Puszczy Terokkar.', '', '', '', '', 0),
(11385, 'plPL', 'Poszukiwani: kanalizatorzy Słońcoszukaczy', 'Wyszeptano Mah\'duunowi, że kanalizatorzy z oddziału wojskowego zwanego Słońcoszukaczami muszą dziś zginąć.$B$BZnajdziesz ich w Botanice w Twierdzy Burz.$B$BChcesz nagrody – zabij kanalizatorów.', 'Tropiciel Otchłani Mah\'duun chce, żebyś $gzabił:zabiła; 6 kanalizatorów Słońcoszukaczy. Gdy wszyscy będą martwi, wróć do niego do Dolnego Miasta w Shattrath po nagrodę.', '', 'Wróć do tropiciela Otchłani Mah\'duuna w Puszczy Terokkar.', '', '', '', '', 0),
(11386, 'plPL', 'Poszukiwany: Projektor Pathaleona', 'Zawsze zakładałem, że Pathaleon Rachmistrz wyświetla swój wizerunek po całej Rubieży za pomocą magii. Najwyraźniej się myliłem.$B$BMój najnowszy klient twierdzi, że ten krwawy elf porozumiewa się z kierownikami specjalnych projektów księcia Kael\'thasa za pomocą mechanicznego urządzenia. O ile wiem, zdobył je od rebeliantów Zaxxis w Burzy Otchłani.$B$BMój klient chce zdobyć ten projektor. Może złożysz Pathaleonowi wizytę? Znajdziesz go w Mechanarze w Twierdzy Burz.', 'Handlarz wiatru Zhareem poprosił cię o zdobycie Projektora Pathaleona. Dostarcz mu go do Dolnego Miasta w Shattrath, aby odebrać nagrodę.$B$BTo zadanie można wykonać tylko na poziomie heroicznym.', '', 'Wróć do handlarza wiatru Zhareema w Puszczy Terokkar.', '', '', '', '', 0),
(11387, 'plPL', 'Poszukiwani: niszczyciele z Kuźni Burz', 'W Mechanarze są mechaniczne konstrukty, które według tego, co usłyszał Mah\'duun, trzeba rozmontować.$B$BUdaj się do Twierdzy Burz, znajdź niszczycieli z Kuźni Burz i zniszcz ich.$B$BPotem możesz wrócić po nagrodę.', 'Tropiciel Otchłani Mah\'duun chce, żebyś $gzniszczył:zniszczyła; 5 niszczycieli z Kuźni Burz. Gdy wszyscy zostaną zniszczeni, wróć do niego do Dolnego Miasta w Shattrath po nagrodę.', '', 'Wróć do tropiciela Otchłani Mah\'duuna w Puszczy Terokkar.', '', '', '', '', 0),
(11388, 'plPL', 'Poszukiwany: Zwój Skyrissa', 'Dzisiejszy klient szuka czegoś naprawdę wyjątkowego.$B$BPowiada się, że Zwiastun Skyriss jest sługą Przedwiecznych. Mówi się też, że nosi przy sobie wielki zwój z ich instrukcjami, jak w ich imieniu zapanować nad życiem we wszechświecie.$B$BMój obecny kupiec chce dostać ten zwój w swoje ręce, choć i tak nie odczyta zapisanego na nim języka.$B$BUdaj się do Arkatrazu w Twierdzy Burz i zdobądź go dla mnie, dobrze, $N?', 'Handlarz wiatru Zhareem poprosił cię o zdobycie Zwoju Skyrissa. Dostarcz mu go do Dolnego Miasta w Shattrath, aby odebrać nagrodę.$B$BTo zadanie można wykonać tylko na poziomie heroicznym.', '', 'Wróć do handlarza wiatru Zhareema w Puszczy Terokkar.', '', '', '', '', 0),
(11389, 'plPL', 'Poszukiwani: wartownicy Arkatrazu', 'Wartownicy w Arkatrazie oszaleli. Więźniowie szaleją na wolności, a strażnicy atakują tych, którzy chcieliby pomóc.$B$BMah\'duun słyszy tego, który przemawia na wiatrach Otchłani. Mówi on, by zniszczyć wartowników.$B$BDokonaj tego, a dzisiejsza nagroda będzie twoja.', 'Tropiciel Otchłani Mah\'duun chce, żebyś $grozmontował:rozmontowała; 5 wartowników Arkatrazu. Gdy tego dokonasz, wróć do niego do Dolnego Miasta w Shattrath po nagrodę.', '', 'Wróć do tropiciela Otchłani Mah\'duuna w Puszczy Terokkar.', '', '', '', '', 0),
(11481, 'plPL', 'Kryzys przy Słonecznej Studni', 'Na naaru, dziękuję ci za twoje wysiłki.$b$bNasza praca jest jednak daleka od końca i muszę cię prosić o podjęcie się kluczowej misji – równie ważnej jak każda, którą dotąd zleciłem.$b$bNasze siły są rozproszone. Na domiar złego musieliśmy wysłać oddział do Azeroth, by zbadał wydarzenia na Płaskowyżu Słonecznej Studni.$b$bJesteś tam $gpotrzebny:potrzebna;, $N. Zamelduj się u Larethora. Powiedz mu, że żałuję, iż nie mogę posłać więcej ludzi.', 'Adyen Strażnik Światła ze Wzniesienia Aldorów w Shattrath poprosił cię, żebyś $gudał:udała; się na Płaskowyż Słonecznej Studni i $gporozmawiał:porozmawiała; z Larethorem.', '', '', '', '', '', '', 0),
(11482, 'plPL', 'Obowiązek wzywa', 'Posłuchaj mnie.$b$bObowiązek wymaga, byś $gwrócił:wróciła; do Azeroth. Każdy, kto jest zdolny do walki, ma się natychmiast stawić na Płaskowyżu Słonecznej Studni.$b$bObawiam się, że nie mam więcej informacji, poza jedną:$b$bW tej misji połączysz siły z Aldorami. Po przybyciu porozmawiaj z draeneiem imieniem Larethor.$b$bNajwyraźniej sytuacja wymaga, abyśmy odłożyli nasze spory na bok i połączyli siły.$b$bPrzygotuj się, przyjacielu. To brzmi poważnie.', 'Dathris Słońcobij z Tarasu Widzących w Shattrath nalegał, byś natychmiast $gudał:udała; się do Azeroth i $gzameldował:zameldowała; się u Larethora przy Słonecznej Studni.', '', '', '', '', '', '', 0),
(11497, 'plPL', 'Nauka latania', 'Choć na dłuższą metę może to zaszkodzić moim interesom, wyglądasz mi na kogoś, kto marzy o tym, by przemierzać niebo na własnym wierzchowcu, a nie być przewożonym z miejsca na miejsce.$B$BDoskonale to rozumiem.$B$BTy, przyjacielu, musisz się udać do Warowni Dzikiego Młota w południowo-zachodnim zakątku Doliny Cienistego Księżyca. Na miejscu porozmawiaj z Ilsą Burzowar o nauce latania. Pamiętaj, że jej szkolenie nie jest tanie. Ale myślę, że uznasz, iż warto.', 'Porozmawiaj z Ilsą Burzowar w Warowni Dzikiego Młota w Dolinie Cienistego Księżyca.', '', '', '', '', '', '', 0),
(11498, 'plPL', 'Nauka latania', 'Choć na dłuższą metę może to zaszkodzić moim interesom, wyglądasz mi na kogoś, kto marzy o tym, by przemierzać niebo na własnym wierzchowcu, a nie być przewożonym z miejsca na miejsce.$B$BDoskonale to rozumiem.$B$BTy, przyjacielu, musisz się udać do Wioski Cienistego Księżyca w północno-zachodnim zakątku Doliny Cienistego Księżyca. Na miejscu porozmawiaj z Olrokkiem o nauce latania. Pamiętaj, że jego szkolenie nie jest tanie. Ale myślę, że uznasz, iż warto.', 'Porozmawiaj z Olrokkiem w Wiosce Cienistego Księżyca w Dolinie Cienistego Księżyca.', '', '', '', '', '', '', 0),
(11499, 'plPL', 'Poszukiwany: Sygnet księcia Kael\'thasa', '$N, dziś proszę o niemożliwe. Dziś musisz zdobyć sygnet Kael\'thasa Słońcobieżcy, władcy krwawych elfów!$B$BTo prawda, pogłoski o jego śmierci w Twierdzy Burz okazały się bezpodstawne. Pojawił się ponownie, tym razem na Tarasie Magistrów na Wyspie Quel\'Danas. Co tam robi, to opowieść, którą przekaże ci ktoś inny. Ja wiem tyle, że mam niezliczonych kolekcjonerów zainteresowanych jego książęcym pierścieniem i zamierzam go dla nich zdobyć.$B$BA raczej zamierzam, żebyś to ty go $gzdobył:zdobyła;.', 'Handlarz wiatru Zhareem poprosił cię o zdobycie Sygnetu księcia Kael\'thasa. Dostarcz mu go do Dolnego Miasta w Shattrath, aby odebrać nagrodę.$B$BTo zadanie można wykonać tylko na Tarasie Magistrów na poziomie heroicznym.', '', 'Wróć do handlarza wiatru Zhareema w Puszczy Terokkar.', '', '', '', '', 0),
(11500, 'plPL', 'Poszukiwane: Siostry Udręki', 'Wyszeptano Mah\'duunowi, że Siostry Udręki mają zostać odesłane do piekieł, z których się wywodzą.$B$BMah\'duun wie, że te demony można znaleźć na Tarasie Magistrów na Wyspie Quel\'Danas.$B$BZrobisz to, by zdobyć nagrodę, albo nie.', 'Tropiciel Otchłani Mah\'duun chce, żebyś $gzabił:zabiła; 4 Siostry Udręki. Gdy tego dokonasz, wróć do niego do Dolnego Miasta w Shattrath po nagrodę.', '', 'Wróć do tropiciela Otchłani Mah\'duuna w Puszczy Terokkar.', '', '', '', '', 0),
(11517, 'plPL', 'Zamelduj się u Nasuuna', 'Bardzo się cieszę, że tu jesteś, $N! Teraz, gdy zajęliśmy to sanktuarium, musimy szybko stworzyć magiczny portal, który będzie tu prowadził z Shattrath na Rubieży.$B$BMój pan, egzarcha Nasuun, kieruje tymi działaniami Ofensywy. Poprosił mnie, bym przysyłał mu obiecujących kandydatów, którzy mają to, czego trzeba, by pomóc w tworzeniu portalu.$B$BUdaj się, proszę, do Shattrath i porozmawiaj z nim w komnacie A\'dala na Tarasie Światła.', 'Handlarz Portanuus poprosił cię, żebyś $gporozmawiał:porozmawiała; z egzarchą Nasuunem na Tarasie Światła w Shattrath.', '', '', '', '', '', '', 0),
(11534, 'plPL', 'Zamelduj się u Nasuuna', 'Bardzo się cieszę, że tu jesteś, $N! Kiedy odbiliśmy to sanktuarium z rąk Nędznych, szybko stworzyliśmy magiczny portal, który prowadzi tu z Shattrath na Rubieży.$B$BMój pan, egzarcha Nasuun, kieruje działaniami Ofensywy, by utrzymać ten portal. Poprosił mnie, bym przysyłał mu obiecujących kandydatów, którzy mają to, czego trzeba, by pomóc w zdobywaniu dodatkowej energii do jego zasilania.$B$BUdaj się, proszę, do Shattrath i porozmawiaj z nim w komnacie A\'dala na Tarasie Światła.', 'Handlarz Portanuus poprosił cię, żebyś $gporozmawiał:porozmawiała; z egzarchą Nasuunem na Tarasie Światła w Shattrath.', '', '', '', '', '', '', 0),
(11550, 'plPL', 'Oto nadchodzi Zwodziciel...', 'Mimo naszych najlepszych starań złowrogie plany Kael\'thasa zostały zrealizowane. Słoneczna Studnia została ponownie rozpalona, by przygotować przybycie Zwodziciela.$B$BObiekt, który stoi przede mną, pod A\'dalem, przedstawia obecny stan obrony Słonecznej Studni. Wzniesiono potężne bariery, które powstrzymują nasze ataki na wewnętrzne komnaty. Jeśli kiedykolwiek nasz świat potrzebował pomocy, to właśnie teraz.$B$BZamelduj się u arcymaga Ne\'thula na Wyspie Quel\'Danas, na północ od Quel\'Thalas.', 'Zamelduj się u arcymaga Ne\'thula na Wyspie Quel\'Danas, na północ od Quel\'Thalas.$B$BLotmistrzowie w Żelaznej Kuźni i Srebrnej Lunie dowiozą cię na miejsce.', '', '', '', '', '', '', 0),
(11875, 'plPL', 'Zdobycie przewagi', 'Oddziały Ofensywy Straceńczego Słońca będą potrzebować każdej możliwej przewagi, by odeprzeć sojuszników Kil\'jaedena. Moi koledzy w Wichrogrodzie stworzyli oleje, które wzmocnią ostrza i pancerze naszych żołnierzy.$B$BKluczowy składnik, pozostałości Otchłani, przenika całą Rubież – jeśli wie się, gdzie szukać. Każdy mistrz zielarstwa, skórowania lub górnictwa, który zna oznaki, może je zebrać przy wykonywaniu swojego fachu. Pozostałości mogą się znajdować we wszystkich ziołach, rudach i zwierzętach pochodzących z Rubieży.', 'Przynieś 8 porcji pozostałości Otchłani emisariuszowi Mordinowi w Shattrath.', '', 'Wróć do emisariusza Mordina w Puszczy Terokkar.', '', '', '', '', 0),
(11877, 'plPL', 'Plany ataku Słonecznej Furii', 'Podczas naszej ofensywy na Quel\'Danas odkryliśmy, że poplecznicy Kael\'thasa planują kontratak. Rozkazując krwawym elfom Słonecznej Furii, które stacjonują w Burzy Otchłani, zaatakować nasze placówki na Rubieży, liczy, że odciągnie wojska i uwagę od Słonecznej Studni.$B$BNie możemy do tego dopuścić, $N. Na linii frontu potrzebne jest każde ostrze.$B$BUdaj się do Burzy Otchłani i zdobądź ich plany ataku. Może je mieć przy sobie każdy krwawy elf Słonecznej Furii, który tam przebywa. Powodzenia, $N.', 'Lord Torvos w Shattrath chce, żebyś $gzdobył:zdobyła; Plany ataku Słonecznej Furii.', '', 'Wróć do lorda Torvosa w Shattrath.', '', '', '', '', 0),
(11880, 'plPL', 'Pomiary wielofazowe', 'Jestem pewien, że ten „gnomi wynalazca” to wariat. Bredził coś o mrocznych zakłóceniach, które zaczęły się pojawiać na Polach Duchów wokół Oshu\'gun w Nagrandzie.$B$BWedług niego te, eee, wielofazowe... hm, spektrogogle pozwolą temu, kto je nosi, zobaczyć zakłócenia i wykonać ich pomiary. Upierał się, że zapisanie tych danych ma zasadnicze znaczenie dla naszej kampanii przy Słonecznej Studni. Moim zdaniem ma nie po kolei w głowie, ale mam rozkaz badać wszystko, co mogłoby pomóc. Czy $gmógłbyś:mogłabyś; wykonać parę pomiarów?', 'Zwiastun Haronem w Shattrath chce, żebyś $gużył:użyła; Wielofazowych gogli spektrograficznych i $gwykonał:wykonała; 6 pomiarów wielofazowych.', '', 'Wróć do Zwiastuna Haronema na Tarasie Światła w Shattrath.', 'Wykonane pomiary wielofazowe', '', '', '', 0),
(12479, 'plPL', 'Naprzód, do Północnej Grani!', 'Witaj w alfie Wrath of the Lich King dla przyjaciół i rodziny. Skorzystaj z portali obok mnie, by rozpocząć podróż do Północnej Grani.$B$BMożesz zgłosić się do werbownika Przymierza w Twierdzy Walecznych w Boreańskiej Tundrze albo udać się do Valgardu w Wyjącym Fiordzie.', 'Porozmawiaj z werbownikiem Przymierza w Twierdzy Walecznych w Boreańskiej Tundrze albo z tym w Przystani Zemsty w Wyjącym Fiordzie.', '', '', '', '', '', '', 0),
(12480, 'plPL', 'Naprzód, do Północnej Grani!', 'Witaj w alfie Wrath of the Lich King dla przyjaciół i rodziny. Skorzystaj z portali obok mnie, by rozpocząć podróż do Północnej Grani.$B$BMożesz zgłosić się do werbownika Hordy w Warowni Wojennej Pieśni w Boreańskiej Tundrze albo udać się do Przystani Zemsty w Wyjącym Fiordzie.', 'Porozmawiaj z werbownikiem Hordy w Warowni Wojennej Pieśni w Boreańskiej Tundrze albo w Przystani Zemsty w Wyjącym Fiordzie.', '', '', '', '', '', '', 0),
(13081, 'plPL', 'Wola naaru', 'Doceniam wszystko, co dla nas $gzrobiłeś:zrobiłaś;, $N. Mam dla ciebie ostatnie zadanie... ostatnią lśniącą nadzieję dla paladyna, który zasługuje na każde ocalenie, jakie możemy mu zapewnić.$B$BUdaj się teraz do Shattrath i porozmawiaj z naaru A\'dalem. Od dawna jest on latarnią światła i potężnym sojusznikiem pobożnych paladynów. Opowiedz mu historię Bridenbrada i poproś o wszelką pomoc, jaką może ofiarować.$B$BNie potrafię dość mocno podkreślić, jak ważne jest, byś się $gpospieszył:pospieszyła; – obawiam się, że naszemu krzyżowcowi zostało na tym świecie niewiele czasu.', 'Poproś o pomoc A\'dala w Shattrath w Puszczy Terokkar.', '', '', '', '', '', '', 0),
(13082, 'plPL', 'Dar A\'dala', 'Cieszę się, że do mnie przybywasz, $N. Wiem o krzyżowcu Bridenbradzie i o twoich wędrówkach w nadziei na jego ocalenie. Męstwo Bridenbrada rozpaliło w tobie niezwykłą bezinteresowność, a to samo w sobie jest cudem.$B$BŚwiatło zatroszczy się o swoich. Obdarzę Bridenbrada moim błogosławieństwem i nie będzie musiał znosić skażenia nieumarłością. Odeślę cię do Dalaranu, a ty wrócisz do niego. Wiedz, że pozostaję z tobą.', 'Wróć do krzyżowca Bridenbrada przy Cichym Czuwaniu w Lodowej Koronie.', '', '', '', '', '', '', 0),
(13430, 'plPL', 'Próba naaru: Magtheridon', 'Musisz przejść cztery próby, zanim naaru uznają cię za $ggodnego:godną;.$B$BZostała tylko jedna przeszkoda, $gśmiertelniku:śmiertelniczko;. Zbierz armię i udaj się do leża Magtheridona, głęboko w Cytadeli Piekielnego Ognia. Przebij się do serca komnaty i zniszcz tego plugawego deprawatora!', 'A\'dal w Shattrath chce, abyś $gzabił:zabiła; Magtheridona.', '', 'Wróć do A\'dala w Dolnym Mieście w Shattrath.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(9831, 'plPL', 'Dobrze się $gspisałeś:spisałaś;, $N. Nie byłem pewien, czy ci się uda.$B$BPojemniki są zaczarowane potężnym zaklęciem, które ukrywa je przed niegodnymi oczami. Cieszę się, że przed tobą się nie ukryły.', 0),
(9832, 'plPL', 'Masz fragmenty. To naprawdę imponujące, $N. Z pewnością jesteś $ggodny:godna; klucza do Karazhanu.$B Pozostaje jednak drobny problem.', 0),
(9836, 'plPL', 'Ten klucz... rozpoznaję go. To klucz Khadgara... oczywiście jeszcze mu go nie dałem.', 0),
(9837, 'plPL', 'Jego własny klucz? To niewiarygodne!$B$BNie wyczuwam żadnych zaburzeń w naszej linii czasu, więc chyba od początku tak miało się stać. Nie ma już odwrotu, $N. Klucz należy do ciebie i tylko do ciebie.', 0),
(9979, 'plPL', 'Tak? W czym mogę ci dziś pomóc?', 0),
(9990, 'plPL', 'Eterycy? Towary dostarczane do Tuurem? Egzotyczne części mechaniczne? I krwawy elf gotowy dostarczyć to ostatnie pudełko do Punktu Ognistego Skrzydła?$B$BCo to wszystko znaczy?! Jak to się ma do tego, co spotkało druidów w Gąszczu Cenariona?$B$BChyba powinniśmy zajrzeć do tego pudełka.', 0),
(10004, 'plPL', 'Spokojnie, śliczne oczka! Sal\'salabim pomoże.', 0),
(10009, 'plPL', 'Umowa to umowa, ale jak Sal\'salabim ci powiedzieć, ty się nie złościć, tak?', 0),
(10010, 'plPL', 'Oczywiście! Obrócimy ich własną broń przeciwko nim!', 0),
(10017, 'plPL', 'Dziękuję ci, $N. Aldorowie usłyszą o twoich czynach.', 0),
(10019, 'plPL', 'Dziękuję ci, $N. Naaru otoczyli te nieszczęsne dusze swoją opieką; byłoby wielką szkodą, gdyby dotarli do Shattrath tylko po to, by umrzeć od odniesionych wcześniej ran.$B$B<To zadanie można powtarzać do osiągnięcia reputacji na poziomie „Neutralny”.>', 0),
(10020, 'plPL', 'Dziękuję, $N. Opieka nad potrzebującymi to trudne zadanie, ale z czasem odkryłam, że sama w sobie jest nagrodą.', 0),
(10021, 'plPL', 'Dziękuję ci, $N. Jesteśmy strażnikami Światła i nie możemy porzucić naszych obowiązków, nawet w najtrudniejszych czasach.', 0),
(10024, 'plPL', 'Wszystkie są w doskonałym stanie, $N. Tak trzymaj, a wkrótce Widzący staną się twoimi przyjaciółmi.', 0),
(10025, 'plPL', 'Dziękuję ci, $N. Wizje Voren\'thala mogą pewnego dnia przesądzić o losie naszej rasy. Powinniśmy zrobić, co w naszej mocy, by były jak najdokładniejsze.$B$B<To zadanie można powtarzać do osiągnięcia reputacji na poziomie „Neutralny”.>', 0),
(10037, 'plPL', 'Dzięki! Nie pamiętam, kiedy ostatnio jadłem węgorza!$B$BJak mam je przyrządzić?', 0),
(10038, 'plPL', 'Najwyższy czas, żeby ktoś tu przyszedł. Wysłałem ten raport do Fortu Alleriańskiego ponad tydzień temu!$B$BBiurokracja!', 0),
(10040, 'plPL', 'Dobrze, w końcu $gwróciłeś:wróciłaś;! No więc, czego się $gdowiedziałeś:dowiedziałaś;? Kim oni są?', 0),
(10041, 'plPL', 'Dobrze, w końcu $gwróciłeś:wróciłaś;! No więc, czego się $gdowiedziałeś:dowiedziałaś;? Kim oni są?', 0),
(10042, 'plPL', 'To naprawdę złe wieści! Cóż, wygląda na to, że dobrze zrobiłem, wysyłając cię na pomoc Weeksowi. Ostatnie, czego nam trzeba, to Rada Cieni zadomowiona tuż u naszego progu!$B$B$N, w uznaniu twoich zasług w Wiosce Grangol\'var przyznaję ci prawo wyboru jednej z tych wspaniałych nagród.', 0),
(10091, 'plPL', 'To\'gun był tu wcześniej i złożył mi raport. Powinien był zostać z tobą i pomóc!$B$BOdesłałam go z powrotem, żeby wsparł Grik\'thę. Moim zdaniem tworzą uroczą parę.$B$BWięc to są te urządzenia duszy, których Rada Cieni używała do wzmacniania swojej mocy przywoływania? Jak dla mnie wyglądają groźnie.', 0),
(10095, 'plPL', 'Szmer prawie się wyrwał?! Trzymali to coś w zamknięciu od dwóch lat... Ciekawe, co zrobili nie tak, że po tak długim czasie stracili nad tym kontrolę?$B$B$N, powalając tę bestię, zapewne $gocaliłeś:ocaliłaś; nas wszystkich! Aż strach pomyśleć, co by się stało z nami wszystkimi tutaj i z resztą Rubieży, gdyby to coś zdołało się uwolnić!$B$BCieszę się, że $gpomogłeś:pomogłaś; nam wziąć sprawy w swoje ręce i rozprawić się z zagrożeniem ze strony Rady Cieni w Auchindoun. Jak możemy ci się kiedykolwiek odwdzięczyć?', 0),
(10102, 'plPL', 'K\'ure postąpił mądrze, przysyłając cię tutaj. Choć nie możemy ci pomóc ulżyć cierpieniu orczych przodków, jest ktoś, kto może.$B$BKtoś, kto wkrótce odrodzi się ze Światła...', 0),
(10112, 'plPL', 'Tak, w istocie, chyba wszystko zaczyna mi się rozjaśniać.$B$BI myślę, że twoja gorliwość w tej sprawie zasługuje na coś więcej niż tylko informacje, których szukasz.', 0),
(10167, 'plPL', 'To wspomnienie jest żywe, $N. Katastrofa całkowicie wyczerpała moją energię. Pozostała ze mnie tylko nikła drobina energii pustki, gdy prorok Velen i jego towarzysze draenei podnieśli moje szczątki i przenieśli je tutaj. Po długiej ceremonii moją umniejszoną postać złożono na spoczynek w tym sarkofagu. Odradzam się od niemal tysiąca lat. Cykl prawie się dopełnił...', 0),
(10169, 'plPL', 'Strzelcy Aldorów wydają się pochłonięci musztrą, co daje ci mnóstwo czasu, by wlać zawartość fiolki do gulaszu.', 0),
(10177, 'plPL', 'Najwyższy czas, żebyś się $gzjawił:zjawiła;.$B$BMehlisah mówiła, że przyśle pomoc, już kilka dni temu. A walczymy tu jeszcze dłużej!', 0),
(10180, 'plPL', 'Powinienem był się domyślić, że wyśle cię za mną. Próbował mnie odwieść od powrotu do Sal Sethekk, ale nie mógłbym z tym żyć, gdybym pozwolił Lakce tam zginąć.', 0),
(10210, 'plPL', '<Światło, które wypełniło twoje zmysły, gdy $gzbliżałeś:zbliżałaś; się do A\'dala, przybiera na sile, gdy się do niego zwracasz. W twojej głowie wciąż rozbrzmiewają melodyjne dzwoneczki.>$B$B<Tu jesteś $gbezpieczny:bezpieczna;.>', 0),
(10211, 'plPL', 'Mam nadzieję, że $gdowiedziałeś:dowiedziałaś; się to i owo o Shattrath, $N. Może minąć trochę czasu, zanim to wszystko do ciebie dotrze.', 0),
(10228, 'plPL', 'Księga umarłych? Nigdy o niej nie słyszałem... O co w ogóle chodzi? Kto cię przysłał?', 0),
(10231, 'plPL', 'Dobra, dobra! Nie bij nas. Mieliśmy tę księgę, ale ją sprzedaliśmy...', 0),
(10251, 'plPL', 'Wszystkie znaki na to wskazywały, ale przymykałem na nie oko.$B$BUścisk Legionu z każdym dniem się zacieśnia. Nawet w tych stronach...$B$BGdybym wiedział... Gdybym wiedział, że mój chłopak obcuje z demonami... Zaoferowały mu moc, a potem dały mu jej zasmakować. Tylko tyle było trzeba...$B$BKsięga przepadła. Zabrał ją Levixus... Jego plany znam tylko ja i jego mroczny pan.$B$B$GNieznajomy:Nieznajoma;, nie wiem, czy kiedykolwiek w życiu $gpostąpiłeś:postąpiłaś; słusznie, ale wiedz jedno: chłopaka trzeba powstrzymać.', 0),
(10280, 'plPL', '$GOdzyskałeś:Odzyskałaś; Pieśń Ducha! To kryształ ata\'mal, który prorok Velen zostawił swojemu ludowi na przechowanie, zanim wyruszył w nieszczęsną misję na Exodar.$B$BDziwne, że nie przewidział, iż kryształ wpadnie w ręce Płonącego Legionu, choćby na krótko.$B$BA może przewidział? Może przewidział to wszystko i zostawił go tam, żebyś $godzyskał:odzyskała; kryształ i $gdostarczył:dostarczyła; go mnie tutaj?$B$BWyczuwam, że tak właśnie było. Jesteś $gwielkim bohaterem:wielką bohaterką; swojego ludu, $N!', 0),
(10325, 'plPL', 'Stawienie czoła demonom Płonącego Legionu i czczącym je szalonym kultystom to niemały wyczyn, $N. $GWykazałeś:Wykazałaś; się wielkim oddaniem i odwagą. Tak trzymaj, a twoja sława wśród Aldorów będzie rosła.', 0),
(10326, 'plPL', 'Wciąż dowodzisz swojej wartości, $N. Walcz z wrogami Światła, gdziekolwiek ich spotkasz; twoje czyny zostaną sowicie nagrodzone.', 0),
(10327, 'plPL', 'Wciąż dowodzisz swojej wartości, $N. Walcz z wrogami Światła, gdziekolwiek ich spotkasz; twoje czyny zostaną sowicie nagrodzone.', 0),
(10409, 'plPL', 'Stało się, $N. Socrethar został zniszczony.$B$BJa i pozostali wyliżemy się z ran, $N. Jednak furia magii Socrethara okazała się zbyt wielka dla młodego Kaylaana. Nawet moja najżarliwsza modlitwa nie zdołała go wskrzesić.$B$BTo niewypowiedziany żal, że ktoś tak młody poległ w walce. Jednak w końcu jego wola okazała się dość silna, by wyzwolić się spod skażenia Legionu, i w tym możemy znaleźć pociechę.', 0),
(10410, 'plPL', 'Socrethar... Pamiętam to imię. Był niegdyś sławnym wojownikiem Światła, a jego jedyną wadą była pycha.', 0),
(10412, 'plPL', 'Dobra robota, $N. Może jednak okażesz się $gprzydatnym sojusznikiem:przydatną sojuszniczką;.', 0),
(10414, 'plPL', 'Tak... Szeregi Kaela topnieją, a nasze rosną.$B$B<To zadanie można powtarzać do osiągnięcia reputacji na poziomie „Szanowany”.>', 0),
(10415, 'plPL', 'Doskonale! Wszyscy, którzy nam się sprzeciwią, zostaną zmiażdżeni!$B$B<To zadanie można powtarzać do osiągnięcia reputacji na poziomie „Szanowany”.>', 0),
(10416, 'plPL', 'Zgodnie z obietnicą, $N. Cała surowa moc księgi skupiona w jednej runie.', 0),
(10419, 'plPL', 'Moc zawarta w tej księdze jest ogromna. A jednak ktoś o jasnym umyśle z łatwością skupi ją w jednej runie.', 0),
(10420, 'plPL', 'Patrz, jak plugawe materiały się rozpadają. Patrz, jak metal obraca się w pył.$B$BŚwiatło oczyszcza wszystko i zostaje tylko najczystszy osad.', 0),
(10421, 'plPL', 'Spaczone materiały zostały usunięte z tego świata. Pozostał tylko osad Światła.', 0),
(10507, 'plPL', 'Dysponujesz potężną mocą, $N. Widzący mają szczęście, że mogą nazywać cię $gswoim sojusznikiem:swoją sojuszniczką;.$B$BW miarę jak wieść o nowym przymierzu Kaela będzie się rozchodzić, coraz więcej osób przyzna nam rację. To, że możemy ogłosić tak zdecydowane zwycięstwo nad nowymi zwierzchnikami Kael\'thasa, stawia nas w wyjątkowo korzystnym położeniu.$B$BNie zapomnę twoich czynów.', 0),
(10509, 'plPL', 'Nie masz pojęcia, co to będzie znaczyć dla Widzących, $N. Wybacz, muszę złapać oddech i ocenić sytuację.', 0),
(10547, 'plPL', 'Masz zgniłe jajo arakkoa? Czemu od razu nie mówisz! Chyba dobijemy targu.$B$B<Tobias uśmiecha się, odsłaniając usta pełne zgnilizny i brudu.>', 0),
(10550, 'plPL', 'Teraz zastawmy pułapkę!', 0),
(10551, 'plPL', 'Czy jesteś $gpewien:pewna; swojego wyboru, $N? Aldorowie powitają cię jako sprzymierzeńca, ale Widzący niełatwo wybaczą ci tę decyzję.', 0),
(10552, 'plPL', 'Czy jesteś $gpewien:pewna; swojego wyboru, $N? Widzący powitają cię jako sprzymierzeńca, ale Aldorowie niełatwo wybaczą ci tę decyzję.', 0),
(10553, 'plPL', 'Khadgar przysyła nowego rekruta? Zatem weźmy się do pracy, $N.', 0),
(10554, 'plPL', 'Witaj, $N. Cieszę się, że $gpostanowiłeś:postanowiłaś; przyłączyć się do naszej misji. Niech Światło zawsze cię chroni.', 0),
(10560, 'plPL', '<A\'dal wydaje się niezwykle z ciebie zadowolony. Dzięki twojej pomocy Twierdza Burz zostanie pewnego dnia wyrwana ze szponów zła.>', 0),
(10653, 'plPL', 'Stawienie czoła demonom Płonącego Legionu i czczącym je szalonym kultystom to niemały wyczyn, $N. $GWykazałeś:Wykazałaś; się wielkim oddaniem i odwagą. Tak trzymaj, a twoja sława wśród Aldorów będzie rosła.', 0),
(10654, 'plPL', 'Wciąż dowodzisz swojej wartości, $N. Walcz z wrogami Światła, gdziekolwiek ich spotkasz; twoje czyny zostaną sowicie nagrodzone.', 0),
(10655, 'plPL', 'Wciąż dowodzisz swojej wartości, $N. Walcz z wrogami Światła, gdziekolwiek ich spotkasz; twoje czyny zostaną sowicie nagrodzone.', 0),
(10656, 'plPL', 'Armia Słonecznej Furii Kaela jest znakomicie wyszkolona. Bardzo imponująca robota, $N.', 0),
(10658, 'plPL', 'Doskonale! To nauczy Kael\'thasa, by nie lekceważył naszej potęgi.', 0),
(10659, 'plPL', 'Armia Kaela wkrótce upadnie.', 0),
(10704, 'plPL', 'Jestem pod wrażeniem, $N, choć po kimś, kto zwrócił nam kryształ ata\'mal, należało się tego spodziewać.$B$BOddaj mi oba odłamki, a dopilnuję, by połączono je w ostateczną postać. Wtedy zyskasz dostęp do Arkatrazu.', 0),
(10708, 'plPL', '<Gdy oddajesz medalion A\'dalowi, znika on w jego istocie w rozbłysku światła.>$B$B<Przez chwilę widzisz przebłysk pewnego momentu... być może z przyszłości. Widzisz Akamę i Maiev wychodzących z Klatki Strażniczki i przebijających się do Czarnej Świątyni. Pomaga im trzecia postać spowita w cienie. Przyglądając się bliżej, zauważasz, że to ty.>', 0),
(10781, 'plPL', 'Karmazynowa Pieczęć zostanie zbadana. Stanowi zagrożenie dla wszelkiego życia na Draenorze. Przewiduję dzień, w którym jej mroczny pan będzie musiał odpowiedzieć za swoje zbrodnie. Może to ty postawisz go przed sądem, $gbohaterze:bohaterko;.', 0),
(10822, 'plPL', 'Armia Kaela wkrótce upadnie.', 0),
(10823, 'plPL', 'Doskonale! To nauczy Kael\'thasa, by nie lekceważył naszej potęgi.', 0),
(10826, 'plPL', 'Twoja odwaga jest wielka, $gprzyjacielu:przyjaciółko;. Niech wszyscy wiedzą, że jesteś $gprawdziwym sojusznikiem:prawdziwą sojuszniczką; kapłaństwa!', 0),
(10827, 'plPL', 'Wciąż dowodzisz swojej wartości, $N. Walcz z wrogami Światła, gdziekolwiek ich spotkasz; twoje czyny zostaną sowicie nagrodzone.', 0),
(10828, 'plPL', 'Wciąż dowodzisz swojej wartości, $N. Walcz z wrogami Światła, gdziekolwiek ich spotkasz; twoje czyny zostaną sowicie nagrodzone.', 0),
(10831, 'plPL', '<Nasmara bada tkaninę, obracając ją w dłoniach.>$B$BTo wyjątkowo piękna próbka, $N. Będziesz $gświetnym krawcem:świetną krawcową; księżycowej tkaniny.', 0),
(10832, 'plPL', '<Gidge bada esencję upiora Otchłani.>$B$BNawet tak mała próbka esencji tego stwora promieniuje mocą. Może źle zrozumiałam, co się dzieje. Nie rozwścieczamy upiorów, czerpiąc energię z otoczenia. To upiory i otoczenie są jednym i tym samym!$B$BNie wahaj się dać mi znać, jeśli dokonasz kolejnych odkryć, teraz, gdy $gzostałeś krawcem:zostałaś krawcową; ognia zaklęć.', 0),
(10833, 'plPL', 'Widzę, że wizyta przy ołtarzu się powiodła. Zaszła w tobie subtelna zmiana, którą dostrzegą nieliczni, ale bez wątpienia tam jest.', 0),
(10847, 'plPL', 'Twoja odwaga zasługuje na pochwałę. Strażnicy Skettis nie rozstają się dobrowolnie ze swoją własnością.$B$BLecz dawne bohaterstwo niewiele teraz znaczy. Zobaczymy, czy taka odwaga nie opuści cię w przyszłości, bo wzrok Terokka zwrócony jest na południe.$B$BTe Oczy widzą wszystko.', 0),
(10849, 'plPL', 'Opowieść Rilaka jest ponura, $gwędrowcze:wędrowczyni;. Jak widać po stanie karawany, w lesie Terokka panuje dziś wiele smutku i ciemności.', 0),
(10862, 'plPL', 'Twój lud jest rozgniewany, ale niewiele mogę zrobić. Niektórych z nas dotknęła moc naaru i zmieniliśmy się na zawsze. Ci, którzy pozostali w dziczy, są tacy, jacy byli zawsze.', 0),
(10863, 'plPL', 'Mądrze $gzrobiłeś:zrobiłaś;, szukając mnie. Mogę ci wiele pokazać.', 0),
(10879, 'plPL', 'Podziwiam twoją sprawność w walce, $N. $GOkazałeś:Okazałaś; się $gprawdziwym obrońcą:prawdziwą obrończynią; Światła. Niech błogosławieństwo A\'dala rozjaśnia twoje najciemniejsze godziny.$B$BAle spójrz daleko, ku horyzontowi. Nad Skettis wiszą mroczne niebiosa. Terokk bez wątpienia planuje kolejny ruch. Na razie Shattrath jest bezpieczne. Lecz tylko jutro wie, jaka groza na nas spadnie.', 0),
(10882, 'plPL', 'Po raz kolejny $gdowiodłeś:dowiodłaś; swojego hartu. Gdyby zwiastun Skyriss się wyrwał, w konflikcie, który by wybuchł, zginęłyby niezliczone tysiące, tak jak stało się w przypadku innego sługi Przedwiecznych, Skerama, w twoim świecie, Azeroth.$B$B$N, to, co mam ci do zaoferowania w zamian, może się wydawać drobnostką, ale wiedz, że towarzyszy temu dozgonna wdzięczność Sha\'tar.', 0),
(10883, 'plPL', 'Twierdza Burz jest dziełem naaru, $gśmiertelniku:śmiertelniczko;. Dostęp do tego statku zawsze leżał w naszej mocy. Powrót do Twierdzy Burz uznawaliśmy jednak za zbędny. Dla śmiertelnej rasy byłaby to może kwestia dumy, ale naaru niewielką wagę przykładają do takich spraw.$B$BIdziemy teraz, bo musimy. Nie można pozwolić, by Kael\'thas wypowiedział słowa potępienia.$B$BChoć droga stoi otworem, tylko głupiec wszedłby tam, nie dowiódłszy swojej wartości. Nie lekceważ celu prób, $gśmiertelniku:śmiertelniczko;.', 0),
(10884, 'plPL', 'Dobra robota, $N. $GPrzeszedłeś:Przeszłaś; próbę łaski.', 0),
(10885, 'plPL', 'Dobra robota, $N. $GPrzeszedłeś:Przeszłaś; próbę siły.', 0),
(10886, 'plPL', 'Dobra robota, $N. $GPrzeszedłeś:Przeszłaś; próbę nieustępliwości.', 0),
(10888, 'plPL', '$GDowiodłeś:Dowiodłaś;, że jesteś istotą wielkiej mocy. Naaru dają ci dostęp do Twierdzy Burz.', 0),
(10889, 'plPL', 'Strażnicy Skettis niecierpliwią się na swoich grzędach. Shattrath jest w niebezpieczeństwie. Z pewnością odczujemy impet zemsty Terokka.$B$BSzybko zbierz oddział obrońców! Porozmawiaj z defensorem Grashną i daj mu znać, że jesteś $ggotów:gotowa; chwycić za broń przeciwko napastnikom!', 0),
(10898, 'plPL', 'Niestety, biedne Podniebne Skrzydło padło ofiarą straszliwej klątwy Luangi Więziciela!$B$BPodniebne Skrzydło poleciało do Zasłony Shalas, by spróbować nakłonić innych do obrania drogi Światła. Nie przyjęli tego dobrze, zwłaszcza że mieszkają tuż u progu Skettis.$B$BLuanga był jednym z najgroźniejszych agentów Terokka. Dobrze się $gspisałeś:spisałaś;, uwalniając Podniebne Skrzydło! Dziękuję ci.', 0),
(10902, 'plPL', 'Sądząc po tych próbkach, świetnie radzisz sobie z eliksirami. Będzie z ciebie $gdobry uczeń:dobra uczennica;.$B$BTe esencje dostarczą mi dość materiału, by opracować recepturę. Dzięki temu odkryciu poznają mnie wszyscy alchemicy!$B$BA teraz, jeśli chcesz się uczyć, jestem gotów cię uczyć.', 0),
(10906, 'plPL', 'Chcesz się ode mnie uczyć? Hmmm, tak. Może będzie z ciebie $godpowiedni uczeń:odpowiednia uczennica;.', 0),
(10908, 'plPL', 'A więc się spotykamy, $N. Wybacz brak formalności, ale czas nagli.', 0),
(10917, 'plPL', '<Vekax skrzeczy z radości, gdy pokazujesz mu dowód zguby jego wrogów.>$B$BTak, to pokaże Skettis, że my, Wyrzutkowie, nie przyjmiemy ich kary z pokorą. Oto nagroda, którą ci obiecałem. Mogę załatwić więcej, jeśli dostarczysz mi kolejne pióra.', 0),
(10918, 'plPL', '<Vekax skrzeczy z radości, gdy pokazujesz mu dowód zguby jego wrogów.>$B$BTak, to pokaże Skettis, że my, Wyrzutkowie, nie przyjmiemy ich kary z pokorą. Oto nagroda, którą ci obiecałem. Mogę załatwić więcej, jeśli dostarczysz mi kolejne pióra.$B$B<To zadanie można powtarzać do osiągnięcia reputacji na poziomie „Szanowany”.>', 0),
(10948, 'plPL', '<Światło A\'dala otacza cię, gdy wita cię z powrotem. Masz wrażenie, że wie, o co zamierzasz go poprosić.>', 0),
(10949, 'plPL', '<Xi\'ri zdaje się dostrzegać twoją obecność. Wydaje się skupiony na toczącej się wokół bitwie.>', 0),
(10960, 'plPL', 'Tak niewielu ma dar pozwalający czerpać taką moc od M\'uru. Zobaczyć to u dziecka – to naprawdę zdumiewające!$b$bMądrze $gzrobiłeś:zrobiłaś;, przyprowadzając ją do mnie.$b$bMówisz, że jest sierotą z Shattrath? Dopilnuję, by złożono wniosek do tamtejszej opiekunki sierocińca, aby przekazano ją pod naszą opiekę na właściwe szkolenie. Jej miejsce jest z nami, tutaj.$b$bDopilnuj, by do tego czasu była bezpieczna.', 0),
(10966, 'plPL', 'Dusza się raduje na wieść, że są tacy bohaterowie jak ty, gotowi tak bezinteresownie poświęcać swój czas.$B$BJuż teraz widzę, że czas spędzony z tobą wywarł na Dornai ogromne wrażenie. Dobrze, gdy dzieci mają okazję wyjść i zobaczyć świat.$B$BProszę, powiedziała mi, że chce, byś $gzaopiekował:zaopiekowała; się jednym z jej ulubionych zwierzaków, tak jak $gopiekowałeś:opiekowałaś; się nią. Na pamiątkę po niej.$B$BZaglądaj do nas czasem.', 0),
(10967, 'plPL', 'Dusza się raduje na wieść, że są tacy bohaterowie jak ty, gotowi tak bezinteresownie poświęcać swój czas.$B$BJuż teraz widzę, że czas spędzony z tobą wywarł na Salandrii ogromne wrażenie. Dobrze, gdy dzieci mają okazję wyjść i zobaczyć świat.$B$BProszę, powiedziała mi, że chce, byś $gzaopiekował:zaopiekowała; się jednym z jej ulubionych zwierzaków, tak jak $gopiekowałeś:opiekowałaś; się nią. Na pamiątkę po niej.$B$BZaglądaj do nas czasem.', 0),
(10983, 'plPL', 'Grok powiedział, że jestem mądry? Nie wiem, czy to prawda.$B$BMoże dlatego, że jako jedyny w klanie naprawdę próbuję ocalić nas przed zagładą z rąk Klanu Ostrza oraz Gruula i jego synów, którzy go wspierają.$B$BMam nadzieję, że $gprzybyłeś:przybyłaś;, by wybawić nas od pewnej zguby, $N.', 0),
(10984, 'plPL', 'Ty pomóc Grok? Grok potrzebować pomoc! Klan Krwawych Młotów potrzebować pomoc!', 0),
(11007, 'plPL', '<Myśli A\'dala przeplatają się z twoimi.>$B$BSfera... Dziwne. Czy wiesz, że on przeżył? Tak. To jest tutaj – w samej sferze. Z pewnością okaleczony. Teraz wzywa wyższą moc. Nie, nie Illidana.$B$BWyższą.$B$BKil\'jaeden Zwodziciel nadchodzi...$B$BNie tutaj...$B$B<A\'dal kieruje twój umysł gdzie indziej.>$B$BAzeroth. Nieznane.$B$BOdpocznij. Twoi bracia i siostry odbiją teraz Twierdzę Burz.$B$B<A\'dal nuci bojową pieśń.>$B$B', 0),
(11024, 'plPL', 'To niemożliwe... to należało kiedyś do szponokapłana. Jak to w ogóle $gzdobyłeś:zdobyłaś;?', 0),
(11028, 'plPL', 'Arakkoa chcą sprowadzić Terokka zza zasłony czasu, a Rilak... chce znaleźć sposób, by przyspieszyć ten proces? Czy on oszalał?$B$B<Adaris opada z powrotem, gdy opuszczają go siły.>$B$B$GWypełniłeś:Wypełniłaś; swój obowiązek, $N. Czas, byś $gpozwolił:pozwoliła; moim ludziom przejąć sprawę. To teraz kwestia czysto wojskowa.', 0),
(11038, 'plPL', 'Więc jesteś tu, by pomóc nam ustalić, co dokładnie planuje Kael\'thas? Twoja pomoc jest bardzo mile widziana. W Burzy Otchłani roi się od agentów krwawych elfów, których działania grożą rozdarciem tej krainy.', 0),
(11039, 'plPL', '<Na twarzy mistrza szpiegów przez chwilę maluje się rozczarowanie.>$B$BLiczyłem przynajmniej na oddział, ale skoro Voren\'thal uznał za stosowne przysłać tylko ciebie, dostosuję swoje plany.', 0),
(11045, 'plPL', 'Fantei mówi prawdę, a ja chętnie przyjmę twoją pomoc.', 0),
(11046, 'plPL', 'Fantei ma dobrą pamięć. Minęły miesiące, odkąd ostatnio byłam w Shattrath po odczynniki. Ale ma rację. Przyda mi się pomoc.', 0),
(11096, 'plPL', 'Dobra robota, asie. Mam przeczucie, że świetnie się u nas odnajdziesz.', 0),
(11098, 'plPL', 'Dzięki za zapasy, zrobimy z nich dobry użytek! Nowy rekrut? Cóż, zobaczmy, z jakiej gliny cię ulepiono.', 0),
(11108, 'plPL', 'Wiesz, byłem pierwszy. Porzucone dziecię potwora...$B$B<Barthamus kręci głową.>$B$BZawdzięczamy ci wszystko, $N. W pojedynkę $gzmiażdżyłeś:zmiażdżyłaś; imperium Smoczych Paszcz i $gzebrałeś:zebrałaś; tyle informacji, że moi bracia będą mieli zajęcie na dziesięć żywotów.$B$BTo niewiele, ale możemy ci coś ofiarować... Każdy z moich pobratymców zgłosił gotowość, by towarzyszyć ci w twojej misji na Rubieży. Wystarczy poprosić, a zwiąże się z tobą.', 0),
(11109, 'plPL', 'To zaszczyt cię poznać, $N. Wszyscy uważnie śledziliśmy twoje przygody i jesteśmy wdzięczni za wszystko, co $gzrobiłeś:zrobiłaś; dla stada Otchłanioskrzydłych.$B$BJeśli wybierzesz mnie na swojego towarzysza, zaniosę cię na krańce tego świata i z powrotem. O cokolwiek poprosisz, dołożę wszelkich starań, by to spełnić.$B$BPamiętaj jednak, że na wyprawy po Rubieży możesz wybrać tylko jedno z nas. Gdy dokonasz wyboru, nie będzie można go zmienić.', 0),
(11110, 'plPL', 'To zaszczyt cię poznać, $N. Wszyscy uważnie śledziliśmy twoje przygody i jesteśmy wdzięczni za wszystko, co $gzrobiłeś:zrobiłaś; dla stada Otchłanioskrzydłych.$B$BJeśli wybierzesz mnie na swojego towarzysza, zaniosę cię na krańce tego świata i z powrotem. O cokolwiek poprosisz, dołożę wszelkich starań, by to spełnić.$B$BPamiętaj jednak, że na wyprawy po Rubieży możesz wybrać tylko jedno z nas. Gdy dokonasz wyboru, nie będzie można go zmienić.', 0),
(11111, 'plPL', 'To zaszczyt cię poznać, $N. Wszyscy uważnie śledziliśmy twoje przygody i jesteśmy wdzięczni za wszystko, co $gzrobiłeś:zrobiłaś; dla stada Otchłanioskrzydłych.$B$BJeśli wybierzesz mnie na swojego towarzysza, zaniosę cię na krańce tego świata i z powrotem. O cokolwiek poprosisz, dołożę wszelkich starań, by to spełnić.$B$BPamiętaj jednak, że na wyprawy po Rubieży możesz wybrać tylko jedno z nas. Gdy dokonasz wyboru, nie będzie można go zmienić.', 0),
(11112, 'plPL', 'To zaszczyt cię poznać, $N. Wszyscy uważnie śledziliśmy twoje przygody i jesteśmy wdzięczni za wszystko, co $gzrobiłeś:zrobiłaś; dla stada Otchłanioskrzydłych.$B$BJeśli wybierzesz mnie na swojego towarzysza, zaniosę cię na krańce tego świata i z powrotem. O cokolwiek poprosisz, dołożę wszelkich starań, by to spełnić.$B$BPamiętaj jednak, że na wyprawy po Rubieży możesz wybrać tylko jedno z nas. Gdy dokonasz wyboru, nie będzie można go zmienić.', 0),
(11113, 'plPL', 'To zaszczyt cię poznać, $N. Wszyscy uważnie śledziliśmy twoje przygody i jesteśmy wdzięczni za wszystko, co $gzrobiłeś:zrobiłaś; dla stada Otchłanioskrzydłych.$B$BJeśli wybierzesz mnie na swojego towarzysza, zaniosę cię na krańce tego świata i z powrotem. O cokolwiek poprosisz, dołożę wszelkich starań, by to spełnić.$B$BPamiętaj jednak, że na wyprawy po Rubieży możesz wybrać tylko jedno z nas. Gdy dokonasz wyboru, nie będzie można go zmienić.', 0),
(11114, 'plPL', 'To zaszczyt cię poznać, $N. Wszyscy uważnie śledziliśmy twoje przygody i jesteśmy wdzięczni za wszystko, co $gzrobiłeś:zrobiłaś; dla stada Otchłanioskrzydłych.$B$BJeśli wybierzesz mnie na swojego towarzysza, zaniosę cię na krańce tego świata i z powrotem. O cokolwiek poprosisz, dołożę wszelkich starań, by to spełnić.$B$BPamiętaj jednak, że na wyprawy po Rubieży możesz wybrać tylko jedno z nas. Gdy dokonasz wyboru, nie będzie można go zmienić.', 0),
(11195, 'plPL', 'Hej, a skąd ty to masz?$B$BNie, nie, nie mów – to pochodzi od samego Mistrza Uroków! Teraz wszystko jasne. Mocne mojo! Kto nosi ten relikt, choćby nie wiem ile razy się zhańbił, zawsze będzie szanowany przez swoich. Niesamowite!$B$B<Gdy Griftah unosi lalkę w powietrze, z jej szyi spada mały, zardzewiały amulet. Troll już chce go wyrzucić, ale odwraca się do ciebie z błyskiem w oku.>$B$BNie mam teraz monet, mon, ale weź sobie to tutaj...', 0),
(11354, 'plPL', 'Kolejny klient, który wkrótce będzie zadowolony. Wygląda na to, że jest w świetnym stanie. Należy ci się nagroda.$B$BWróć jutro, a będę miał dla ciebie kolejne zlecenie.', 0),
(11362, 'plPL', 'Może każę przywiązać do niego nowe pióra, zanim wyślę go kupcowi. Przy tylu arakkoa w okolicy z pewnością nie będzie to trudne. Drobiazg, który w żadnym razie nie umniejsza twojej nagrody.$B$BWróć jutro, a będę miał dla ciebie kolejne zlecenie.', 0),
(11363, 'plPL', 'Doprawdy śmiała zdobycz – bardowie powinni ją opiewać. Proszę, w pełni na to $gzasłużyłeś:zasłużyłaś;.$B$BWróć jutro, a będę miał dla ciebie kolejne zlecenie.', 0),
(11364, 'plPL', 'Dobrze, $gzasłużyłeś:zasłużyłaś; na nagrodę.$B$BWróć jutro, a wiatry znów wyszepczą coś Mah\'duunowi.', 0),
(11368, 'plPL', 'Teraz, gdy o tym myślę, szkoda, że nie poprosiłem cię, byś $gprzyniósł:przyniosła; także dwa pozostałe serca. Może następnym razem. Tak czy inaczej, $gzasłużyłeś:zasłużyłaś; na swoją prowizję.$B$BWróć jutro, a będę miał dla ciebie kolejne zlecenie.', 0),
(11369, 'plPL', 'Czyż to nie zdumiewające, gdy czuje się życie pulsujące w jaju? Muszę się pospieszyć z dostarczeniem go nabywcy. Nie chcielibyśmy przecież, żeby wykluło się tutaj, prawda?$B$BTwoja zapłata jest gotowa.$B$BWróć jutro, a będę miał dla ciebie kolejne zlecenie.', 0),
(11370, 'plPL', 'Obawiam się, że mój klient nie znajdzie czasu, by przeczytać tę księgę w całości. Nie nasze to jednak zmartwienie. Oto twoja nagroda.$B$BWróć jutro, a będę miał dla ciebie kolejne zlecenie.', 0),
(11371, 'plPL', 'Mam nadzieję, że walka była warta twojego czasu? Ta nagroda z pewnością jest.$B$BWróć jutro, a wiatry znów wyszepczą coś Mah\'duunowi.', 0),
(11372, 'plPL', 'Jestem pewien, że te pióra będą piękną ozdobą pióropusza wodza. $GZasłużyłeś:Zasłużyłaś; na swoje wynagrodzenie, $N.$B$BWróć jutro, a będę miał dla ciebie kolejne zlecenie.', 0),
(11373, 'plPL', '<Wyczuwasz u handlarza wiatru głęboką satysfakcję.>$B$BDobrze, cieszę się, że słyszę o jego śmierci. Może zdołam sam odkryć sekrety jego amuletu. A jeśli nie, sprzedam go za niezłą sumkę.$B$BMam nadzieję, że ta nagroda wystarczy.$B$BWróć jutro, a będę miał dla ciebie kolejne zlecenie.', 0),
(11374, 'plPL', 'Ależ z ciebie $gbohater:bohaterka;, $N. Jestem pewien, że mój klient znajdzie sposób, by uwolnić z klejnotu ducha ukochanej osoby. Za dobrze wykonaną robotę czeka cię zapłata.$B$BWróć jutro, a będę miał dla ciebie kolejne zlecenie.', 0),
(11375, 'plPL', 'Martwiłem się, że możesz nie wrócić. Mam nadzieję, że walka ze Szmerem nie pozbawiła cię słuchu?$B$BOto twoja nagroda. Profesor bez wątpienia będzie zadowolony, choć martwi mnie, co ostatecznie zamierza z tym zrobić.$B$BWróć jutro, a będę miał dla ciebie kolejne zlecenie.', 0),
(11376, 'plPL', 'Jestem zadowolony. Ten, który przemawia przez Otchłań, także będzie. Mah\'duun ma dla ciebie gotową nagrodę.$B$BWróć jutro, a wiatry znów wyszepczą coś Mah\'duunowi.', 0),
(11377, 'plPL', 'Och, czuję coś smakowitego! Mam nadzieję, że porządnie $gspuściłeś:spuściłaś; temu ptaszysku lanie.$B$BProszę, poczęstuj się moimi zapasami. Jestem pewien, że ktoś z twoim talentem zrobi z nich dobry użytek.', 0),
(11378, 'plPL', 'Widzę, że $gwróciłeś:wróciłaś; do teraźniejszości w jednym kawałku.$B$B<Handlarz wiatru rozgląda się dookoła.>$B$BWygląda na to, że nic się nie zmieniło. Ale w sumie skąd miałbym to wiedzieć?$B$BŁadnie odcięta; mój klient będzie zadowolony. Oto twoja nagroda.$B$BWróć jutro, a będę miał dla ciebie kolejne zlecenie.', 0),
(11379, 'plPL', 'No proszę, spójrz tylko...$B$B<Rokk bierze łyk mikstury, a jego twarz wykrzywia się w dziwaczną maskę bólu i zachwytu.>$B$BNa słodkiego A\'dala, ale to dobre! Ktoś z takim kulinarnym potencjałem nie powinien zostać bez porządnych składników. Weź trochę moich zapasów i niech będę z ciebie dumny.', 0),
(11380, 'plPL', 'To najsoczystsze jagody many, jakie w życiu widziałem. Chyba mądrzeję od samego patrzenia na nie.$B$BSkoro nie potrzebuję już większości moich zapasów mięsa i ryb, może weźmiesz trochę? Na pewno przyrządzisz z nich coś pysznego.', 0),
(11381, 'plPL', 'Jeśli kiedykolwiek czułem zapach porządnej porcji duchowej zupy, to właśnie teraz. Jeszcze szczypta pieprzu i gotowe.$B$BJak obiecałem, oto twoja działka. A że tak dobrze się $gspisałeś:spisałaś;, dorzucę trochę moich zapasów.', 0),
(11382, 'plPL', 'Dziwne, że piasek w tym czymś wciąż sypie się do góry. Chyba jak najszybciej każę ją dostarczyć nowemu właścicielowi.$B$BDziękuję ci za dobrze wykonaną robotę, $N. Z pewnością $gzasłużyłeś:zasłużyłaś; na swoją prowizję.$B$BWróć jutro, a będę miał dla ciebie kolejne zlecenie.', 0),
(11383, 'plPL', '$GZnalazłeś:Znalazłaś; drogę w przeszłość, a potem z powrotem. Musisz być $gwielkim:wielką; $gbohaterem:bohaterką;. Nagroda jest twoja.$B$BWróć jutro, a wiatry znów wyszepczą coś Mah\'duunowi.', 0),
(11384, 'plPL', 'Och, naprawdę ją $gzdobyłeś:zdobyłaś;! Jaka malutka. A jednak gdy druidzi z nią skończą – co podobno potrwa bardzo długo – Spaczodrzazg odrośnie na nowo.$B$BA oto twoja obiecana nagroda.$B$BWróć jutro, a będę miał dla ciebie kolejne zlecenie.', 0),
(11385, 'plPL', 'A teraz są martwi i już niczego nie ukierunkują. Ten, który szepcze przez Otchłań, jest zadowolony, a ty $gzdobyłeś:zdobyłaś; nagrodę.$B$BWróć jutro, a wiatry znów wyszepczą coś Mah\'duunowi.', 0),
(11386, 'plPL', 'Kusi mnie, żeby zatrzymać go dla siebie i oddać klientowi pieniądze. Z pewnością poszerzyłby zasięg moich interesów.$B$B<Handlarz wiatru wzdycha.>$B$BMam jednak reputację, o którą muszę dbać.$B$BSkoro o niej mowa – dziękuję, że pomagasz mi ją utrzymać. Oto twoja prowizja.$B$BWróć jutro, a będę miał dla ciebie kolejne zlecenie.', 0),
(11387, 'plPL', 'Mah\'duun lubi walczyć z konstruktami; robią mniej bałaganu niż istoty z krwi i kości.$B$BNagroda jest twoja.$B$BWróć jutro, a wiatry znów wyszepczą coś Mah\'duunowi.', 0),
(11388, 'plPL', 'Nie śmiem dotknąć zwoju, bym i ja nie ściągnął na siebie uwagi Przedwiecznych. Jego dostarczeniem zajmie się któryś z moich pomocników.$B$BW pełni $gzasłużyłeś:zasłużyłaś; na nagrodę, $N, i życzę ci wszelkiego szczęścia we wszystkich znanych światach.$B$BWróć jutro, a będę miał dla ciebie kolejne zlecenie.', 0),
(11389, 'plPL', 'Skoro wartownicy są zniszczeni, może naaru poproszą Konsorcjum o nowych? Mah\'duun nie wie i nic go to nie obchodzi.$B$B$GZasłużyłeś:Zasłużyłaś; na nagrodę.$B$BWróć jutro, a wiatry znów wyszepczą coś Mah\'duunowi.', 0),
(11481, 'plPL', 'Kolejny żołnierz z Shattrath? Miły widok!$b$bSzkoda, że nie ma was więcej, ale poradzimy sobie z tym, co mamy. Cokolwiek się tu dzieje, nie będzie czekać, aż się przygotujemy.$b$bRozejrzyj się, $N. Jest mnóstwo do zrobienia. Włącz się i zrób, co do ciebie należy.$b$bA, właśnie, i nie drażnij Wyjących – eee, Widzących. Wygląda na to, że siedzimy w tym razem...', 0),
(11482, 'plPL', 'Witaj na Płaskowyżu Słonecznej Studni, Wyjący – Co mówisz? A, Widzący, no jasne. Czy nie to właśnie powiedziałem?$b$bNo dobrze, wyjaśnijmy sobie parę rzeczy. Za tymi murami dzieje się coś poważnego i w interesie obu naszych ludów jest się tym zająć. A skoro żadne z nas nie ma dość sił, by działać w pojedynkę, będziemy pracować RAZEM. Jasne?$b$bTo co, zaczynamy?', 0),
(11497, 'plPL', 'Więc to mój chłopak Nutral cię przysłał, co? Porządny gość... Muszę pamiętać, coby mu posłać kufelek za całą tę robotę, co mi podsyła.$B$BJak chcesz się nauczyć latać jak należy, to dobrze $gtrafiłeś:trafiłaś;. Nikt nie lata lepiej niż my, Dzikie Młoty, i ci, których szkolimy. Za opłatą, i to niemałą, nauczę cię szybować po niebie!$B$BA jak skończysz, nie zapomnij pogadać z Brunnem o kupnie jednej z tych gryfich piękności!', 0),
(11498, 'plPL', 'Na krew i grom, Nutral przysłał mi kolejnego piechura! Porządny gość... jak na draeneia.$B$B<Olrokk spluwa na ziemię tuż przy twoich stopach.>$B$BDobrze trafiasz, jeśli chcesz się nauczyć dosiadać własnego wierzchowca w przestworzach. W zamian za wielki wór złota nauczę cię, co trzeba, żebyś nie $gspadł:spadła; haniebnie na śmierć.$B$BA jak skończysz, nie zapomnij pogadać z Damą Dzikogrzywą o kupnie jednej z wiwern z naszej stajni!', 0),
(11499, 'plPL', 'A więc książę krwawych elfów tym razem naprawdę nie żyje? Szkoda, zawsze uważałem, że miał klasę. Pomyśleć, że ktoś tak wyniosły mógł upaść za tak marną sumkę.$b$bAle jak to mówią, interes to interes. $GZasłużyłeś:Zasłużyłaś; na nagrodę, $gposzukiwaczu:poszukiwaczko; przygód.$b$bWróć jutro, a będę miał dla ciebie kolejne zlecenie.', 0),
(11500, 'plPL', 'Kto wie, dlaczego te demoniczne siostry musiały zginąć? Obchodzi cię to?$b$bMah\'duun sądzi jednak, że obchodzi cię to na tyle, by odebrać nagrodę.$b$bWróć jutro, a wiatry znów wyszepczą coś Mah\'duunowi.', 0),
(11517, 'plPL', 'Przysłał cię Portanuus? Dobrze, nie mamy czasu do stracenia!', 0),
(11534, 'plPL', 'Przysłał cię Portanuus? Dobrze, nie mamy czasu do stracenia!', 0),
(11550, 'plPL', 'Kil\'jaeden spada na ten świat z pełną potęgą Płonącego Legionu. Jeśli przyzwanie się dopełni, nasz świat znów pogrąży się w chaosie. Twoja pomoc na Wyspie Quel\'Danas ma kluczowe znaczenie dla naszego zwycięstwa nad Płonącym Legionem.$b$bNasi magowie pracują nad zniesieniem barier blokujących dostęp do Słonecznej Studni. Zrób, co do ciebie należy, w walce z siłami Legionu, pomagając Ofensywie Straceńczego Słońca.', 0),
(11875, 'plPL', 'Dziękuję za pomoc, $N. Żaden wkład w wysiłek wojenny nie jest zbyt mały. Nasi ludzie będą potrzebować w tej bitwie każdej możliwej przewagi.', 0),
(11877, 'plPL', '<Lord Torvos przyjmuje plany i je przegląda.>$b$b$GOddałeś:Oddałaś; Ofensywie wielką przysługę, $N, ale nie powinniśmy spoczywać na laurach. Nie zdziwiłbym się, gdyby nasi wrogowie planowali w przyszłości kolejne podstępy.', 0),
(11880, 'plPL', 'Dzięki za pomoc. Nie masz pojęcia, jak to jest użerać się z tamtym „doktorem” Gofrosmażem. W przerwach między „kontrolami” moich postępów zajmuje się wciskaniem ludziom tego czy innego gadżetu opartego na swoich wojskowych wynalazkach.', 0),
(13081, 'plPL', '<Gdy zbliżasz się do naaru, twoją głowę wypełnia łagodne dzwonienie.>$B$BWiem, dlaczego przybywasz.', 0),
(13082, 'plPL', '<Gdy zbliżasz się do krzyżowca Bridenbrada, nie sposób nie zauważyć, że jego skóra nabrała bladego odcienia, a oddech jest płytki. Widać wyraźnie, że zostało mu niewiele czasu.>$B$B$GWróciłeś:Wróciłaś; do mnie, $N. Muszę przyznać... dobrze cię znów widzieć... twoja twarz odnawia moją nadzieję, że ta kraina wkrótce uwolni się z uścisku Arthasa. Jestem dumny, że cię poznałem...$B$B<Słowa Bridenbrada cichną, a na jego twarzy pojawia się blady uśmiech. Gdy życie zdaje się z niego uchodzić, twoje uszy wypełnia łagodne dzwonienie.>', 0),
(13430, 'plPL', '$GUdowodniłeś:Udowodniłaś;, że jesteś istotą wielkiej mocy. Naaru to aprobują...', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(9426, 'plPL', '$GWykonałeś:Wykonałaś; zadanie, $N?', 0),
(9831, 'plPL', '$GZdobyłeś:Zdobyłaś; fragment, $N? Lepiej nie trać w tej sprawie czasu.', 0),
(9832, 'plPL', 'Jak idą poszukiwania fragmentów klucza, $N?', 0),
(9836, 'plPL', 'Kim jesteś i czego chcesz?', 0),
(10004, 'plPL', '<Sal\'salabim rozciera głowę.>$B$B[Demoniczny] Ik il romath sardon.', 0),
(10009, 'plPL', 'Ty nie wracać bez złota Sal\'salabim!', 0),
(10017, 'plPL', '$GZdobyłeś:Zdobyłaś; worki jadowe, $N? Ci uchodźcy nie mogą dłużej czekać.', 0),
(10019, 'plPL', 'Wielu uchodźców wciąż potrzebuje leczenia zatrutych ran. $GPrzyniosłeś:Przyniosłaś; mi więcej worków jadowych, $N?', 0),
(10020, 'plPL', '$GZdobyłeś:Zdobyłaś; krew, $N? Bez niej Zahlia może już nigdy nie zobaczyć swojego syna.', 0),
(10021, 'plPL', '$GWykonałeś:Wykonałaś; zadanie, $N?', 0),
(10024, 'plPL', '$GZdobyłeś:Zdobyłaś; oczy bazyliszków do eliksiru Voren\'thala?', 0),
(10025, 'plPL', 'Nawet niewielka dawka eliksiru Voren\'thala wymaga wielu oczu bazyliszka. Przynosząc mi ich więcej, z pewnością zaskarbisz sobie przychylność Widzących.', 0),
(10037, 'plPL', '<Seth ciągnie cię za płaszcz.>$B$B$GZnalazłeś:Znalazłaś; węgorze? No, $gznalazłeś:znalazłaś;?', 0),
(10040, 'plPL', '$GRozmawiałeś:Rozmawiałaś; już ze wszystkimi? Co mieli do powiedzenia?', 0),
(10041, 'plPL', '$GRozmawiałeś:Rozmawiałaś; już ze wszystkimi? Co mieli do powiedzenia?', 0),
(10042, 'plPL', 'No i czego się $gdowiedziałeś:dowiedziałaś;, $gchłopcze:dziewczyno;?', 0),
(10091, 'plPL', 'Tak? Co mogę dla ciebie zrobić?', 0),
(10095, 'plPL', '$N, przynosisz wieści z Labiryntu Cieni? Czy zagrożenie zostało wreszcie zażegnane?', 0),
(10112, 'plPL', 'Hmm, czy moja pamięć się poprawia?', 0),
(10167, 'plPL', '<Duch D\'ore cicho brzęczy.>$B$BWitaj, $N.', 0),
(10169, 'plPL', 'Wokół kociołka unosi się zapach ziół i przypraw.', 0),
(10211, 'plPL', 'Opowieści ludzi są ulotne, $N. Opowieści miast trwają przez długie lata.', 0),
(10231, 'plPL', 'No czego?', 0),
(10241, 'plPL', '$GWykonałeś:Wykonałaś; zadanie, $N?', 0),
(10246, 'plPL', '$GWykonałeś:Wykonałaś; zadanie, $N?', 0),
(10280, 'plPL', '<Muzyczne dźwięczenie mowy naaru wypełnia twój umysł.>$B$BWyczuwam, że masz przy sobie coś o wielkiej mocy. Co mi przynosisz?', 0),
(10325, 'plPL', 'Masz przy sobie insygnia naszych wrogów, $N?', 0),
(10326, 'plPL', 'Masz przy sobie kolejne insygnia naszych wrogów? Płonący Legion wciąż jest zagrożeniem, a my ścigamy go wszędzie, gdzie tylko go znajdziemy.', 0),
(10327, 'plPL', 'Przyjmę każdy znak, który ci został. Nie martw się, twoje czyny zostaną należycie odnotowane.', 0),
(10341, 'plPL', '$GWykonałeś:Wykonałaś; zadanie, $N?', 0),
(10409, 'plPL', 'Niech Światło będzie z tobą.', 0),
(10410, 'plPL', 'Co cię trapi, dziecko?', 0),
(10412, 'plPL', 'Śmiało, $N. Mów.', 0),
(10414, 'plPL', 'Nawet najmniejszy wkład w naszą sprawę zostaje odnotowany, $N. Nasi wrogowie są liczni, ale zwyciężymy!', 0),
(10415, 'plPL', 'Co ostatnio dla nas $gzrobiłeś:zrobiłaś;, $N? Wojna z Kael\'thasem sama się nie wygra, wiesz?', 0),
(10416, 'plPL', '$GZdobyłeś:Zdobyłaś; już tajemną księgę, $N?', 0),
(10419, 'plPL', '$GZdobyłeś:Zdobyłaś; więcej tajemnych ksiąg, $N?', 0),
(10420, 'plPL', '$GZdobyłeś:Zdobyłaś; już jakieś spaczone uzbrojenie, $N?', 0),
(10421, 'plPL', '$GNatrafiłeś:Natrafiłaś; ostatnio na spaczone uzbrojenie? Pozwól Światłu wykonać swoje dzieło, $N. Nie pozwól, by te plugawe przedmioty pozostały na tym świecie.', 0),
(10507, 'plPL', 'Czy to już załatwione, $N?', 0),
(10547, 'plPL', '<Tobias unosi brew.>$B$BKrwawy oset? Pierwsze słyszę... Jesteś z rozjemców? Wiesz, że $gmusiałbyś:musiałabyś; mi powiedzieć, gdybyś $gbył:była;... Mam swoje prawa!', 0),
(10550, 'plPL', 'Masz krwawy oset?', 0),
(10653, 'plPL', 'Masz przy sobie insygnia naszych wrogów, $N?', 0),
(10654, 'plPL', 'Masz przy sobie kolejne insygnia naszych wrogów? Płonący Legion wciąż jest zagrożeniem, a my ścigamy go wszędzie, gdzie tylko go znajdziemy.', 0),
(10655, 'plPL', 'Przyjmę każdy znak, który ci został. Nie martw się, twoje czyny zostaną należycie odnotowane.', 0),
(10656, 'plPL', 'Śmiało, $N. Mów.', 0),
(10658, 'plPL', 'Co ostatnio dla nas $gzrobiłeś:zrobiłaś;, $N? Wojna z Kael\'thasem sama się nie wygra, wiesz?', 0),
(10659, 'plPL', 'Nawet najmniejszy wkład w naszą sprawę zostaje odnotowany, $N. Nasi wrogowie są liczni, ale zwyciężymy!', 0),
(10704, 'plPL', '<Głos A\'dala melodyjnie wibruje w twoim umyśle.>$B$B$GWróciłeś:Wróciłaś;. Czy przynosisz oba odłamki klucza do Arkatrazu?', 0),
(10781, 'plPL', '<A\'dal cię wita.>', 0),
(10822, 'plPL', 'Nawet najmniejszy wkład w naszą sprawę zostaje odnotowany, $N. Nasi wrogowie są liczni, ale zwyciężymy!', 0),
(10826, 'plPL', 'Masz przy sobie insygnia naszych wrogów, $N?', 0),
(10827, 'plPL', 'Masz przy sobie kolejne insygnia naszych wrogów? Płonący Legion wciąż jest zagrożeniem, a my ścigamy go wszędzie, gdzie tylko go znajdziemy.', 0),
(10828, 'plPL', 'Przyjmę każdy znak, który ci został. Nie martw się, twoje czyny zostaną należycie odnotowane.', 0),
(10831, 'plPL', '$GWytworzyłeś:Wytworzyłaś; próbkę pierwotnej księżycowej tkaniny?', 0),
(10832, 'plPL', '$GZdobyłeś:Zdobyłaś; próbkę upiora Otchłani?', 0),
(10833, 'plPL', '$GUżyłeś:Użyłaś; mocy kryształu, by pogłębić swoją więź z Ołtarzem Cieni?', 0),
(10847, 'plPL', '$GWróciłeś:Wróciłaś;, $N. Jakie wieści przynosisz?', 0),
(10849, 'plPL', '$GPrzebyłeś:Przebyłaś; daleką drogę i niesiesz dla mnie wieści.', 0),
(10879, 'plPL', 'To nie czas na pogawędki, $N. Jesteśmy atakowani! Powstrzymaj najeźdźców!', 0),
(10882, 'plPL', '<A\'dal skupia na tobie uwagę, a jego spojrzenie jest niemal nie do zniesienia.>$B$BAndorrianie, być może nie rozumiesz wagi swojej misji? Nie ma czasu do stracenia... zbierz grupę towarzyszy i wejdź do Arkatrazu.$B$BPołóż kres zwiastunowi Skyrissowi.', 0),
(10884, 'plPL', '<A\'dal cię wita.>', 0),
(10885, 'plPL', '<A\'dal cię wita.>', 0),
(10886, 'plPL', '<A\'dal cię wita.>', 0),
(10888, 'plPL', '<A\'dal cię wita.>', 0),
(10898, 'plPL', 'Co cię tu sprowadza?', 0),
(10902, 'plPL', 'Esencje! Masz je?', 0),
(10917, 'plPL', 'Przynosisz pióra, o które prosiłem, $N?', 0),
(10918, 'plPL', 'Pieski Skettis wciąż bacznie pilnują nas, wyrzutków. Gdy tylko któryś z nas postawi stopę poza Shattrath, będzie jak martwy.$B$BPrzynoś mi więcej piór na dowód twojego zwycięstwa nad nimi.', 0),
(10966, 'plPL', 'Dobrze cię znowu widzieć. Ufam, że tobie i małej Dornai wspaniale upłynął wspólny czas?', 0),
(10967, 'plPL', 'Dobrze cię znowu widzieć. Ufam, że tobie i małej Salandrii wspaniale upłynął wspólny czas?', 0),
(11007, 'plPL', '$GUsłyszałeś:Usłyszałaś; moje wołanie? Tak...', 0),
(11024, 'plPL', 'Czuć od ciebie Skettis! Wytłumacz się!', 0),
(11072, 'plPL', '$GWykonałeś:Wykonałaś; zadanie, $N?', 0),
(11096, 'plPL', '$GWykonałeś:Wykonałaś; zadanie, $N?', 0),
(11098, 'plPL', 'Masz coś dla mnie, $gchłopcze:dziewczyno;?', 0),
(11108, 'plPL', 'Ależ $gmiałeś:miałaś; przygodę, $N.', 0),
(11195, 'plPL', 'Hej, $N! Słyszałem, że wkręcasz się do ekipy Budda. Nie dożyjesz dnia, w którym tego pożałujesz, przyjacielu, to ci mogę obiecać.$B$BCo tam masz, mon?', 0),
(11354, 'plPL', 'Poproszę szpicrutę.', 0),
(11362, 'plPL', 'Znów rozmawiamy... musisz mieć kostur.', 0),
(11363, 'plPL', 'Słyszałem szepty, że wódz wojenny ma zamiast dłoni broń. Czy to prawda?', 0),
(11364, 'plPL', '$GWróciłeś:Wróciłaś;. Czy wszyscy centurioni leżą martwi?', 0),
(11368, 'plPL', 'Mam nadzieję, że wiesz, jak zachować serce w dobrym stanie podczas transportu?', 0),
(11369, 'plPL', 'Znów rozmawiamy, bo masz jajo? Znakomicie, pokaż mi je!', 0),
(11370, 'plPL', 'Mój klient się niecierpliwi. Sądzę, że chce zgłębić taktyczną myśl wodza, by poradzić sobie w jednym ze swoich trwających konfliktów.', 0),
(11371, 'plPL', 'Jak idzie ci walka z siepaczami Żmijokolców?', 0),
(11372, 'plPL', 'Zbliża się ceremonia wodza.', 0),
(11373, 'plPL', 'Niewielu wie, że źródło magii Shaffara tkwi wyłącznie w jego amulecie. Bez niego jest bezsilny.$B$BZ drugiej strony, jeśli masz go ty, to znaczy, że Shaffar nie żyje.', 0),
(11374, 'plPL', 'Wyobrażasz sobie, że jest się uwięzionym w klejnocie na całą wieczność?', 0),
(11375, 'plPL', 'Nie mam nawet pewności, jaką postać ma przybierać szept w świecie materialnym, ale profesor zapewnia mnie, że rozpoznasz go, gdy go zobaczysz.$B$BMoże to coś w rodzaju krtani tej istoty?', 0),
(11376, 'plPL', 'Instruktorki – wszystkie martwe? Nie?$B$BCzyż nie mówiłem, żebyś nie $gwracał:wracała;, dopóki nie zabijesz ich wszystkich?', 0),
(11377, 'plPL', 'Czy ja czuję coś smakowitego?', 0),
(11378, 'plPL', 'Głowa Łowcy Epok... jak ktoś dochodzi do wniosku, że chce ją powiesić na ścianie?$B$BA na dodatek nie upolować bestii samemu – co taki ktoś mówi przyjaciołom, gdy pytają, jak poszła walka?$B$BPewnie kłamie.', 0),
(11379, 'plPL', 'Udał się mój mały eksperyment?', 0),
(11380, 'plPL', 'Masz szczęście, przyjacielu?', 0),
(11381, 'plPL', 'Co tak pięknie pachnie?', 0),
(11382, 'plPL', 'Na twoim miejscu bardzo bym uważał z podróżami w czasie. Nie $gchciałbyś:chciałabyś; przecież przypadkiem zrobić czegoś głupiego, na przykład zabić któregoś ze swoich przodków, i niechcący wymazać siebie z teraźniejszości!', 0),
(11383, 'plPL', 'Rozmawiamy, ale wyczuwam, że nie wszyscy władcy szczelin są martwi.$B$BWróć, gdy będą, $N.', 0),
(11384, 'plPL', '$GZgubiłeś:Zgubiłaś; drogę do Botaniki? Nie da się jej przeoczyć... to część Twierdzy Burz, przy wschodnim skraju Burzy Otchłani.', 0),
(11385, 'plPL', 'Jak to możliwe, że rozmawiamy, skoro nie wszyscy kanalizatorzy leżą martwi?', 0),
(11386, 'plPL', 'Sama technologia projektorów nie jest niczym szczególnym, ale zasięg tego modelu to prawdziwy przełom!', 0),
(11387, 'plPL', '<Tropiciel Otchłani przechyla głowę, wyraźnie zdziwiony twoją obecnością.>$B$BNiszczyciele nie zostali jeszcze zniszczeni.', 0),
(11388, 'plPL', 'Bezpośrednie mieszanie się w sprawy Przedwiecznych musi być bardzo niebezpieczne.$B$BLepiej ty niż ja!', 0),
(11389, 'plPL', 'Nie wiesz, jak dostać się do Twierdzy Burz i Arkatrazu? Na wschód przez Burzę Otchłani, a potem leć albo spadaj – wybór należy do ciebie.', 0),
(11499, 'plPL', 'Taras Magistrów musi być naprawdę niebezpiecznym miejscem, skoro leży tak blisko Słonecznej Studni.$b$bMam nadzieję, że nie masz wątpliwości?', 0),
(11500, 'plPL', 'To, co przemawia na wiatrach Otchłani, szepcze Mah\'duunowi. Mówi, że nie $gzałatwiłeś:załatwiłaś; jeszcze sprawy sióstr.$b$bCzyżby $N nie $gdbał:dbała; o nagrodę?', 0),
(11875, 'plPL', 'Masz dla mnie jakieś pozostałości?', 0),
(11877, 'plPL', '$GWróciłeś:Wróciłaś; z planami?', 0),
(11880, 'plPL', 'Masz te pomiary? Ten gnom znowu na mnie nawrzeszczy, jeśli nie dostanie swoich bezcennych danych.', 0),
(11885, 'plPL', '$GWykonałeś:Wykonałaś; zadanie, $N?', 0),
(12611, 'plPL', 'Czy to już załatwione, $N?', 0),
(12660, 'plPL', 'Czy to już załatwione, $N?', 0),
(13148, 'plPL', 'Co cię tu sprowadza?', 0),
(24522, 'plPL', 'Co cię tu sprowadza?', 0),
(24562, 'plPL', 'Co cię tu sprowadza?', 0);
