INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(2976, 'plPL', '(1) Raliq Pijak: Ogr. On nigdy nie wychodzić z kantyna. Wredny. Brzydki. Gruby. Wredny. I jeszcze bardzo gruby.$B$B[Następna strona]', 0),
(2977, 'plPL', '(2) Coosh\'coosh: Mały wkurzający grzybolud z Moczarów Zangarskich mieć grzybowy ogród na granica Moczarów Zangarskich i Terokkar. Przegrać dużo złoto do Sal\'salabim w grze „Co tak śmierdzi”. Próbować zapłacić Sal\'salabim głupim grzybem, co nazywać się świecący kapelusz. Mówić, że on dobry jak złoto! Ha!$B$B[Następna strona]', 0),
(2978, 'plPL', '(3) Floon: Arakkoa. Przegrać dużo złoto do Sal\'salabim. Sal\'salabim zabić ptakoluda, bo nie zapłacić. Teraz duch ptakoluda chodzić w północno-zachodnia część Kościanych Pustkowi.$B', 0);
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES
(9914, 'plPL', 'To dziecko przyprawia mnie o dreszcze. Stoi tam całymi dniami i rozmawia ze swoim dziadkiem. Potem odwraca się i mówi matce, co powiedział mu dziadek, a ona – rzecz jasna – tylko się uśmiecha i kiwa głową.$B$BBaranki! Lemingi! Wszyscy co do jednego!$B', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
