INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(15608, 1, 0, 'plPL', 'Co to ma być? Czempioni przybywają mi z pomocą? Wyczuwam w tym rękę mrocznego. Czyżby to święte wydarzenie naprawdę nosiło jego błogosławieństwo?'),
(18373, 0, 0, 'plPL', 'Zbezcześciliście miejsce spoczynku naszych przodków. Za tę zniewagę może być tylko jedna kara. To stosowne, że przybyliście do miejsca umarłych... bo wkrótce do nich dołączycie.');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(10568, 'plPL', 'Obawiam się, że długo byś nie $gprzetrwał:przetrwała; w Dolinie Alterak. Wróć do nas, jak nabierzesz jeszcze trochę doświadczenia.', 'Obawiam się, że długo byś nie $gprzetrwał:przetrwała; w Dolinie Alterak. Wróć do nas, jak nabierzesz jeszcze trochę doświadczenia.', 0),
(13689, 'plPL', '%s zaczyna się wyrywać z więzów!', '', 0),
(13690, 'plPL', '%s niemal uwolnił się z więzów!', '', 0),
(13691, 'plPL', '%s wyrywa się na wolność!', '', 0),
(14134, 'plPL', 'Walcz!', '', 0),
(14135, 'plPL', 'Dość tego. A teraz się cofnij!', '', 0),
(14455, 'plPL', 'Stanie się, mój panie.', 'Stanie się, mój panie.', 0),
(15179, 'plPL', 'Piaski czasu rozwieją się na wietrze!', 'Piaski czasu rozwieją się na wietrze!', 0),
(15180, 'plPL', 'Historia zaraz zostanie napisana na nowo!', 'Historia zaraz zostanie napisana na nowo!', 0),
(15181, 'plPL', 'Niech zacznie się oblężenie!', 'Niech zacznie się oblężenie!', 0),
(15182, 'plPL', 'Szczelina musi być chroniona!', 'Szczelina musi być chroniona!', 0),
(15183, 'plPL', 'Kończy wam się czas!', 'Kończy wam się czas!', 0),
(15184, 'plPL', 'Zwycięstwo albo śmierć!', 'Zwycięstwo albo śmierć!', 0),
(15185, 'plPL', 'Nigdy nas wszystkich nie pokonacie!', 'Nigdy nas wszystkich nie pokonacie!', 0),
(15186, 'plPL', 'Niczego nie osiągniecie!', 'Niczego nie osiągniecie!', 0),
(15187, 'plPL', 'Nie! Szczelina...', 'Nie! Szczelina...', 0),
(15425, 'plPL', 'Uważaj, wchodząc do gąszczu, $N. Unosi się tam szkodliwa aura. To muszą być pozostałości po tym, co zniszczyło moich braci druidów.', '', 0),
(15466, 'plPL', 'Powstańcie, moi polegli bracia! Przybierzcie postać i walczcie!', '', 0),
(15487, 'plPL', 'Co to ma znaczyć?!', '', 0),
(15488, 'plPL', 'Mam dużo pracy... bardzo dużo pracy! Co?', '', 0),
(15489, 'plPL', 'Empoor, powiesz mi, co chcę wiedzieć, albo pożałujesz!', 'Empoor, powiesz mi, co chcę wiedzieć, albo pożałujesz!', 0),
(15490, 'plPL', 'Teraz, kiedy już mnie prawie zatłuczono na śmierć, czego chcesz?', '', 0),
(15491, 'plPL', 'Już sobie idę!', '', 0),
(15514, 'plPL', 'Tawerna „Koniec Świata” nie ma nic do zaoferowania istotom takim jak ja. Zauważyłem jednak, że przyciąga klientelę zainteresowaną tym, co mam na sprzedaż.$B$BSpecjalizuję się w egzotycznych towarach inżynieryjnych sprowadzanych z najdalszych stron. Od czasu do czasu mam nawet na sprzedaż jakąś rzadkość czy dwie.$B$BCzym mógłbym cię zainteresować?', '', 0),
(15516, 'plPL', 'Co widzisz, gdy patrzysz na zachód, śmiertelniku?', '', 0),
(15517, 'plPL', 'Widzę pogiętą stal i czuję woń rozdartej ziemi.', 'Widzę pogiętą stal i czuję woń rozdartej ziemi.', 0),
(15518, 'plPL', 'Wiesz, co ja widzę? Zapowiedź inwazji.$B$BTak, pan postąpił mądrze, zamykając portale, ale od tamtej pory stracił... jak by to ująć? Pan stracił skupienie. Tak... Skupienie.$B$BLegion wykorzystał tę okazję. Teraz sączy się na zewnątrz, z każdym dniem jest ich więcej.', '', 0),
(15519, 'plPL', 'Legion?', 'Legion?', 0),
(15520, 'plPL', 'Płonący Legion. Demony. Widzę je tak wyraźnie, jak ty widzisz własną dłoń przed twarzą. A raczej kiedyś widziałem je wyraźnie.$B$BWraz z powrotem Legionu pojawiają się nowe knowania. W zwykłych okolicznościach potrafię wyczuć obecność demona z tysiąca kroków.$B$B<Altruis się krzywi.>', '', 0),
(15521, 'plPL', 'A teraz?', 'A teraz?', 0),
(15522, 'plPL', 'Umykają mi. Nie potrafię przejrzeć ich zabezpieczeń. Postawili osłony, które chronią ich przed wykryciem.$B$B<Altruis wskazuje na zachód.>$B$BBoją się nas, bo wiedzą, że my nie boimy się niczego. Cena takiej mocy jest wysoka, a ofiar wiele.', '', 0),
(15523, 'plPL', 'To jak ich teraz widzisz?', 'To jak ich teraz widzisz?', 0),
(15524, 'plPL', '<Altruis odwraca się do ciebie i uśmiecha.>$B$BNie widzę.$B$B<Altruis wskazuje na swojego wierzchowca, Nethrandamusa.>$B$BMusimy ich powstrzymać, zanim te obozy kuźnicze zdołają ukończyć to, co budują.', '', 0),
(15525, 'plPL', 'Obozy kuźnicze?', 'Obozy kuźnicze?', 0),
(15526, 'plPL', 'Tak nazywają się te budowle rozsiane po okolicy. Legion zaprzągł mo\'argów i gan\'argów do budowy broni masowej zagłady w tych ruchomych obozach kuźniczych. Nie przekonujmy się, co zamierzają zbudować tu, w Nagrandzie!$B$BBędziesz moimi oczami. Twoja broń będzie moją furią.', '', 0),
(15527, 'plPL', 'O nie, znowu ty! Odejdź!', '', 0),
(15532, 'plPL', 'Oto, co wywnioskowałem z informacji zebranych przez ciebie podczas rozpoznania.$B$BSą dwa główne obozy kuźnicze: Obóz Kuźniczy: Nienawiść, dokładnie na zachód od miejsca, w którym stoimy, i Obóz Kuźniczy: Strach, dokładnie na południowy zachód. W każdym obozie jest transporter Legionu, jedna kuźnia i kilka wież osłaniających przed zaklęciami. Ponadto obozów strzegą strażnicy gniewu obsadzający spaczone działa. Na koniec – w każdym obozie jest nadzorca, lord otchłani.$B$BNo to nie powinno być żadnego problemu...$B$B<Altruis się śmieje.>', '', 0),
(15544, 'plPL', '<Sal\'salabim warczy na ciebie, a potem wraca do picia swojego spienionego napoju.>', '', 0),
(15551, 'plPL', '[Demoniczny] Ka kalix!', '', 0),
(15552, 'plPL', 'Przysłał mnie Altruis. Powiedział, że możesz mi pomóc.', 'Przysłał mnie Altruis. Powiedział, że możesz mi pomóc.', 0),
(15559, 'plPL', 'CZEGO TY CHCIEĆ!?', '', 0),
(15560, 'plPL', 'Przysłał mnie Sal\'salabim, żebym $godebrał:odebrała; twój dług. Płać albo będę $gmusiał:musiała; zrobić ci krzywdę.', 'Przysłał mnie Sal\'salabim, żebym $godebrał:odebrała; twój dług. Płać albo będę $gmusiał:musiała; zrobić ci krzywdę.', 0),
(15567, 'plPL', 'Raliq dać ci teraz nauczka!', '', 0),
(15568, 'plPL', 'Jeszcze raz dziękuję, $N, że $gpomogłeś:pomogłaś; mi odkryć, co się tu stało, w gąszczu.', '', 0),
(15600, 'plPL', '', 'Moim zadaniem jest opieka nad tymi biedakami. Przyjmuję pomoc od każdego, kto zechce się przydać, czy to Aldora, czy Widzącego.$B$BMamy tak mało rąk do pracy, że nie odprawiłabym nawet ogra, gdyby umiał założyć opaskę uciskową. Miejska polityka mało mnie obchodzi.', 0),
(15601, 'plPL', '', 'Wyobrażasz sobie? Ten eteryk nie ma przy sobie ani jednego oka bazyliszka!$B$BA jego przywódca ma czelność nazywać siebie „Księciem Przemytników”!', 0),
(15641, 'plPL', '', 'Witaj, $N. Jesteśmy Aldorami, kapłanami Światła i sługami Sha\'tar.$B$BMożesz zostać z nami tak długo, jak potrzebujesz.', 0),
(15642, 'plPL', 'Kim są Sha\'tar?', 'Kim są Sha\'tar?', 0),
(15643, 'plPL', '', '„Zrodzeni ze światła” – tak mniej więcej można przetłumaczyć słowo Sha\'tar. Tak nazwaliśmy naaru, którzy odebrali Shattrath sługom Illidana.', 0),
(15644, 'plPL', 'Czy Shattrath nie jest miastem draenei? Dlaczego pozwalacie tu przebywać innym?', 'Czy Shattrath nie jest miastem draenei? Dlaczego pozwalacie tu przebywać innym?', 0),
(15645, 'plPL', '', 'Shattrath to coś więcej niż punkt zborny w wojnie z Płonącym Legionem i Illidanem. To także schronienie dla tych, którzy chcą uciec przed otaczającą nas przemocą.$B$BBylibyśmy hipokrytami, gdybyśmy odprawiali uchodźców.$B$BJeśli twoje pytanie dotyczy Widzących, odpowiem, że choć mogę nie lubić ich ani szalonych twierdzeń ich przywódcy o wizjach odkupienia, nie do nas należy kwestionowanie mądrości naaru.$B$BŻyjemy w trudnych czasach, $N. Musimy szukać sojuszników, gdzie tylko się da.', 0),
(15720, 'plPL', 'Przyglądam się, jak Aldorowie naprawiają mury. Wiesz, że odbudują całe miasto?$B$BPracują o wiele szybciej niż stary brygadzista Oslow u nas w Jeziernych Włościach. Ciągle gubił narzędzia w jeziorze albo gnolle zabierały mu materiały.$B$BPowinienem poprosić Aldorów, żeby mu kogoś przysłali do pomocy. Naprawiliby ten most w mgnieniu oka.', '', 0),
(15722, 'plPL', 'Malukaz bez przerwy trajkocze o historycznym znaczeniu tej puszczy, ale ja nie mogę sobie pozwolić na zajmowanie się historią, dopóki nie rozwiążemy obecnych problemów.$B$BNie twierdzę, że jego praca nie jest ważna, ale ktoś musi zadbać o obronę i zaopatrzenie warowni.', '', 0),
(15788, 'plPL', 'Szeregowy Weeks, potrzebuję kolejnego przebrania.', 'Szeregowy Weeks, potrzebuję kolejnego przebrania.', 0),
(15791, 'plPL', '', 'Musimy się dowiedzieć, co ta tajemnicza grupa robi w Wiosce Grangol\'var!', 0),
(15793, 'plPL', 'Mamy tu obowiązek, $gchłopcze:dziewczyno;, dopilnować, żeby nikt nas nie zaskoczył.$B$BA to oznacza działanie z wyprzedzeniem!', '', 0),
(15795, 'plPL', '$GSłyszałeś:Słyszałaś;, że w Labiryncie Cieni całkowicie stracili kontrolę nad Szmerem?!', '$GSłyszałeś:Słyszałaś;, że w Labiryncie Cieni całkowicie stracili kontrolę nad Szmerem?!', 0),
(15796, 'plPL', 'Za mało nam za to płacą. Ale ta zrujnowana wioska to i tak lepsze niż skradanie się po Auchindoun.', 'Za mało nam za to płacą. Ale ta zrujnowana wioska to i tak lepsze niż skradanie się po Auchindoun.', 0),
(15797, 'plPL', 'Zaciągnąłem się, bo obiecali mi opłacić naukę w akademii. Wujek mówi, że mogę zacząć w przyszłym sezonie!', 'Zaciągnąłem się, bo obiecali mi opłacić naukę w akademii. Wujek mówi, że mogę zacząć w przyszłym sezonie!', 0),
(15798, 'plPL', 'Hej, ty pewnie jesteś tym nowym rekrutem! Miło cię poznać!$B$BSą jakieś wieści z Labiryntu Cieni w Auchindoun, czy odzyskaliśmy już kontrolę nad Szmerem?', 'Hej, ty pewnie jesteś tym nowym rekrutem! Miło cię poznać!$B$BSą jakieś wieści z Labiryntu Cieni w Auchindoun, czy odzyskaliśmy już kontrolę nad Szmerem?', 0),
(15799, 'plPL', 'Jeśli masz ochotę, kilku z nas wybiera się później do Shattrath na drinka.', 'Jeśli masz ochotę, kilku z nas wybiera się później do Shattrath na drinka.', 0),
(15800, 'plPL', 'Chcesz dołączyć do ligi skórzanej piłki? Gramy głównie od poniedziałku do środy.$B$BMożesz do nas dołączyć po tej zmianie. Porzucamy sobie trochę.', 'Chcesz dołączyć do ligi skórzanej piłki? Gramy głównie od poniedziałku do środy.$B$BMożesz do nas dołączyć po tej zmianie. Porzucamy sobie trochę.', 0),
(15801, 'plPL', 'Mam nadzieję, że to miejsce sprawdzi się jako wysunięta baza dla operacji Rady Cieni. Wiem, że to brzmi dziwnie, ale trochę tęsknię za Labiryntem Cieni.', 'Mam nadzieję, że to miejsce sprawdzi się jako wysunięta baza dla operacji Rady Cieni. Wiem, że to brzmi dziwnie, ale trochę tęsknię za Labiryntem Cieni.', 0),
(15802, 'plPL', '<Nachyla się bliżej.>$B$BTak między nami, myślę, żeby którejś nocy się stąd „zwinąć”. Wiesz, o co mi chodzi?', '<Nachyla się bliżej.>$B$BTak między nami, myślę, żeby którejś nocy się stąd „zwinąć”. Wiesz, o co mi chodzi?', 0),
(15803, 'plPL', 'Za kogo ty się masz, że wchodzisz tu i się do mnie odzywasz? Jestem przywódcą Rady Cieni w tej wiosce. Zejdź mi z oczu!$B$BJeśli jeszcze raz cię zobaczę, będę ostatnią osobą, jaką ujrzysz w życiu. Rozumiesz?$B$BA może wolisz zostać $gpogrzebany:pogrzebana; w labiryncie Auchindoun albo złożony w ofierze Szmerowi?', '', 0),
(15827, 'plPL', 'Przerzucając stosy ksiąg i zwojów na stole, %s zaczyna z zainteresowaniem przyglądać się jednemu z nich.', '', 0),
(15829, 'plPL', 'Co? Co to ma być?!', '', 0),
(15830, 'plPL', 'To w ogóle nie mieści się w głowie!', '', 0),
(15831, 'plPL', 'Wygląda na to, że wybrałem zły dzień na rzucenie picia.', '', 0),
(15832, 'plPL', 'Jak można było to przeoczyć?!', '', 0),
(15833, 'plPL', 'Kapitanie, sir, mamy mały problem.', '', 0),
(15838, 'plPL', 'Jak pan każe, sir. Wygląda na to, że ktoś zapomniał mi wspomnieć, że druidzi z Gąszczu Cenariona zostali wybici!', '', 0),
(15839, 'plPL', 'Złe wieści. Znowu nas zaatakowali. Już ich nie ma, ale przednia wieża wartownicza się pali.', '', 0),
(15840, 'plPL', 'Zaginął jeden z naszych kupców!', '', 0),
(15842, 'plPL', 'Ta grupa, która niedawno przybyła z Warowni Honoru – to najemnicy! Zaczynają sprawiać kłopoty. Może powinienem z nimi porozmawiać?', '', 0),
(15843, 'plPL', 'Jeden z naszych zwiadowców melduje, że jakaś tajemnicza grupa zajęła ruiny Wioski Grangol\'var. Ups, ten raport ma już ponad tydzień.', '', 0),
(15844, 'plPL', 'Mamy meldunek od zwiadowcy w terenie, że jeden z druidów Cenariona został pojmany w Punkcie Ognistego Skrzydła.', '', 0),
(15847, 'plPL', 'Czy twoje umiejętności są już dość wprawne, by nauczyć się tego, czego mogę cię nauczyć?', 'Czy twoje umiejętności są już dość wprawne, by nauczyć się tego, czego mogę cię nauczyć?', 0),
(15853, 'plPL', 'Tak jest, sir. Już się robi!', '', 0),
(15996, 'plPL', '', 'Jako przedstawicielka Dolnego Miasta jestem tu, by przedstawić nasze stanowisko: Auchindoun trzeba oczyścić z plagi Rady Cieni. Oczywiście jeśli mamy mieć jakąkolwiek nadzieję na przyszłość i zapobiec kataklizmowi większemu niż ten, który stworzył Kościane Pustkowia!$B$BWszystkie nasze ludy wycierpiały już zbyt wiele. Jestem tu, by dopilnować, żeby to cierpienie się skończyło!', 0),
(16051, 'plPL', '<Isfar wzdycha.>$B$BKilka domków na drzewach to jeszcze nie dom, ale to i tak ogromna poprawa w porównaniu z Salami Sethekk.$B$BChoć w Shattrath było mi wygodnie, nie potrafię wrócić do mojego prawdziwego domu w Skettis bez siostry. Wciąż jest uwięziona w Salach Sethekk, trzymana w niewoli przez naszego starszego brata.', '', 0),
(16064, 'plPL', 'Sethekk uważają się za prawdziwych i najwierniejszych wyznawców pana wszystkich arakkoa. Nie pytaj o pana, bo jego tajemnice przeznaczone są wyłącznie dla ludu pierza.$B$BSethekk uznali zniszczenie Auchindoun za przybycie naszego pana na ten świat. Wyruszyli do ruin, zabierając ze sobą relikwie naszego największego bohatera, Terokka.$B$BWciąż szukają pana w ruinach świątyni, ale dziś widzę ich kłamstwa na wylot. Nie jestem już jednym z nich.', '', 0),
(16066, 'plPL', '„Szponi Król” Ikiss jest jednym z przywódców Sethekk, obok mojego brata, Tkacza Mroku Sytha.$B$BTo oni poprowadzili exodus Sethekk ze Skettis do ruin Auchindoun. Na początku Ikiss był charyzmatycznym przywódcą, ale popadł w obłęd.$B$BTeraz otwarcie głosi, że jest odrodzonym Terokkiem! Naprawdę oczekuje, że arakkoa ugną przed nim kolana jak przed swoim władcą. Wyobrażasz sobie taką arogancję?', '', 0),
(16067, 'plPL', 'Kim jest Szponi Król Ikiss?', 'Kim jest Szponi Król Ikiss?', 0),
(16068, 'plPL', 'Kim są Sethekk?', 'Kim są Sethekk?', 0),
(16069, 'plPL', 'Gdzie znajdę relikwie Terokka?', 'Gdzie znajdę relikwie Terokka?', 0),
(16070, 'plPL', 'Kim jest ten Terokk, o którym ciągle wspominasz?', 'Kim jest ten Terokk, o którym ciągle wspominasz?', 0),
(16071, 'plPL', 'To największy bohater, jakiego znali arakkoa.$B$BPowiada się, że w dawnych czasach zbudował miasto Skettis własnymi szponami. Był naszym największym czempionem i obrońcą, ale opuścił nas, gdy odwróciliśmy się od czci Rukhmar.$B$BZaczęliśmy czcić nowego pana, który obiecał nam niewyobrażalną potęgę i pozycję w kosmosie.$B$BNiektórzy mówią, że Terokk i Rukhmar to jedno i że odwrócił się od nas, gdy my odwróciliśmy się od niego.', '', 0),
(16123, 'plPL', 'Powiedz mi jeszcze raz, co wiesz!', 'Powiedz mi jeszcze raz, co wiesz!', 0),
(16202, 'plPL', 'Ty – chodź tutaj. Czyż te ostrza nie są najwyższej jakości? Z pewnością chcesz coś ode mnie kupić. Nigdzie indziej nie znajdziesz broni wykonanej z takim kunsztem i starannością.', '', 0),
(16203, 'plPL', 'Na co się gapisz?', '', 0),
(16219, 'plPL', 'Lubisz ryby? Mam tu ryby. Jeśli lubisz świeże ryby, najświeższe, podejdź i spróbuj mojego towaru.', '', 0),
(16296, 'plPL', 'SPRZEDAWCO OWOCÓW!!! Twój wózek wciąż nam zawadza! Dajemy ci jeszcze godzinę, żebyś zabrała go z naszego terenu. Nie wystawiaj dłużej naszej cierpliwości na próbę!', 'SPRZEDAWCO OWOCÓW!!! Twój wózek wciąż nam zawadza! Dajemy ci jeszcze godzinę, żebyś zabrała go z naszego terenu. Nie wystawiaj dłużej naszej cierpliwości na próbę!', 0),
(16307, 'plPL', '', 'Mogłabym przysiąc, że miałam więcej jabłek. Grok!', 0),
(16314, 'plPL', '', 'O co krzyczy ten biedny ork? Ktoś powinien sprawdzić, co się dzieje.', 0),
(16354, 'plPL', 'Gakarah ma!', '', 0),
(16377, 'plPL', 'Już za kilka minut komediowy występ Perry\'ego Gatnera!', 'Już za kilka minut komediowy występ Perry\'ego Gatnera!', 0),
(16380, 'plPL', 'Jeśli masz ochotę się pośmiać, zajrzyj do tawerny „Koniec Świata”!', 'Jeśli masz ochotę się pośmiać, zajrzyj do tawerny „Koniec Świata”!', 0),
(16383, 'plPL', 'Dziękuję wszystkim za przybycie. A teraz gorące brawa na powitanie najlepszego w Shattrath – Perry\'ego Gatnera!', '', 0),
(16384, 'plPL', 'Perry Gatner! Co za występ! Kantyna jest otwarta całą noc, więc zostańcie i bawcie się dobrze!', '', 0),
(16506, 'plPL', 'Anachoreto Nindumenie, mam do ciebie prośbę.', '', 0),
(16507, 'plPL', 'Właśnie wysłaliśmy do Nagrandu kolejny niedoświadczony oddział. Czy mógłbyś odmówić za nich modlitwę?', '', 0),
(16521, 'plPL', 'Oczywiście, przyjacielu. Jak mogę ci służyć?', '', 0),
(16524, 'plPL', 'Szlachetna prośba. To będzie dla mnie zaszczyt, Erothemie.', '', 0),
(16526, 'plPL', 'Przyjaciele, przyłączcie się do mnie w pokornej modlitwie do Światła.', '', 0),
(16531, 'plPL', 'Światło, które przyjmujemy, błagamy cię...', '', 0),
(16533, 'plPL', 'Do walki z ciemnością posłaliśmy nasze dzieci.', '', 0),
(16534, 'plPL', 'Pobłogosław je i chroń, i daj im zwycięstwo nad tymi, którzy chcą nas skrzywdzić...', '', 0),
(16535, 'plPL', 'Błogosław nadal ten nasz pradawny dom, błagamy.', '', 0),
(16536, 'plPL', 'Obdarz nas cierpliwością wobec naszych elfich gości.', '', 0),
(16595, 'plPL', '<Gdy zbliżasz się do naaru, wypełnia cię kojące światło. W twoim umyśle rozbrzmiewają powolne, melodyjne dźwięki i choć nie pada ani jedno słowo, czujesz pewność, że nic ci tu nie grozi. W Shattrath jesteś mile widzianym gościem.>', '', 0),
(16611, 'plPL', 'Poratujesz miedziakiem, $gpanie:pani;?', 'Poratujesz miedziakiem, $gpanie:pani;?', 0),
(16612, 'plPL', 'Hej, $gkolego:paniusiu;? Masz trochę grosza? Mam pięcioro dzieci do wykarmienia!', 'Hej, $gkolego:paniusiu;? Masz trochę grosza? Mam pięcioro dzieci do wykarmienia!', 0),
(16613, 'plPL', 'Proszę, nie ignorujcie nas...', 'Proszę, nie ignorujcie nas...', 0),
(16614, 'plPL', 'Masz jakiegoś zbędnego miedziaka?', 'Masz jakiegoś zbędnego miedziaka?', 0),
(16697, 'plPL', 'To my jesteśmy prawdziwą Hordą!', 'To my jesteśmy prawdziwą Hordą!', 0),
(16698, 'plPL', 'Za Kargatha! Za zwycięstwo!', 'Za Kargatha! Za zwycięstwo!', 0),
(16699, 'plPL', 'Gakarah ma!', 'Gakarah ma!', 0),
(16700, 'plPL', 'Krew jest naszą siłą!', 'Krew jest naszą siłą!', 0),
(16701, 'plPL', 'Lok\'tar Illadari!\n', 'Lok\'tar Illadari!\n', 0),
(16702, 'plPL', 'Ten świat jest NASZ!', 'Ten świat jest NASZ!', 0),
(16703, 'plPL', 'Lok narash!', 'Lok narash!', 0),
(16708, 'plPL', 'Za Pana!', 'Za Pana!', 0),
(16709, 'plPL', 'Illidan panuje!', 'Illidan panuje!', 0),
(16710, 'plPL', 'Giń, ciepłokrwisty!', 'Giń, ciepłokrwisty!', 0),
(16711, 'plPL', 'Na głębiny Nazjataru!', 'Na głębiny Nazjataru!', 0),
(16712, 'plPL', 'Moja krew jest jak jad!', 'Moja krew jest jak jad!', 0),
(16735, 'plPL', 'Przyjaciele, z wielką radością witam was dziś w świątyni.', '', 0),
(16740, 'plPL', 'A\'dal był dla mnie, pokornego sługi Światła, niezwykle hojny w swoich objawieniach.', '', 0),
(16741, 'plPL', 'Zgodnie z moim boskim powołaniem muszę dzielić się tymi objawionymi prawdami ze wszystkimi, którzy zechcą słuchać.', '', 0),
(16742, 'plPL', 'Dano mi poznać, że w każdym z nas mieszka Światło...', '', 0),
(16743, 'plPL', '...że jest ono darem danym za darmo wszystkim istotom zrodzonym w naturalny sposób.', '', 0),
(16752, 'plPL', 'Objawia się jako uczucie, z początku słabe i łatwe do zignorowania, które potwierdza prawdę i delikatnie skłania do czynienia dobra.', '', 0),
(16753, 'plPL', 'Zwykła życzliwość, miłosierne uczynki, służba potrzebującym. Wszystko to są owoce Światła.', '', 0),
(16754, 'plPL', 'Tych, którzy słuchają jego podszeptów, nagradza błogosławieństwami, zarówno widzialnymi, jak i niewidzialnymi.', '', 0),
(16755, 'plPL', 'Wewnętrzne zasoby nadziei i wiary rosną w siłę, a zdolność przyjęcia większego światła się pogłębia.', '', 0),
(16756, 'plPL', 'Z czasem, dzięki posłuszeństwu wobec przewodnictwa Światła, człowiek staje się bardziej wrażliwy na jego głos i jego moc.', '', 0),
(16757, 'plPL', 'Wielka jest uzdrawiająca i błogosławiąca moc najgorliwszych wyznawców Światła.', '', 0),
(16761, 'plPL', 'Niestety, są i tacy, którzy przemierzają doczesność wbrew Światłu.', '', 0),
(16762, 'plPL', 'Od nich Światło się odsuwa, aż pozostaje tylko ciemność.', '', 0),
(16763, 'plPL', 'Gdzie nie ma światła, tam kwitną rozpacz, odraza i gniew.', '', 0),
(16764, 'plPL', 'Urodziliśmy się w niebezpiecznej epoce, w której siły ciemności są zdecydowane doprowadzić do naszej zagłady.', '', 0),
(16765, 'plPL', 'To czas, by odnaleźć jedność ze Światłem.', '', 0),
(16766, 'plPL', 'Słuchajcie moich słów i niech Światło w was potwierdzi ich prawdę.', '', 0),
(16775, 'plPL', 'Przyjmijcie światło, które jest w was, przyjaciele! Wyrzeknijcie się wszelkiej ciemności...', '', 0),
(16776, 'plPL', 'Musimy wiernie przetrwać te ciężkie czasy, a pewnego dnia odniesiemy zwycięstwo.', '', 0),
(16778, 'plPL', 'Na naaru, niech tak się stanie.', '', 0),
(16780, 'plPL', 'Niech tak się stanie.', 'Niech tak się stanie.', 0),
(16787, 'plPL', 'Nadszedł czas! Gul\'danie, każ swoim czarnoksiężnikom podwoić wysiłki! Za chwilę brama się otworzy, a twoja Horda zostanie wypuszczona na ten dojrzały, niczego niepodejrzewający świat!', '', 0),
(16790, 'plPL', 'Nie! Przeklęta niech będzie ta słaba, śmiertelna powłoka!', '', 0),
(16792, 'plPL', 'Czempioni! Moja tarcza słabnie!', '', 0),
(16794, 'plPL', 'Moja moc musi się skupić na portalu! Nie mam czasu podtrzymywać tarczy!', '', 0),
(16795, 'plPL', 'Tarcza prawie znikła! Wszystko, na co pracowałem, jest zagrożone!', '', 0),
(16796, 'plPL', 'Dziękuję wam za pomoc, czempioni. Teraz Horda Gul\'dana przetoczy się przez ten świat jak chmara szarańczy, a wszystkie moje zamysły, wszystkie starannie ułożone plany wreszcie się dopełnią.', '', 0),
(16804, 'plPL', 'Chłodna bryza muska twoją twarz. W komnacie rozbrzmiewa łagodne, melodyjne nucenie.\n', '', 0),
(16805, 'plPL', 'Ten świat spłonie!', 'Ten świat spłonie!', 0),
(16807, 'plPL', 'Nadszedł koniec!', 'Nadszedł koniec!', 0),
(16808, 'plPL', 'Przyjmij Nicość!', 'Przyjmij Nicość!', 0),
(16809, 'plPL', 'Żałosny robaku!', 'Żałosny robaku!', 0),
(16810, 'plPL', 'Nikt nie oprze się Legionowi!', 'Nikt nie oprze się Legionowi!', 0),
(16811, 'plPL', 'Nasycę się twoją duszą!', 'Nasycę się twoją duszą!', 0),
(16812, 'plPL', 'Nie uciekniesz.', 'Nie uciekniesz.', 0),
(16813, 'plPL', 'Jedyną sprawiedliwością jest śmierć!', 'Jedyną sprawiedliwością jest śmierć!', 0),
(16870, 'plPL', '', 'Z całym szacunkiem, A\'dal przysłał nas tutaj, żebyśmy zbadali poczynania Kaela, a nie przypuszczali zmasowany atak.', 0),
(16872, 'plPL', 'Słuchaj, słonko. Nikt nie mówi o tym, żebyśmy sami szturmowali Twierdzę Burz, ale kiedy trafia się dogodny cel, musimy go wykorzystać.', '', 0),
(16873, 'plPL', 'Trzymaj język za zębami, łotrze! Nie waż się mówić takim tonem do kapłanki Światła!', '', 0),
(16875, 'plPL', '', 'Magistrix ucieszy się, gdy się dowie, że biegle władam thalasyjskim. Twoja uprzejmość nie uszła mojej uwadze.', 0),
(16876, 'plPL', '', 'Wracając do tematu... powinniśmy się skupić na tych kuźniach many. Musimy się dowiedzieć, co wróg z nimi robi i po co.', 0),
(16881, 'plPL', '', 'Gorące.', 0),
(16882, 'plPL', '', 'Pfff... nieważne.', 0),
(16887, 'plPL', '', 'Gorący żart.', 0),
(16888, 'plPL', '', 'Ja, jakby, w ogóle tego nie łapię...', 0),
(16889, 'plPL', '...i tylko spójrzcie, dokąd nas to zaprowadziło!', '', 0),
(16890, 'plPL', 'Nawet ty musisz przyznać, że twoje informacje od dezerterów są przestarzałe i niewiarygodne. Przeprowadźmy przemyślane ataki na te kuźnie many i zbierzmy tyle informacji, ile się da.', '', 0),
(16891, 'plPL', 'Nareszcie wielkolud mówi o działaniu!', '', 0),
(16914, 'plPL', 'Czy oni nigdy nie odpoczywają?!$B$BJeśli mamy zapewnić przyszłość mieszkańcom Dolnego Miasta, musimy rozprawić się z Radą Cieni, zanim wywoła kataklizm jeszcze większy niż ten, który stworzył Kościane Pustkowia!$B$BPonieważ przywódcy Shattrath nie działają szybko, my, wolni ludzie Dolnego Miasta, wzięliśmy sprawy w swoje ręce.$B$BAle nasi szpiedzy zostali zdemaskowani. Zatrzymamy agentów Rady Cieni, a ty w tym czasie wślizgnij się do labiryntu i zobacz, czego zdołasz się dowiedzieć.', '', 0),
(16958, 'plPL', '', 'Witaj w Forcie Alleriańskim, $N.', 0),
(16995, 'plPL', '', 'Witaj, co cię tu sprowadza?$B$BTo sierociniec dla dzieci z Rubieży, które straciły rodziców i nie mają nikogo innego, kto by się nimi zaopiekował.$B$BMoże przychodzisz, bo rozważasz adopcję?', 0),
(17093, 'plPL', 'Przez lata byłem przekonany, że w Srebrnej Lunie postępujemy słusznie – pracując nad tym, by dotrzeć na Rubież i połączyć się z Kaelem.$B$BGdybym wiedział, co Kael\'thas dla nas szykuje, zostałbym na Placu Sokolego Skrzydła.', '', 0),
(17336, 'plPL', 'Nie dam się tak łatwo pojmać! Niech zadrżą mury tego więzienia... i niech runą!', '', 0),
(17339, 'plPL', 'Nędzne, wścibskie owady! Uwolnijcie mnie, a może obdarzę was litościwą śmiercią!', '', 0),
(17340, 'plPL', 'Robactwo! Pijawki! Bierzcie moją krew i się nią udławcie!', '', 0),
(17341, 'plPL', 'Illidan to arogancki głupiec! Zmiażdżę go i odzyskam Rubież dla siebie!', '', 0),
(17342, 'plPL', 'Precz, bezmyślne pasożyty! Moja krew należy do mnie!', '', 0),
(17343, 'plPL', 'Jak długo, waszym zdaniem, wasze żałosne czary zdołają mnie utrzymać?', '', 0),
(17344, 'plPL', 'Moja krew będzie waszą zgubą!', '', 0),
(17346, 'plPL', 'Jestem... wreszcie... wolny!', '', 0),
(17347, 'plPL', 'Legion pochłonie was wszystkich!', '', 0),
(17348, 'plPL', 'Nie znowu! Nie znowu...', '', 0),
(17349, 'plPL', 'Myśleliście, że jestem słaby? Miękki? Kto jest teraz słaby?', '', 0),
(17353, 'plPL', 'Czas dać ci lekcję dobrych manier, $gchłoptasiu:dziewuszko;!', '', 0),
(17354, 'plPL', 'Liczę do trzech. Jak się stąd nie wyniesiesz, poszczuję cię psami.', '', 0),
(17357, 'plPL', 'Czas stanąć przed Stwórcą!', '', 0),
(17361, 'plPL', 'Dobra, poddajemy się! Nie róbcie nam krzywdy!', '', 0),
(17364, 'plPL', 'Spadaj, $gmały:mała;. Mam interesy do załatwienia...', '', 0),
(17365, 'plPL', 'Ezekiel mówił, że możesz mieć pewną książkę...', 'Ezekiel mówił, że możesz mieć pewną książkę...', 0),
(17644, 'plPL', 'Niech twój umysł spowije mgła.', '', 0),
(17645, 'plPL', 'Spójrz w ciemność swojej duszy.', '', 0),
(17646, 'plPL', 'Tu... jest moje miejsce.', '', 0),
(17647, 'plPL', 'Zapłacisz życiem!', '', 0),
(17648, 'plPL', 'Teraz nie ma już odwrotu!', '', 0),
(17649, 'plPL', 'Odbądź pokutę!', '', 0),
(17650, 'plPL', 'Te mury będą twoim grobowcem!', '', 0),
(17651, 'plPL', 'Teraz zostaniesz... na wieczność.', '', 0),
(17744, 'plPL', 'Dobrze widzieć przyjaciela Aldorów w tych odległych stronach. Obawiam się, że długo już nie zniosę bezczelnej paplaniny tych elfów.', '', 0),
(17795, 'plPL', 'Witaj w Burzowej Iglicy, $N.$B$BProszę, nie zrażaj się tym, że jestem tu obecny za pośrednictwem tego urządzenia obrazującego. Mam wielu wrogów, którzy chętnie widzieliby mnie martwego, więc to tylko środek ostrożności.$B$BZapewniam cię, że jesteś tu zupełnie $gbezpieczny:bezpieczna;.', '', 0),
(18115, 'plPL', '', 'Choć uwaga Sha\'tar skupia się na Dolinie Cienistego Księżyca i Illidanie, nie możemy lekceważyć zagrożenia, jakie stanowi Kael\'thas Słońcobieżca.', 0),
(18164, 'plPL', 'Zadanie strażnika Światła jest dwojakie. Po pierwsze i najważniejsze – za wszelką cenę chronić kapłanów. Po drugie – niszczyć wrogów Światła, gdziekolwiek się ukrywają.', '', 0),
(18389, 'plPL', 'Przyszliśmy po ciebie, zagubiony bracie. Zwyczaj nakazuje dać ci szansę na skruchę, zanim zostaniesz zniszczony. Dajemy ci tę szansę, jak nakazuje prawo naaru.', '', 0),
(18390, 'plPL', 'Nie rozśmieszaj mnie. To jest ta potężna armia Aldorów, która przyszła mnie pokonać?', '', 0),
(18391, 'plPL', 'Może jest nas niewielu, Socretharze, ale nasza wiara jest silna. To coś, czego nigdy nie zrozumiesz. A teraz, gdy zwyczajowi stało się zadość, przygotuj się na swój koniec.', '', 0),
(18392, 'plPL', 'Tak, załatwmy to. Zanim jednak zaczniemy, chciałbym wam kogoś przedstawić.', '', 0),
(18393, 'plPL', 'Jak... jak mogłeś?!', '', 0),
(18397, 'plPL', 'Socrethar mąci ci w głowie, Kaylaanie! Nie mówisz tego naprawdę! Pamiętam, jak cię szkoliłem, gdy byłeś jeszcze dzieckiem. Już wtedy miałeś silną wolę!', '', 0),
(18400, 'plPL', '', 'Światło chce odzyskać swojego zagubionego syna, Socretharze.', 0),
(18401, 'plPL', '', 'Ofiaruję w zamian siebie. Będziesz mieć Ishanah, Wielką Kapłankę Aldorów, jako swojego więźnia, jeśli uwolnisz Kaylaana ze swojego mrocznego uścisku.', 0),
(18402, 'plPL', 'Ty głupia stara wiedźmo... Po co miałbym to robić, skoro mogę mieć was oboje?', '', 0),
(18406, 'plPL', 'Och, proszę cię! Aż mnie mdli. Chyba będę musiał sam was wszystkich pozabijać.', '', 0),
(18407, 'plPL', 'Zabij te psy, Kaylaanie! Zasłuż na swoje miejsce w Płonącym Legionie!', '', 0),
(18408, 'plPL', 'Na co czekasz? Wykończ ich, młodzieńcze. Niech twoja nienawiść płonie!', '', 0),
(18492, 'plPL', '', 'Opuszczenie Kael\'thasa to najlepsze, co ktokolwiek z nas kiedykolwiek zrobił. Jego zwolennicy są zbyt ślepi albo zbyt przerażeni, by zrozumieć, dokąd ich prowadzi.$B$BMy jednak tacy nie jesteśmy.', 0),
(18547, 'plPL', 'Są tacy, którzy kłamią i przekręcają prawdę. Jasnowidze natomiast wydobywają prawdę na światło dzienne.$B$BCelem tej biblioteki, $N, jest uczynić jasnowidzem każdego.', '', 0),
(18590, 'plPL', 'Czas stawić czoła Socretharowi, $N. $GJesteś gotów:Jesteś gotowa;?', '', 0),
(18591, 'plPL', 'Jestem $ggotów:gotowa;, Adyenie.', 'Jestem $ggotów:gotowa;, Adyenie.', 0),
(18612, 'plPL', 'O tak, mam babeczki!', '', 0),
(18613, 'plPL', 'Dobra, babeczkarzu, pokaż mi swoje babeczki!', 'Dobra, babeczkarzu, pokaż mi swoje babeczki!', 0),
(18616, 'plPL', 'Babeczki mam tutaj. Podejdźcie!', '', 0),
(18617, 'plPL', 'Tak, tak, jestem babeczkarzem. Wiecie dlaczego? Bo sprzedaję babeczki, ot co!', '', 0),
(18620, 'plPL', 'Nie ma to jak pełny kufel, żeby popić jedną z moich wspaniałych babeczek.', '', 0),
(18621, 'plPL', 'O tak, tego było mi trzeba. Babeczki na sprzedaż! Świeże babeczki, tylko tutaj!', '', 0),
(18732, 'plPL', 'Zwycięstwo albo śmierć!', '', 0),
(18739, 'plPL', '%s zaczyna rzucać Rozbłysk podmuchu!', '', 0),
(18799, 'plPL', '%s czerpie energię z powietrza...', '', 0),
(18841, 'plPL', '', 'Nie zapominaj, że w Azeroth wciąż szaleją bitwy. Wrócisz, by wesprzeć Hordę w Dolinie Alterak?', 0),
(18842, 'plPL', 'Throm\'ka. Wiesz, że nasza walka ze Strażniczkami Srebrnego Skrzydła w Wąwozie Wojennej Pieśni wciąż trwa? Twoja obecność byłaby tam mile widziana...', '', 0),
(18844, 'plPL', 'Przebyłem daleką drogę w poszukiwaniu sposobu, by ostatecznie pokonać Ligę Aratoru w Kotlinie Aratorskiej, ale ten przygłup w przepasce biodrowej, Adam Eternum, depcze mi po piętach na każdym kroku.\n$b\nMimo to, gdyby pogromcy tacy jak ty wrócili do Azeroth, może udałoby się nam rozprawić z Przymierzem raz na zawsze!', '', 0),
(18847, 'plPL', '', 'Jak tam u ciebie? Rubież już ci się przejadła i pora wracać do Doliny Alterak, żeby dać Hordzie popalić?', 0),
(18848, 'plPL', 'Strażniczki Srebrnego Skrzydła wciąż walczą z Hordą w Wąwozie Wojennej Pieśni. Pozostaje się przekonać, czy wrócisz tam, by im pomóc.', '', 0),
(18849, 'plPL', 'Przybyłem do Rubieży w nadziei, że odkryję potężne artefakty, które pomogą Lidze Aratoru w walce z Plugawicielami w Kotlinie Aratorskiej... ale znalazłem tylko tę bombową magiczną przepaskę biodrową, niedorzecznego gnomiego pomagiera i nieumarłego prześladowcę z przerostem ego, który upiera się, że ukradłem mu jego szarą czaszkę czy coś w tym guście.\n$b\nTak czy inaczej, może zechcesz dołączyć do walki Ligi, podczas gdy ja będę szukał dalej?', '', 0),
(18850, 'plPL', '<Można odnieść wrażenie, że Oric jest tu tylko w ramach żałosnej próby rozładowania atmosfery i nie należy zwracać na niego uwagi, bo tylko go to zachęci.>', '', 0),
(18856, 'plPL', '<To olbrzymi, opancerzony, osiodłany kot bojowy. Czy to nie dość głupie, nawet bez tego, żeby jeszcze mówił?>', '', 0),
(18864, 'plPL', '', 'Tylko mag może się nauczyć magii portali.', 0),
(18865, 'plPL', '', 'Magu... chcesz się nauczyć magii portali, tak?', 0),
(18968, 'plPL', 'Witaj w Shattrath, siedzibie Sha\'tar na Rubieży. Szukasz wskazówek?', 'Witaj w Shattrath, siedzibie Sha\'tar na Rubieży. Szukasz wskazówek?', 0),
(19091, 'plPL', 'Stąpaj ostrożnie. Za tym mostem leży piekło.', '', 0),
(19098, 'plPL', '%s rozbija zgniłe jajo i – ku przerażeniu i konsternacji wszystkich wokół – zaczyna pić z jego cuchnącego wnętrza.', '', 0),
(19099, 'plPL', 'To zmieniło moje życie... Przepraszam na chwilę.', '', 0),
(19100, 'plPL', '%s wydaje z siebie najohydniejsze beknięcie, jakie kiedykolwiek słyszano i czuto.', '', 0),
(19101, 'plPL', 'No dobrze, wracajmy do interesów.', '', 0),
(19112, 'plPL', 'Zawładnięcie umysłem słabych to drobnostka... bo jestem wierny potęgom nietkniętym przez czas i niewzruszonym przez los. Żadna siła na tym świecie ani poza nim nie ma dość mocy, by zmusić nas do ugięcia kolan... nawet potężny Legion!', '', 0),
(19113, 'plPL', 'Oto sprawca waszej zguby!', '', 0),
(19180, 'plPL', 'Kryj się! Kryj się, zanim cię zobaczą! Cofnij się!', '', 0),
(19181, 'plPL', 'Nadeszła chwila, by uderzyć. Zlikwiduj Icariusa.', '', 0),
(19182, 'plPL', 'Boraku, potrzebuję kolejnego pęku krwawego ostu.', 'Boraku, potrzebuję kolejnego pęku krwawego ostu.', 0),
(19183, 'plPL', 'Masz. Nie zgub go znowu!', '', 0),
(19211, 'plPL', 'W Shattrath są dwa banki, oba na obrzeżach centralnego placu miasta. Jeden prowadzą draenei z Aldorów, drugi krwawe elfy z Widzących.', 'W Shattrath są dwa banki, oba na obrzeżach centralnego placu miasta. Jeden prowadzą draenei z Aldorów, drugi krwawe elfy z Widzących.', 0),
(19212, 'plPL', 'Bank Aldorów', 'Bank Aldorów', 0),
(19213, 'plPL', 'Bank Widzących', 'Bank Widzących', 0),
(19214, 'plPL', 'Bank Aldorów znajduje się na północny zachód od centrum miasta.', 'Bank Aldorów znajduje się na północny zachód od centrum miasta.', 0),
(19215, 'plPL', 'Bank Widzących znajduje się na południowy wschód od centrum miasta.', 'Bank Widzących znajduje się na południowy wschód od centrum miasta.', 0),
(19216, 'plPL', 'Karczmy w Shattrath są pełne rannych uchodźców. Wciąż jest jednak miejsce u draenei z Aldorów i krwawych elfów z Widzących, na Wzniesieniu Aldorów i na Tarasie Widzących.', 'Karczmy w Shattrath są pełne rannych uchodźców. Wciąż jest jednak miejsce u draenei z Aldorów i krwawych elfów z Widzących, na Wzniesieniu Aldorów i na Tarasie Widzących.', 0),
(19217, 'plPL', 'Karczma Aldorów', 'Karczma Aldorów', 0),
(19218, 'plPL', 'Karczma Widzących', 'Karczma Widzących', 0),
(19219, 'plPL', 'Karczma Aldorów znajduje się wysoko nad Shattrath, na Wzniesieniu Aldorów. Winda prowadząca na górę jest na północny zachód od centrum miasta.', 'Karczma Aldorów znajduje się wysoko nad Shattrath, na Wzniesieniu Aldorów. Winda prowadząca na górę jest na północny zachód od centrum miasta.', 0),
(19220, 'plPL', 'Karczma Widzących znajduje się nad Shattrath, na Tarasie Widzących. Winda prowadząca na górę jest na południowy zachód od centrum miasta.', 'Karczma Widzących znajduje się nad Shattrath, na Tarasie Widzących. Winda prowadząca na górę jest na południowy zachód od centrum miasta.', 0),
(19221, 'plPL', 'Lotmistrzem w Shattrath jest Nutral. Znajdziesz go na wschód od centrum miasta.', 'Lotmistrzem w Shattrath jest Nutral. Znajdziesz go na wschód od centrum miasta.', 0),
(19222, 'plPL', 'Skrzynki pocztowe znajdziesz w bankach i karczmach Aldorów i Widzących albo tuż przed nimi.', 'Skrzynki pocztowe znajdziesz w bankach i karczmach Aldorów i Widzących albo tuż przed nimi.', 0),
(19223, 'plPL', 'Stajenni są tuż przed obiema karczmami – draenei i krwawych elfów – na Wzniesieniu Aldorów i na Tarasie Widzących.', 'Stajenni są tuż przed obiema karczmami – draenei i krwawych elfów – na Wzniesieniu Aldorów i na Tarasie Widzących.', 0),
(19224, 'plPL', 'Stajnia Aldorów', 'Stajnia Aldorów', 0),
(19225, 'plPL', 'Stajnia Widzących', 'Stajnia Widzących', 0),
(19226, 'plPL', 'Mistrzowie bitewni w Shattrath zbierają się zwykle na schodach między górnym a dolnym miastem. Mistrzowie bitewni Przymierza gromadzą się w jednym miejscu, Hordy w innym, a mistrzowie bitewni areny pomiędzy nimi i naprzeciwko.', 'Mistrzowie bitewni w Shattrath zbierają się zwykle na schodach między górnym a dolnym miastem. Mistrzowie bitewni Przymierza gromadzą się w jednym miejscu, Hordy w innym, a mistrzowie bitewni areny pomiędzy nimi i naprzeciwko.', 0),
(19227, 'plPL', 'Mistrzowie bitewni Przymierza', 'Mistrzowie bitewni Przymierza', 0),
(19228, 'plPL', 'Mistrzowie bitewni Hordy', 'Mistrzowie bitewni Hordy', 0),
(19229, 'plPL', 'Mistrzów bitewnych Przymierza znajdziesz zwykle na schodach na północny wschód od centrum miasta.', 'Mistrzów bitewnych Przymierza znajdziesz zwykle na schodach na północny wschód od centrum miasta.', 0),
(19230, 'plPL', 'Mistrzów bitewnych Hordy znajdziesz zwykle na schodach na południowy wschód od centrum miasta.', 'Mistrzów bitewnych Hordy znajdziesz zwykle na schodach na południowy wschód od centrum miasta.', 0),
(19231, 'plPL', 'Jakiego nauczyciela szukasz?', 'Jakiego nauczyciela szukasz?', 0),
(19239, 'plPL', 'Lorokeem, wielki mistrz alchemii i wygnaniec ze Skettis, mieszka wśród innych arakkoa w północno-zachodniej części Dolnego Miasta.', 'Lorokeem, wielki mistrz alchemii i wygnaniec ze Skettis, mieszka wśród innych arakkoa w północno-zachodniej części Dolnego Miasta.', 0),
(19240, 'plPL', 'Jacka Trappera znajdziesz przy gotowaniu na otwartym targu w południowo-wschodniej części Dolnego Miasta.', 'Jacka Trappera znajdziesz przy gotowaniu na otwartym targu w południowo-wschodniej części Dolnego Miasta.', 0),
(19241, 'plPL', 'Tawerna „Koniec Świata”', 'Tawerna „Koniec Świata”', 0),
(19242, 'plPL', 'Tawerna „Koniec Świata” znajduje się w najdalej na wschód wysuniętej części Dolnego Miasta.', 'Tawerna „Koniec Świata” znajduje się w najdalej na wschód wysuniętej części Dolnego Miasta.', 0),
(19243, 'plPL', 'Najwyższego zaklinacza Bardolana znajdziesz w Bibliotece Jasnowidza na Tarasie Widzących. To wielki mistrz tej sztuki, otoczony swoimi uczniami: mistrzami, rzemieślnikami, ekspertami i czeladnikami.', 'Najwyższego zaklinacza Bardolana znajdziesz w Bibliotece Jasnowidza na Tarasie Widzących. To wielki mistrz tej sztuki, otoczony swoimi uczniami: mistrzami, rzemieślnikami, ekspertami i czeladnikami.', 0),
(19245, 'plPL', 'Mildred Fletcher znajdziesz w lecznicy w północno-wschodniej części Dolnego Miasta.', 'Mildred Fletcher znajdziesz w lecznicy w północno-wschodniej części Dolnego Miasta.', 0),
(19246, 'plPL', 'Draeneiowego wielkiego mistrza jubilerstwa, Hamanara, znajdziesz wśród jego ludu na Wzniesieniu Aldorów.', 'Draeneiowego wielkiego mistrza jubilerstwa, Hamanara, znajdziesz wśród jego ludu na Wzniesieniu Aldorów.', 0),
(19247, 'plPL', 'Seymoura, głównego skórnika w Shattrath i wielkiego mistrza tego fachu, znajdziesz na otwartym targu w Dolnym Mieście.', 'Seymoura, głównego skórnika w Shattrath i wielkiego mistrza tego fachu, znajdziesz na otwartym targu w Dolnym Mieście.', 0),
(19248, 'plPL', 'Wielką mistrzynię garbarstwa Darmari znajdziesz na otwartym targu w Dolnym Mieście.', 'Wielką mistrzynię garbarstwa Darmari znajdziesz na otwartym targu w Dolnym Mieście.', 0),
(19250, 'plPL', 'Płatnerza i kowala broni, Kradu Ponure Ostrze i Zulę Żużlową Furię, znajdziesz przy pracy przy wielkiej kuźni w Dolnym Mieście.', 'Płatnerza i kowala broni, Kradu Ponure Ostrze i Zulę Żużlową Furię, znajdziesz przy pracy przy wielkiej kuźni w Dolnym Mieście.', 0),
(19252, 'plPL', 'Potrzebuję kolejnego przebrania, Boraku. $GZgubiłem:Zgubiłam; poprzednie.', 'Potrzebuję kolejnego przebrania, Boraku. $GZgubiłem:Zgubiłam; poprzednie.', 0),
(19361, 'plPL', '<Tajemny strażnik zdaje się zwracać ku tobie, ale nic nie mówi.>', '', 0),
(19362, 'plPL', '<Tajemny strażnik wskazuje najdalej na wschód wysuniętą część Dolnego Miasta.>', '', 0),
(19363, 'plPL', '<Tajemny strażnik wskazuje miejsce na południowy wschód od centrum miasta.>', '', 0),
(19364, 'plPL', '<Tajemny strażnik wskazuje na drugą stronę Tarasu, w stronę karczmy.>', '', 0),
(19368, 'plPL', '<Tajemny strażnik wskazuje miejsce na wschód od centrum miasta.>', '', 0),
(19370, 'plPL', '<Tajemny strażnik wskazuje miejsce po drugiej stronie Tarasu, w stronę karczmy i pobliskiej skrzynki pocztowej.>', '', 0),
(19371, 'plPL', '<Tajemny strażnik wskazuje na drugą stronę Tarasu, w stronę karczmy i stojącego przed nią stajennego.>', '', 0),
(19372, 'plPL', '<Tajemny strażnik stoi bez ruchu, czekając, aż sprecyzujesz, o których mistrzów bitewnych ci chodzi.>', '', 0),
(19402, 'plPL', 'Nie bój się. Po prostu graj ze mną.', '', 0),
(19403, 'plPL', 'Zwykły kłopot, zapewniam! Powiedz Panu, że jego więźniarka nie ucieknie, dopóki Akama i jego Zaprzysiężeni jej pilnują.', '', 0),
(19405, 'plPL', 'Wybacz moje surowe metody, ale Zdrajca nie może poznać prawdy. Mój sekret musi zostać zachowany za wszelką cenę!', '', 0),
(19406, 'plPL', 'Dla wielu z mojego ludu jestem zdrajcą... pieskiem Illidana. Na razie lepiej, żeby dalej tak myśleli.', '', 0),
(19408, 'plPL', 'W swoim czasie, Maiev. Latami przygotowywałem się do tego ruchu – nie mogę narażać moich planów, odkrywając karty zbyt wcześnie.', '', 0),
(19442, 'plPL', '', 'Jestem niesłychanie zajęta.$B$BMamy na głowie straszny problem, którym trzeba się natychmiast zająć!', 0),
(19443, 'plPL', 'Hildagard, potrzebuję nowych gogli.', 'Hildagard, potrzebuję nowych gogli.', 0),
(19459, 'plPL', 'Władza Illidana nad tą krainą słabnie. Czujesz to, $N?', '', 0),
(19563, 'plPL', 'Przychodzisz pomóc w sprawie zakłóceń?', '', 0),
(19564, 'plPL', 'Zorusie, potrzebuję nowych gogli.', 'Zorusie, potrzebuję nowych gogli.', 0),
(19565, 'plPL', 'Opowiedz mi o poligonie łowców demonów w Ruinach Karaboru.', 'Opowiedz mi o poligonie łowców demonów w Ruinach Karaboru.', 0),
(19566, 'plPL', 'W nagrodę za lata służby Illidan pozwolił Kael\'thasowi przysłać mu pięciu wojowników na szkolenie. Po raz pierwszy krwawe elfy mogły szkolić się na łowców demonów.$B$BSzkolenie było brutalne. Illidan poddał wojowników Kaela próbom, które pokonałyby większość w pełni wyszkolonych łowców demonów.$B$BTrzech elfów Kaela zginęło podczas szkolenia, jeden oszalał.$B$BJednemu się udało.', '', 0),
(19567, 'plPL', 'Nazywał się Varedis. Ku zaskoczeniu Illidana nie tylko przeszedł katorżnicze rytuały przejścia będące częścią szkolenia, ale już wtedy panował nad swoimi mocami lepiej niż wielu doświadczonych łowców demonów.$B$BIllidan wyczuł w Varedisie potencjał i przydzielił mu trzech mistrzów spośród łowców demonów, by dalej szkolili go w swoich metodach.', '', 0),
(19568, 'plPL', 'Po roku szkolenia u trzech najlepszych łowców demonów Illidana Varedis ich prześcignął.$B$BNie zadowalając się już tym, czego mogli go nauczyć, Varedis przeniknął do Rady Cieni, gdzie dowiedział się o potężnym relikcie zwanym Księgą spaczonych imion. Potajemnie ją czytał, zapamiętując każdy ustęp.', '', 0),
(19569, 'plPL', 'Podobno znajomość prawdziwego imienia demona daje pewną władzę nad nim.$B$BMówi się, że Księga spaczonych imion zawiera prawdziwe imię każdego demona, jaki kiedykolwiek istniał. Zapamiętując ustępy księgi, Varedis znalazł źródło mocy dorównujące tej, którą sam Illidan zaczerpnął z Czaszki Gul\'dana.$B$BNa prośbę Illidana Varedis prowadzi teraz poligon w Ruinach Karaboru – wraz z trzema mistrzami, którzy go szkolili.', '', 0),
(19571, 'plPL', 'Nie dziwi, że krwawe elfy mają tak wielki potencjał jako łowcy demonów. W końcu sin\'dorei nie mają naturalnej awersji do demonicznej magii, jaką mają nocne elfy.$B$BNie spodziewam się jednak, by wielu z nich odniosło sukces. Większość z nich, łącznie z Varedisem, dąży do mocy dla niej samej. Ta moc ich pochłonie, bo nie napędza ich czysty ogień, który płonie w sercu prawdziwego łowcy demonów.', '', 0),
(19572, 'plPL', 'Niezła historia.', 'Niezła historia.', 0),
(19573, 'plPL', '$GChciałem:Chciałam; cię jeszcze o coś zapytać, Altruisie.', '$GChciałem:Chciałam; cię jeszcze o coś zapytać, Altruisie.', 0),
(19575, 'plPL', 'Słucham.', 'Słucham.', 0),
(19576, 'plPL', 'Ciekawe.', 'Ciekawe.', 0),
(19600, 'plPL', '<Tajemny strażnik w milczeniu czeka, aż powiesz coś więcej.>', '', 0),
(19614, 'plPL', 'Ta księga dałaby mi nieograniczoną władzę nad moimi wrogami... Stałbym się... niepowstrzymany!', '', 0),
(19615, 'plPL', 'Nie... musisz mi ją odebrać, $N! Już czuję, jak jej mroczna moc nagina moją wolę! Użyj jej, by zniszczyć Varedisa.', '', 0),
(19637, 'plPL', '<Tajemny strażnik wskazuje miejsce poniżej Tarasu – schody na północny wschód od centrum miasta.>', '', 0),
(19638, 'plPL', '<Tajemny strażnik wskazuje miejsce poniżej Tarasu – schody na południowy wschód od centrum miasta.>', '', 0),
(19640, 'plPL', '<Tajemny strażnik wskazuje północno-zachodnią część Dolnego Miasta, gdzie mieszkają arakkoa z Shattrath.>', '', 0),
(19641, 'plPL', '<Tajemny strażnik wskazuje w dół, na Dolne Miasto, gdzie znajduje się wielka kuźnia.>', '', 0),
(19642, 'plPL', '<Tajemny strażnik wskazuje w dół, na otwarty targ w południowo-wschodniej części Dolnego Miasta.>', '', 0),
(19646, 'plPL', '<Tajemny strażnik wskazuje Bibliotekę Jasnowidza.>', '', 0),
(19647, 'plPL', '<Tajemny strażnik wskazuje północno-wschodnią część Dolnego Miasta.>', '', 0),
(19648, 'plPL', '<Tajemny strażnik wskazuje Wzniesienie Aldorów.>', '', 0),
(19650, 'plPL', '<Tajemny strażnik wskazuje otwarty targ w Dolnym Mieście.>', '', 0),
(19651, 'plPL', 'Witaj na Wzniesieniu Aldorów. Szukasz wskazówek?', 'Witaj na Wzniesieniu Aldorów. Szukasz wskazówek?', 0),
(19652, 'plPL', 'Ośrodek opieki znajdziesz w południowej części Wzniesienia Aldorów.', 'Ośrodek opieki znajdziesz w południowej części Wzniesienia Aldorów.', 0),
(19653, 'plPL', 'Skrzynkę pocztową znajdziesz w pobliżu ośrodka opieki.', 'Skrzynkę pocztową znajdziesz w pobliżu ośrodka opieki.', 0),
(19654, 'plPL', 'Stajennego znajdziesz w pobliżu ośrodka opieki.', 'Stajennego znajdziesz w pobliżu ośrodka opieki.', 0),
(19656, 'plPL', 'Wielkiego mistrza jubilerstwa, Hamanara, znajdziesz w północnej części Wzniesienia Aldorów.', 'Wielkiego mistrza jubilerstwa, Hamanara, znajdziesz w północnej części Wzniesienia Aldorów.', 0),
(19753, 'plPL', 'Jest takie stare powiedzenie: „Daj człowiekowi rybę, a nakarmisz go na jeden dzień. Naucz człowieka łowić ryby, a nakarmisz go na całe życie”. Oczywiście tę rybę warto by jeszcze przyrządzić i tu właśnie wkraczam ja.', '', 0),
(19813, 'plPL', 'Twój los jest przesądzony.', '', 0),
(19814, 'plPL', 'Chaos, który tu zasiałem, to zaledwie przedsmak...', '', 0),
(19815, 'plPL', 'Jestem tylko jednym z... nieskończonych zastępów.', '', 0),
(19816, 'plPL', 'Będziesz wykonywać moje rozkazy, słabeuszu.', '', 0),
(19818, 'plPL', 'Uciekaj w przerażeniu.', '', 0),
(19819, 'plPL', 'Pokażę ci okropności, o jakich ci się nie śniło.', '', 0),
(19821, 'plPL', 'Przenikamy wszechświat, niezliczeni jak gwiazdy!', '', 0),
(19858, 'plPL', 'Serce Furii... Dawno temu widziałem jego moc, gdy władał nim Velen. Czuję, że ta sama moc płynie przez nie w tej chwili!', '', 0),
(19859, 'plPL', 'Z mocą tego kryształu moi Zaprzysiężeni i ja... bylibyśmy niepowstrzymani! Moglibyśmy zniszczyć Illidana! Moglibyśmy... zająć jego miejsce jako władcy Rubieży!', '', 0),
(19860, 'plPL', 'Ale to nie jest częścią wizji, która została mi dana... nie tak... mój lud zostanie wyzwolony.', '', 0),
(19870, 'plPL', 'Proszę, $N. Musisz zanieść Serce Furii w bezpieczne miejsce... musisz zanieść je A\'dalowi!', '', 0),
(19890, 'plPL', 'Informacji, której szukasz... nie mogę ci dać za darmo. Musisz udowodnić, że twoi wrogowie są także moimi.', '', 0),
(19901, 'plPL', '', 'Walka z Kael\'thasem i Illidanem trwa na wszystkich frontach. Porażka nie wchodzi w grę.', 0),
(19909, 'plPL', 'Orkowie Hordy! Ten portal to brama do waszego nowego przeznaczenia! Azeroth leży przed wami, dojrzały do zdobycia!', '', 0),
(19911, 'plPL', 'Gul\'dan mówi prawdę! Powinniśmy natychmiast wrócić i przekazać te wieści naszym braciom! Wycofać się przez portal!', '', 0),
(20134, 'plPL', 'Mogę cię uczyć garbarstwa. Chcesz?', 'Mogę cię uczyć garbarstwa. Chcesz?', 0),
(20135, 'plPL', 'Mogę cię uczyć kowalstwa. Chcesz?', 'Mogę cię uczyć kowalstwa. Chcesz?', 0),
(20157, 'plPL', '%s wskazuje niebo w górze.', '', 0),
(20223, 'plPL', '', 'Witaj, $N. Specjalizuję się w sztuce pracy z pierwotną księżycową tkaniną. Krawcy, którzy chcą zostać specjalistami od księżycowej tkaniny, często proszą mnie, bym nauczyła ich naszych metod.', 0),
(20226, 'plPL', '', 'Miło cię poznać! Jestem Gidge, tutejsza ekspertka od krawiectwa ognia zaklęć w Shattrath. Nie żebym miała jakąś konkurencję, ale jeśli chcesz zostać $gkrawcem:krawcową; ognia zaklęć i nie $gwybrałeś:wybrałaś; jeszcze specjalizacji, mogę ci pomóc.', 0),
(20228, 'plPL', 'Jeśli szukasz wykrojów albo wiedzy o krawiectwie tkaniny cienia, chętnie ci pomogę.', '', 0),
(20254, 'plPL', '%s skrzeczy i leci w stronę Zasłony Shalas. Pospiesz się i leć za nim!', '', 0),
(20255, 'plPL', '%s zatrzymuje się na chwilę przed drzewem, a potem wlatuje do środka.', '', 0),
(20256, 'plPL', '%s najwyraźniej czegoś szuka. Chce, żebyś $gpodążył:podążyła; za nim.', '', 0),
(20257, 'plPL', '%s sfruwa na platformę poniżej! Lepiej skacz, jeśli chcesz za nim nadążyć. Szybko!', '', 0),
(20266, 'plPL', 'Nadciągają kolejne sługi Terokka!', '', 0),
(20267, 'plPL', 'Najeźdźcy nie ustępują! Powstrzymajcie ich!', '', 0),
(20268, 'plPL', 'Awatar Terokka!! Do broni!', '', 0),
(20270, 'plPL', 'Awatar Terokka został pokonany! Śmierć Terokkowi! Śmierć Skettis!', '', 0),
(20284, 'plPL', '%s wydaje donośny skrzek!', '', 0),
(20288, 'plPL', '', 'Kiedy zakładałam w Shattrath swoją akademię łotrzyków, nie było tu nawet w połowie tak tłoczno. Potem zaczęli napływać uchodźcy, a naaru potrzebowali każdego wolnego budynku, żeby ich pomieścić.$B$BNa razie zamknęłam akademię, ale to nie na zawsze. Znajdę sobie nowe miejsce.$B$BA wtedy nowe pokolenie łotrzyków pozna takie podstawy jak „podbij oko i się uśmiechnij”, plądrowanie w trakcie walki i zwalanie na innych winy za przerwanie polimorfii. No i kto mógłby zapomnieć o naczelnej zasadzie łotrostwa: prawdziwy łotrzyk nie idzie na fintę.', 0),
(20289, 'plPL', 'Znów $gprzeszedłem:przeszłam; szkolenie alchemika. Chcę się specjalizować w eliksirach.', 'Znów $gprzeszedłem:przeszłam; szkolenie alchemika. Chcę się specjalizować w eliksirach.', 0),
(20291, 'plPL', '', 'Sztuka korzystania z Wymknięcia polega na tym, by zrozumieć, że najlepsze piętnaście sekund w życiu to często te ostatnie.', 0),
(20293, 'plPL', '', 'Miecze, szpony, sztylety, oczywiście – szkoliłam łotrzyków we władaniu nimi wszystkimi. Ale buzdygany? Buzdyganów nie tknę i nie będę uczyć łotrzyka, któremu przyjdzie do głowy walczyć buzdyganem.$B$BW buzdyganie nie ma nic skrytego. Jeśli pójdziesz tą drogą, czeka cię hałaśliwe zabójstwo i długie sprzątanie.', 0),
(20294, 'plPL', '', 'Na moich pierwszych zajęciach zawsze jest pełno młodzików z błyskiem w oku. Mało który przechodzi jednak pierwszy sprawdzian.$B$BDałam sobie spokój z krzyczeniem: „Kiedy wołam »znikaj«, macie zniknąć”. I tak nigdy nie słuchają. Teraz sprawdzian po prostu zabija nieudaczników.', 0),
(20295, 'plPL', 'Nareszcie wolny od tej okropnej klątwy! Dziękuję! Przekaż, proszę, Rilakowi Odkupionemu, że nic mi nie jest. Moja misja wiedzie do Skettis. Terokk musi zostać pokonany!', '', 0),
(20296, 'plPL', '', 'Nigdy nie wychodź z domu bez solidnego zapasu proszku błyskowego, zwłaszcza gdy pracujesz z innymi. Gwarantuję, że zawsze komuś się skończy.$B$BKiedy muszę wybierać między rozdawaniem materiałów a pozwoleniem, żeby jakiś biedak zginął, pomagam... zazwyczaj.', 0),
(20297, 'plPL', '%s oddala się w dal.', '', 0),
(20383, 'plPL', 'Pracownia alchemiczna', 'Pracownia alchemiczna', 0),
(20384, 'plPL', 'Nasz alchemik Lorokeem przyniósł ze sobą swój sprzęt. Może się nieco różnić od tego, do czego $gprzywykłeś:przywykłaś; – w końcu to arakkoa – ale powinien ci wystarczyć. Gnieździ się w północno-zachodniej części Dolnego Miasta.', 'Nasz alchemik Lorokeem przyniósł ze sobą swój sprzęt. Może się nieco różnić od tego, do czego $gprzywykłeś:przywykłaś; – w końcu to arakkoa – ale powinien ci wystarczyć. Gnieździ się w północno-zachodniej części Dolnego Miasta.', 0),
(20385, 'plPL', 'Handlarki klejnotami', 'Handlarki klejnotami', 0),
(20386, 'plPL', 'Na miejscu są dwie handlarki klejnotami: jedna ściśle współpracuje z Widzącymi, a druga jest wierna Aldorom. Kogo szukasz?', 'Na miejscu są dwie handlarki klejnotami: jedna ściśle współpracuje z Widzącymi, a druga jest wierna Aldorom. Kogo szukasz?', 0),
(20388, 'plPL', 'Handlarka klejnotami Aldorów', 'Handlarka klejnotami Aldorów', 0),
(20389, 'plPL', 'Inessera to bystra kobieta, która sprzedaje różne klejnoty i materiały jubilerskie. Jej sklep znajdziesz w północnej części Wzniesienia Aldorów.', 'Inessera to bystra kobieta, która sprzedaje różne klejnoty i materiały jubilerskie. Jej sklep znajdziesz w północnej części Wzniesienia Aldorów.', 0),
(20390, 'plPL', 'Handlarka klejnotami Widzących', 'Handlarka klejnotami Widzących', 0),
(20391, 'plPL', 'Lisrythe może z początku nieco... onieśmielać, ale ma w ofercie to, czego szukasz. Sprzedaje swoje towary we wschodniej części Tarasu Widzących.', 'Lisrythe może z początku nieco... onieśmielać, ale ma w ofercie to, czego szukasz. Sprzedaje swoje towary przed wielką biblioteką na Tarasie Widzących.', 0),
(20392, 'plPL', '<Konstrukt wskazuje wschodnią część Tarasu.>', '', 0),
(20429, 'plPL', 'Chcesz ze mną rozmawiać?', '', 0),
(20452, 'plPL', 'Tydzień Dziecka jeszcze się nie skończył... czy mogę dostać kolejny gwizdek sieroty krwawych elfów?', 'Tydzień Dziecka jeszcze się nie skończył... czy mogę dostać kolejny gwizdek sieroty krwawych elfów?', 0),
(20453, 'plPL', 'Tydzień Dziecka jeszcze się nie skończył... czy mogę dostać kolejny gwizdek draenejskiej sieroty?', 'Tydzień Dziecka jeszcze się nie skończył... czy mogę dostać kolejny gwizdek draenejskiej sieroty?', 0),
(20490, 'plPL', 'Olumie... stary przyjacielu. Dobrze widzieć, że jesteś bezpieczny.', '', 0),
(20491, 'plPL', 'Illidan nabierze podejrzeń... to pewne. Poradzimy sobie z tym jak zawsze.', '', 0),
(20492, 'plPL', 'Nie możesz... mówić poważnie, Olumie. Twoja ofiara już i tak była zbyt wielka.', '', 0),
(20493, 'plPL', 'Wygląda więc na to, że podjąłeś decyzję. Poprowadzimy cię do świata duchów z całą życzliwością, na jaką nas stać.', '', 0),
(20494, 'plPL', 'Żegnaj, drogi przyjacielu. Spotkamy się w następnym świecie, gdy wypełnimy nasze obowiązki w tym.', '', 0),
(20495, 'plPL', 'Panie! Znaleźliśmy zdrajcę, który uciekł Vash! Jego ciało leży przede mną... martwe!', '', 0),
(20496, 'plPL', 'Ależ, panie! Źle oceniłeś moje czyny... Wiem o kimś bliskim tobie, kto planuje cię zdradzić. To ten pies, Kael\'thas! Sprzymierzył się z Kil\'jaedenem i zamierza zająć twoje miejsce jako Władca Rubieży!', '', 0),
(20497, 'plPL', 'Stanie się, mój panie!', '', 0),
(20531, 'plPL', '', 'Konflikty w Rubieży są bardziej zabójcze niż wszystkie, jakie dotąd widziałam. A ich najtragiczniejszymi ofiarami są dzieci, które zostają same.$B$BTeraz, gdy Shattrath zagrażają arakkoa ze Skettis, sierot, którymi trzeba się zająć, będzie jeszcze więcej. Te dzieci często żyją bez nadziei na świetlaną przyszłość.', 0),
(20642, 'plPL', 'Grok szukać pomocy. Mały iść w góry i pomóc Krwawe Młoty!', '', 0),
(20645, 'plPL', 'Synowie Gruula muszą zostać pokonani, jeśli mamy zrzucić kajdany i znów żyć jako wolne ogry!$B$BMusimy działać po cichu, ale szybko, jeśli nasz podziemny ruch oporu ma mieć szansę powodzenia.', '', 0),
(20648, 'plPL', 'Grok potrzebować pomocy! Czemu nikt nie pomóc?', '', 0),
(20664, 'plPL', 'Grok się zdenerwować, jak chuderlaki nie pójść do Gór Klingi i nie gadać z Mog\'dorgiem!', '', 0),
(20693, 'plPL', '%s zaczyna ukierunkowywać moc Światła.', '', 0),
(20697, 'plPL', '', 'Może i znasz się co nieco na zwierzakach, ale czy $gwzbiłeś:wzbiłaś; się kiedy w przestworza? My, Dzikie Młoty, umiemy dosiadać wiatru jak mało kto. Za drobną opłatą, jak masz dość odwagi, wyszkolę cię jak należy.', 0),
(20737, 'plPL', '%s milknie, a pobliskie siły Sha\'tar ogarnia ciche napięcie, gdy Xi\'ri podejmuje decyzję.', '', 0),
(20762, 'plPL', 'Wyglądasz, jakbyś się $gznał:znała; na zwierzętach biegających po ziemi, ale jeśli chcesz szybować, będzie to wymagało szkolenia i poświęcenia. I złota. Masz złoto, prawda?', '', 0),
(20776, 'plPL', 'Nad Shattrath zapada cisza.', '', 0),
(20777, 'plPL', 'Myśli %s wdzierają się do twojego umysłu.', '', 0),
(20778, 'plPL', '$N i $gjego:jej; sojusznicy pokonali Kael\'thasa Słońcobieżcę.\n', '', 0),
(20779, 'plPL', 'Teraz jest czas, by uderzyć na pozostałe krwawe elfy w Twierdzy Burz. Chwyćcie za broń i niech bitewna pieśń A\'dala doda wam sił!\n', '', 0),
(20780, 'plPL', 'Nie obchodzi mnie, kim jesteś ani co robisz poza Podniebną Strażą, ale dopóki tu jesteś, będziesz robić, co ci się każe.', '', 0),
(20781, 'plPL', 'Ja głodny. Owoce wyglądać smacznie.', '', 0),
(20782, 'plPL', 'Mog\'dorg Sędziwy kazać Grok iść do miasto, szukać pomoc dla Krwawe Młoty. Grok iść.', '', 0),
(20783, 'plPL', 'Jak nikt nie pomóc, Grok rozwalić!', '', 0),
(20784, 'plPL', 'Klan Ostrza nie walczyć uczciwie. Mieć gronny do pomocy. Ty iść w Góry Klingi. Gadać z Mog\'dorg Sędziwy. Zabić gronny.', '', 0),
(20791, 'plPL', 'Niech żyje $N, $gnowy król:nowa królowa; ogrów!!!', '', 0),
(20985, 'plPL', 'Mogę cię uczyć jubilerstwa. Chcesz?', 'Mogę cię uczyć jubilerstwa. Chcesz?', 0),
(21002, 'plPL', '<Światło otaczające Xi\'ri pulsuje błękitem. Naaru wita cię jako sojusznika na polu bitwy.>', '', 0),
(21003, 'plPL', 'Jestem $ggotów:gotowa; dołączyć do twoich sił w bitwie, Xi\'ri.', 'Jestem $ggotów:gotowa; dołączyć do twoich sił w bitwie, Xi\'ri.', 0),
(21030, 'plPL', 'Pewnie zastanawiasz się, jak to możliwe, że mówię tak wyraźnie jak na ogra. To skutek uboczny działania kryształów rosnących na tarasie wokół Ogri\'la. Tamtejsze ogry podarowały mi ten kostur, a jego kryształ z kolei obdarował mój umysł.$B$BDzięki twoim dalszym działaniom tam w górze, w Ogri\'la, mam nadzieję pewnego dnia przynieść ten dar wszystkim moim ogrzym braciom. Dziękuję ci, $gmój królu:moja królowo;, za wszystko, co $gzrobiłeś:zrobiłaś; i jeszcze zrobisz.', '', 0),
(21293, 'plPL', 'Jeśli potrzebujesz odczynników, dobrze trafiasz. Lepszego wyboru nie znajdziesz w całym Shattrath.', '', 0),
(21307, 'plPL', 'Nie będę tego przeciągał dłużej, niż trzeba, lady Sinestro. Przykułaś moją uwagę, więc powiedz, czego chcesz od Smoczych Paszcz.', '', 0),
(21310, 'plPL', 'Pa... Pan? On żyje?', '', 0),
(21313, 'plPL', '%s się jąka.', '', 0),
(21314, 'plPL', 'T... Tak, tak... Oczywiście. Potrzebujemy stąd tylko kryształów i rudy. Jest... Będziemy potrzebować wierzchowców.', '', 0),
(21569, 'plPL', 'Zapomnienie posiadanej wiedzy to kosztowne przedsięwzięcie. Czy chcesz ponieść ten koszt?', 'Zapomnienie posiadanej wiedzy to kosztowne przedsięwzięcie. Czy chcesz ponieść ten koszt?', 0),
(21631, 'plPL', '<Nadrządca Mor\'ghor salutuje.>', '', 0),
(21798, 'plPL', 'Chodź, $N. Lord Burzogniewny czeka.', '', 0),
(21799, 'plPL', 'Wojownicy Smoczych Paszcz, zbierzcie się! Jeden z was osiągnął rangę najwyższego lorda! Skłońcie z szacunkiem głowy! Okażcie szacunek i wierność $gnajwyższemu lordowi:najwyższej lady; $N!', '', 0),
(21800, 'plPL', 'Lord Illidan zaraz tu będzie.', '', 0),
(21802, 'plPL', 'Chwała lordowi Illidanowi!', '', 0),
(21803, 'plPL', 'Lordzie Illidanie, oto ten wojownik Smoczych Paszcz, o którym ja i inni ci opowiadaliśmy. Poprowadzi nas do zwycięstwa!', '', 0),
(21805, 'plPL', 'Ale... Panie mój, nie rozumiem. $N... To ork, który...', '', 0),
(21823, 'plPL', 'Stanie się, mój panie.', '', 0),
(21824, 'plPL', 'Więc $gmyślałeś:myślałaś;, że zrobisz z Mor\'ghora głupca, co? Zanim zostaniesz $gwydany:wydana; lordowi Illidanowi, poczujesz ból, o którego istnieniu nie $gmiałeś:miałaś; pojęcia. Z przyjemnością wezmę na tobie własną zemstę.', '', 0),
(21829, 'plPL', 'Witaj, wędrowcze.', 'Witaj, wędrowcze.', 0),
(21873, 'plPL', '$GPodjąłem:Podjęłam; decyzję. Spraw, bym $gzapomniał:zapomniała; o moim mistrzostwie w alchemii!', '$GPodjąłem:Podjęłam; decyzję. Spraw, bym $gzapomniał:zapomniała; o moim mistrzostwie w alchemii!', 0),
(21875, 'plPL', 'Chcę oduczyć się mistrzostwa eliksirów.', 'Chcę oduczyć się mistrzostwa eliksirów.\n', 0),
(21912, 'plPL', 'Dostęp do moich towarów uzyskują tylko najbardziej doświadczeni łowcy sług Illidana.$B$BUznam cię za godnego, gdy twoja reputacja u Sha\'tar, Ekspedycji Cenariońskiej i Aldorów osiągnie poziom „Wywyższony”.', '', 0),
(21913, 'plPL', 'Dostęp do moich towarów uzyskują tylko najbardziej doświadczeni łowcy sług Illidana.$B$BUznam cię za godnego, gdy twoja reputacja u Sha\'tar, Ekspedycji Cenariońskiej i Widzących osiągnie poziom „Wywyższony”.', '', 0),
(21914, 'plPL', 'Witaj, $N. Przynieś mi znaki, którymi Illidan obdarza swoje najpotężniejsze sługi, a udostępnię ci moje alchemiczne towary.', '', 0),
(21915, 'plPL', 'Mam znaki do wymiany.', 'Mam znaki do wymiany.', 0),
(21917, 'plPL', 'Arakkoa się ukrywają... wszędzie!', '', 0),
(21950, 'plPL', 'Niewidoczni arakkoa... są wszędzie wokół nas... obserwują nas... czekają!', '', 0),
(22060, 'plPL', 'Czuję, że wojna jest tuż-tuż. Sprzedawczyni owoców zwerbowała do pomocy ogra. Ja też będę musiał kogoś zwerbować.', 'Czuję, że wojna jest tuż-tuż. Sprzedawczyni owoców zwerbowała do pomocy ogra. Ja też będę musiał kogoś zwerbować.', 0),
(22149, 'plPL', 'Nie widzisz, że mam dokąd iść i z kim się spotkać? Z drogi, wieśniaku!', '', 0),
(22150, 'plPL', 'Czekaj! Chcę kawy!', 'Czekaj! Chcę kawy!', 0),
(22178, 'plPL', '', 'Co podać, złotko?', 0),
(22179, 'plPL', 'Poproszę coś do picia.', 'Poproszę coś do picia.', 0),
(22180, 'plPL', '$GSłyszałem:Słyszałam;, że świetnie gotujesz.', '$GSłyszałem:Słyszałam;, że świetnie gotujesz.', 0),
(22181, 'plPL', '', 'Och, ja kucharką? No, chyba tak. Barmanka musi czasem popracować w kuchni, a przez lata nauczyłam się kilku przepisów. Nic nadzwyczajnego, ale są na tyle sycące, żeby napełnić pokaźny brzuch Groka.', 0),
(22182, 'plPL', 'Chętnie dowiem się więcej.', 'Chętnie dowiem się więcej.', 0),
(23107, 'plPL', 'Ciekawe.', 'Ciekawe.', 0),
(23330, 'plPL', 'Wiele jest rzadkich i cennych przedmiotów, których szukają moi klienci.$B$BTo ty możesz mi je przynosić, $N. W zamian zaoferuję ci to, czego pożądasz.$B$BPomówimy więcej o tym, co chcę dziś zdobyć?', '', 0),
(23331, 'plPL', 'Na wiatrach Otchłani szepcze się rozkaz, a Mah\'duun słyszy.$B$BPrzed Mah\'duunem staje $gmężczyzna:kobieta; i rozmawiają o tych, których śmierci wiatry dziś żądają.', '', 0),
(23989, 'plPL', 'Jeśli mamy odnieść sukces w tworzeniu portalu na Wyspę Quel\'Danas i do spoczywającej na niej Słonecznej Studni, musimy zdobyć źródło energii dość potężne, by uruchomić portal.$B$BNasze wysiłki są ukończone w $3269w procentach. Pomożesz nam, $N?', '', 0),
(23990, 'plPL', 'Ten portal nie jest taki jak inne, które prowadzą z powrotem do Azeroth. Aby go utrzymać, musimy zdobyć więcej ogniw many.$B$BAlbo to, albo ryzykujemy utratę dostępu do Wyspy Quel\'Danas i Słonecznej Studni.', '', 0),
(24222, 'plPL', 'Jakie wieści z walki o Zbrojownię Słonecznego Zasięgu?', 'Jakie wieści z walki o Zbrojownię Słonecznego Zasięgu?', 0),
(24223, 'plPL', 'Cieszę się, że pytasz. Nasze wysiłki, by zdobyć zbrojownię, osiągnęły $3233w procent zakładanego planu.$B$BWiem, że magini bitewna Arynna i Zwiastun Inuuro potrzebują twojej pomocy. Szukaj ich w Sanktuarium Słonecznego Zasięgu na Wyspie Quel\'Danas.', '', 0),
(24224, 'plPL', 'Jak blisko jesteśmy ukończenia kowadła i kuźni w Zbrojowni Słonecznego Zasięgu?', 'Jak blisko jesteśmy ukończenia kowadła i kuźni w Zbrojowni Słonecznego Zasięgu?', 0),
(24225, 'plPL', 'Kiedy ostatnio miałem wieści od Hauthaa, mówiła, że jesteśmy w $3228w procentach drogi do celu.$B$BNie potrafię wyrazić, jak istotne dla naszych wysiłków jest ich zbudowanie. Nasi żołnierze i żołnierki będą potrzebować lepszych zbroi i broni, a kowadło i kuźnia są do tego kluczem.$B$BKowalkę znajdziesz za Zbrojownią Słonecznego Zasięgu, $N.', '', 0),
(24226, 'plPL', 'Chcę cię zapytać o coś jeszcze.', 'Chcę cię zapytać o coś jeszcze.', 0),
(24227, 'plPL', 'Egzarcho, czy zdobyliśmy już Port Słonecznego Zasięgu?', 'Egzarcho, czy zdobyliśmy już Port Słonecznego Zasięgu?', 0),
(24228, 'plPL', 'Niestety, jeszcze nie zdobyliśmy portu. Według meldunków jesteśmy jednak w $3238w procentach drogi do celu.$B$B$N, jeśli chcesz pomóc, poszukaj magistra Ilastara i Obrońcy Kaalana w Zbrojowni Słonecznego Zasięgu na Wyspie Quel\'Danas.', '', 0),
(24229, 'plPL', 'Nasuunie, wiesz, ile jeszcze potrwa, zanim będziemy mieć pracownię alchemiczną w Porcie Słonecznego Zasięgu?', 'Nasuunie, wiesz, ile jeszcze potrwa, zanim będziemy mieć pracownię alchemiczną w Porcie Słonecznego Zasięgu?', 0),
(24230, 'plPL', 'Pracownia alchemiczna nie jest jeszcze gotowa, $N. Mar\'nah mówi jednak, że montaż jest ukończony w $3223w procentach.$B$BJeśli chcesz jej w tym pomóc, znajdziesz ją w karczmie w Porcie Słonecznego Zasięgu.', '', 0),
(24231, 'plPL', 'Co wiesz o niszczeniu magicznych bram na Płaskowyżu Słonecznej Studni?', 'Co wiesz o niszczeniu magicznych bram na Płaskowyżu Słonecznej Studni?', 0),
(24232, 'plPL', 'Próbujemy zburzyć Agamath, Pierwszą Bramę. Proszę, $N, udaj się na Wyspę Quel\'Danas i pomóż, jak tylko możesz!', '', 0),
(24233, 'plPL', 'Agamath, Pierwsza Brama, została przełamana, a dwie z poruczniczek Kil\'jaedena, lady Sacrolash i wielka czarnoksiężniczka Alythess, muszą zostać zniszczone.$B$BZbierz przyjaciół, $N, i dopilnuj tego! Naszym następnym celem jest Rohendor, Druga Brama.', '', 0),
(24234, 'plPL', 'Rohendor, Druga Brama, runął, ale ostatnia z magicznych barier Płaskowyżu Słonecznej Studni, Archonisus, wciąż nam się opiera, $N.$B$BNie ustawaj w wysiłkach i pomagaj przy Słonecznej Studni, jak tylko możesz.', '', 0),
(24247, 'plPL', 'Jeśli Kil\'jaeden wyłoni się ze Słonecznej Studni, nasz świat pogrąży się w wojnie, jakiej nie widziano od 10 000 lat!\n', '', 0),
(24353, 'plPL', 'Najlepszą obroną jest atak – każdy ci to powie.', '', 0),
(24354, 'plPL', '', 'Mocna broń na nic się nie zda, jeśli nie pożyjesz dość długo, by nią władać, $N.', 0),
(25073, 'plPL', 'Bądź $gpierwszy:pierwsza; w okolicy, kto ma niesamowity Elektrostatyczny Odplamiacz Blasterowy!', '', 0),
(25074, 'plPL', 'Opracowany na bazie najnowocześniejszej technologii wojskowej Ofensywy Straceńczego Słońca, bez trudu usuwa uporczywe plamy!', '', 0),
(25075, 'plPL', 'Plamy z wina, plamy z trawy, nawet plamy po zwierzakach nie mają szans z Elektrostatycznym Odplamiaczem Blasterowym!', '', 0),
(25076, 'plPL', 'Nie zwlekaj! Zamów teraz, a moją Ultrakinetyczną Gofrownicę otrzymasz bez dodatkowych opłat!', '', 0),
(25085, 'plPL', 'Hej, zwiastunie, jak idą badania? Jak szybko dostarczysz wyniki, może wpadnie ci Ultrakinetyczna Gofrownica!', '', 0),
(25086, 'plPL', 'Idą do przodu, Gofrosmaż. Nie masz przypadkiem jakiegoś pokazu produktu do zrobienia?', '', 0),
(25109, 'plPL', '', 'Ten świat został okaleczony w sposób, którego nasze oczy nie dostrzegają. Nawet upływ czasu wydaje się jakiś inny.', 0),
(25111, 'plPL', 'Zabierz mnie do Jaskiń Czasu.', 'Zabierz mnie do Jaskiń Czasu.', 0),
(25121, 'plPL', 'Mistrzowie bitewni areny', 'Mistrzowie bitewni areny', 0),
(25122, 'plPL', 'Mistrzowie bitewni areny są w południowo-wschodniej części Dolnego Miasta, pod murem.', 'Mistrzowie bitewni areny są w południowo-wschodniej części Dolnego Miasta, pod murem.', 0),
(25671, 'plPL', 'Wszystkie trzy bramy na Płaskowyżu Słonecznej Studni zostały zburzone, $N.$B$BMusisz zebrać siły i powstrzymać Kil\'jaedena, zanim wkroczy do Azeroth i wszystko przepadnie!', '', 0),
(28481, 'plPL', 'Już dziś w Shattrath: Taureńscy Wodzowie! Grają w tawernie „Koniec Świata” o pełnej godzinie!', '', 0),
(28496, 'plPL', 'Gotowi na rocka? To ruszajcie do tawerny „Koniec Świata”! Taureńscy Wodzowie zaczynają występ o pełnej godzinie.', '', 0),
(28502, 'plPL', 'Kto? Taureńscy Wodzowie! Co? Występ na żywo! Gdzie? Tawerna „Koniec Świata”! Kiedy? O pełnej godzinie! BĄDŹCIE TAM!', '', 0),
(28504, 'plPL', 'TAUREŃSCY WODZOWIE! Grają NA ŻYWO w TAWERNIE „KONIEC ŚWIATA”! Bądźcie tam o pełnej godzinie! Wygnano cię z Shattrath? WŚLIŹNIJ SIĘ Z POWROTEM!', '', 0),
(30147, 'plPL', 'Witaj, $N. ', '', 0),
(33637, 'plPL', 'Zgromadziłem tu być może największy zbiór wiedzy na całej Rubieży. Nawet wielkie biblioteki Srebrnej Luny bledną w porównaniu z nim.$B$BProszę... oglądaj, czytaj, przeglądaj do woli. Wszystko jest uporządkowane i wyraźnie opisane.', '', 0),
(34363, 'plPL', 'Twoja wola nie należy już do ciebie.', '', 0),
(45379, 'plPL', 'Lotmistrz', 'Lotmistrz', 0);
